import spidev
import time
import sqlite3
import sys

# Configuration
SPI_BUS = 0
SPI_DEVICE = 0
SPI_MAX_SPEED_HZ = 50000
ALERT_THRESHOLD_C = 100.0
DATABASE_NAME = 'wildlife_temp_data.db'

# MCP3008 channel for the temperature sensor
TEMP_SENSOR_CHANNEL = 0

# Global resources for cleanup
spi = None
db_conn = None

def init_spi():
    """Initialize the SPI interface for the MCP3008."""
    global spi
    try:
        spi = spidev.SpiDev()
        spi.open(SPI_BUS, SPI_DEVICE)
        spi.max_speed_hz = SPI_MAX_SPEED_HZ
        spi.mode = 0
        return True
    except Exception as e:
        print(f"Error initializing SPI: {e}", file=sys.stderr)
        return False

def init_database():
    """Initialize the SQLite database and create the table if it doesn't exist."""
    global db_conn
    try:
        db_conn = sqlite3.connect(DATABASE_NAME)
        cursor = db_conn.cursor()
        cursor.execute('''
            CREATE TABLE IF NOT EXISTS temperature_alerts (
                record_time TEXT,
                temp_reading REAL
            )
        ''')
        db_conn.commit()
        return True
    except sqlite3.Error as e:
        print(f"Error initializing database: {e}", file=sys.stderr)
        return False

def read_temperature():
    """Read the temperature from the MCP3008 ADC on the specified channel."""
    if spi is None:
        return None
    try:
        # MCP3008 single-ended read: start bit, config byte, don't-care byte
        resp = spi.xfer2([1, (8 + TEMP_SENSOR_CHANNEL) << 4, 0])
        # Extract 10-bit value: bits 9-2 from resp[1] (lower 2 bits) and all 8 from resp[2]
        raw_value = ((resp[1] & 0x03) << 8) + resp[2]
        return raw_value
    except Exception as e:
        print(f"Error reading temperature: {e}", file=sys.stderr)
        return None

def log_temperature_alert(temperature):
    """Log the temperature reading to the database and print an alert."""
    if db_conn is None:
        print("Database not available, cannot log alert.", file=sys.stderr)
        return
    try:
        timestamp = time.strftime('%Y-%m-%d %H:%M:%S')
        cursor = db_conn.cursor()
        cursor.execute(
            "INSERT INTO temperature_alerts (record_time, temp_reading) VALUES (?, ?)",
            (timestamp, temperature)
        )
        db_conn.commit()
        print(f"Alert: Temperature {temperature:.2f}°C at {timestamp}")
    except sqlite3.Error as e:
        print(f"Error logging temperature alert: {e}", file=sys.stderr)

def cleanup():
    """Close SPI and database connections."""
    global spi, db_conn
    if spi is not None:
        try:
            spi.close()
        except Exception:
            pass
        spi = None
    if db_conn is not None:
        try:
            db_conn.close()
        except Exception:
            pass
        db_conn = None

def main():
    """Main loop: read temperature, log alerts, handle errors."""
    if not init_spi():
        sys.exit(1)
    if not init_database():
        cleanup()
        sys.exit(1)

    try:
        while True:
            temperature = read_temperature()
            if temperature is not None:
                if temperature > ALERT_THRESHOLD_C:
                    log_temperature_alert(temperature)
            time.sleep(1)
    except KeyboardInterrupt:
        print("\nProgram terminated by user.")
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        cleanup()

if __name__ == "__main__":
    main()

