import argparse
import logging
import socket
import ssl
import sys
import time
import json
import spidev
import RPi.GPIO as GPIO

DEFAULT_CONFIG = {
    "moisture_threshold": 30,
    "web_port": 8080,
    "log_file": "irrigation.log",
    "valve_pin": 17,
    "spi_channel": 0,
}

def parse_arguments():
    parser = argparse.ArgumentParser(description="Smart Irrigation System")
    parser.add_argument("--moisture_threshold", type=int, default=DEFAULT_CONFIG["moisture_threshold"],
                        help="Moisture threshold for valve activation (default: 30)")
    parser.add_argument("--web_port", type=int, default=DEFAULT_CONFIG["web_port"],
                        help="Web socket port (default: 8080)")
    parser.add_argument("--log_file", type=str, default=DEFAULT_CONFIG["log_file"],
                        help="Log file path (default: irrigation.log)")
    parser.add_argument("--valve_pin", type=int, default=DEFAULT_CONFIG["valve_pin"],
                        help="GPIO pin for valve control (default: 17)")
    parser.add_argument("--spi_channel", type=int, default=DEFAULT_CONFIG["spi_channel"],
                        help="SPI channel for MCP3008 (default: 0)")
    return parser.parse_args()

def configure_logging(log_file):
    logging.basicConfig(filename=log_file, level=logging.INFO,
                        format='%(asctime)s - %(levelname)s - %(message)s')

def initialize_spi(channel):
    try:
        spi = spidev.SpiDev()
        spi.open(0, channel)
        spi.max_speed_hz = 1000000
        spi.mode = 0
        logging.info(f"SPI initialized on bus 0, device {channel}, mode 0, speed 1MHz")
        return spi
    except Exception as e:
        logging.error(f"Failed to initialize SPI: {e}")
        return None

def read_mcp3008(spi, channel):
    if spi is None:
        return None
    try:
        # MCP3008 single-ended read: start bit, config byte, don't-care byte
        adc = spi.xfer2([1, (8 + channel) << 4, 0])
        data = ((adc[1] & 3) << 8) + adc[2]
        return data
    except Exception as e:
        logging.error(f"SPI read error on channel {channel}: {e}")
        return None

def validate_moisture_reading(reading):
    if reading is None:
        return False
    if reading == 0 or reading == 2047:
        logging.warning("MCP3008 returned all-ones (sensor absent or short to GND)")
        return False
    if reading == 32767 or reading == -32768:
        logging.warning("MCP3008 returned all-zeros (sensor absent or short to VDD)")
        return False
    return True

def control_valve(valve_pin, state):
    try:
        GPIO.output(valve_pin, GPIO.HIGH if state else GPIO.LOW)
        logging.info(f"Valve {'OPENED' if state else 'CLOSED'}")
    except Exception as e:
        logging.error(f"Failed to control valve: {e}")

def get_moisture_level(spi, channel):
    reading = read_mcp3008(spi, channel)
    if reading is None:
        return None
    if not validate_moisture_reading(reading):
        return None
    return reading

def handle_client(conn, addr, moisture_level, valve_state, threshold):
    try:
        logging.info(f"Connected by {addr}")
        while True:
            data = conn.recv(1024).decode()
            if not data:
                break
            try:
                request = json.loads(data)
                if request.get("action") == "get_status":
                    response = {
                        "status": "ok",
                        "moisture": moisture_level,
                        "valve": valve_state,
                        "threshold": threshold,
                    }
                    conn.sendall(json.dumps(response).encode())
                elif request.get("action") == "toggle_valve":
                    new_state = not valve_state
                    control_valve(valve_pin, new_state)
                    valve_state = new_state
                    response = {
                        "status": "ok",
                        "moisture": moisture_level,
                        "valve": valve_state,
                        "threshold": threshold,
                    }
                    conn.sendall(json.dumps(response).encode())
                else:
                    response = {
                        "status": "error",
                        "message": "Invalid request",
                    }
                    conn.sendall(json.dumps(response).encode())
            except json.JSONDecodeError:
                response = {
                    "status": "error",
                    "message": "Invalid JSON",
                }
                conn.sendall(json.dumps(response).encode())
            except Exception as e:
                response = {
                    "status": "error",
                    "message": str(e),
                }
                conn.sendall(json.dumps(response).encode())
    except socket.timeout:
        pass
    except Exception as e:
        logging.error(f"Socket error handling client {addr}: {e}")
    finally:
        conn.close()
        logging.info(f"Connection closed by {addr}")

def main():
    args = parse_arguments()
    configure_logging(args.log_file)
    logging.info("Starting Smart Irrigation System")
    logging.info(f"Configuration: {args}")

    spi = initialize_spi(args.spi_channel)
    if spi is None:
        logging.error("Exiting due to SPI initialization failure")
        sys.exit(1)

    GPIO.setmode(GPIO.BCM)
    GPIO.setup(args.valve_pin, GPIO.OUT, initial=GPIO.LOW)
    logging.info(f"Valve pin {args.valve_pin} initialized as output")

    try:
        with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
            s.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
            s.bind(("", args.web_port))
            s.listen(5)
            s.settimeout(1.0)
            logging.info(f"Web socket server listening on port {args.web_port}")

            while True:
                moisture = get_moisture_level(spi, 0)
                if moisture is None:
                    time.sleep(5)
                    continue

                if moisture < args.moisture_threshold:
                    valve_state = True
                else:
                    valve_state = False

                if valve_state != GPIO.input(args.valve_pin):
                    control_valve(args.valve_pin, valve_state)
                    logging.info(f"Valve state changed to {'OPENED' if valve_state else 'CLOSED'}")

                if valve_state != GPIO.input(args.valve_pin):
                    logging.info("Valve toggled by web socket")
                    control_valve(args.valve_pin, not valve_state)

                if valve_state:
                    logging.info("Moisture below threshold, valve ON")
                else:
                    logging.info("Moisture above threshold, valve OFF")

                try:
                    conn, addr = s.accept()
                    handle_client(conn, addr, moisture, valve_state, args.moisture_threshold)
                except socket.timeout:
                    continue
                except Exception as e:
                    logging.error(f"Accept error: {e}")
    except KeyboardInterrupt:
        logging.info("Shutting down due to keyboard interrupt")
    except Exception as e:
        logging.error(f"Unexpected error: {e}")
    finally:
        if spi:
            spi.close()
        GPIO.cleanup()
        logging.info("GPIO cleaned up, system stopped")

if __name__ == "__main__":
    main()

