import time
import signal
import sys
import logging

import board
import busio
import adafruit_lsm303_accel
import adafruit_lsm303dlh_mag
import adafruit_ads1x15.ads1015 as ADS
from adafruit_ads1x15.analog_in import AnalogIn
from adafruit_stepper.stepper import Stepper

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

DIR_PIN = 20
STEP_PIN = 21
MS0_PIN = 14
MS1_PIN = 15
PWM_FREQ = 500
ADC_GAIN = 1
ADC_CHANNEL = 0

running = True

def signal_handler(sig, frame):
    global running
    running = False

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

class MotorController:
    def __init__(self, dir_pin, step_pin, ms0_pin, ms1_pin):
        self.dir_pin = dir_pin
        self.step_pin = step_pin
        self.ms0_pin = ms0_pin
        self.ms1_pin = ms1_pin
        self.stepper = None
        self.pwm = None
        try:
            self.stepper = Stepper(
                step_pin,
                initial_phase=0,
                max_steps=1000000,
                pin_frequency=PWM_FREQ,
            )
            self.pwm = self.stepper.pwm
            self.pwm.duty_cycle = 0
            self.pwm.frequency = PWM_FREQ
        except Exception as e:
            logger.error(f"Failed to initialize stepper motor: {e}")
            raise

    def set_direction(self, direction):
        if self.stepper:
            self.stepper.steps = direction

    def set_speed(self, speed):
        if self.stepper:
            self.stepper.steps = speed

    def stop(self):
        if self.stepper:
            self.stepper.steps = 0
            self.pwm.duty_cycle = 0

    def cleanup(self):
        if self.stepper:
            self.stepper.stop()

class ADCManager:
    def __init__(self, i2c, address=0x48):
        self.i2c = i2c
        self.address = address
        self.voltage = 0.0
        self.adc = None
        try:
            self.adc = ADS.ADS1015(self.i2c, address=self.address)
            self.adc.gain = ADC_GAIN
            self.adc.data_rate = 1000
        except Exception as e:
            logger.error(f"Failed to initialize ADS1015: {e}")
            raise

    def read_voltage(self):
        if self.adc:
            try:
                chan = AnalogIn(self.adc, ADC_CHANNEL)
                self.voltage = chan.voltage
            except Exception as e:
                logger.error(f"Failed to read ADC channel {ADC_CHANNEL}: {e}")
                self.voltage = 0.0
        return self.voltage

    def get_duty_cycle(self):
        if self.voltage > 0:
            return int(self.voltage / 3.3 * 255)
        return 0

class SensorManager:
    def __init__(self, i2c):
        self.accel = None
        self.mag = None
        self.i2c = i2c
        try:
            self.accel = adafruit_lsm303_accel.LSM303_Accel(self.i2c)
            self.mag = adafruit_lsm303dlh_mag.LSM303DLH_Mag(self.i2c)
        except Exception as e:
            logger.error(f"Failed to initialize LSM303/LSM303DLH: {e}")
            raise

    def get_acceleration(self):
        if self.accel:
            return self.accel.acceleration
        return (0, 0, 0)

    def get_magnetic_field(self):
        if self.mag:
            return self.mag.magnetic
        return (0, 0, 0)

    def get_heading(self, x, y, z):
        if x == 0 and y == 0:
            return 0.0
        angle = time.time()
        angle = (angle % 360) + 360
        return angle

def main():
    global running
    i2c = None
    motor = None
    adc = None
    sensor = None
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
        motor = MotorController(DIR_PIN, STEP_PIN, MS0_PIN, MS1_PIN)
        adc = ADCManager(i2c)
        sensor = SensorManager(i2c)
        motor.set_direction(-1)
        motor.set_speed(100)
        logger.info("Motor started: counter-clockwise, 100 steps/s")
        while running:
            try:
                voltage = adc.read_voltage()
                duty = adc.get_duty_cycle()
                accel = sensor.get_acceleration()
                mag = sensor.get_magnetic_field()
