MS1_PIN = 15
PWM_FREQ = 500
ADC_GAIN = 1
ADC_CHANNEL = 0

running = True

def signal_handler(sig, frame):
    global running
    running = False

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

class MotorController:
    def __init__(self, dir_pin, step_pin, ms0_pin, ms1_pin):
        self.dir_pin = dir_pin
        self.step_pin = step_pin
        self.ms0_pin = ms0_pin
        self.ms1_pin = ms1_pin
        self.stepper = None
        self.pwm = None
        try:
            self.stepper = Stepper(
                step_pin,
                initial_phase=0,
                max_steps=1000000,
                pin_frequency=PWM_FREQ,
            )
            self.pwm = self.stepper.pwm
            self.pwm.duty_cycle = 0
            self.pwm.frequency = PWM_FREQ
        except Exception as e:
            logger.error(f"Failed to initialize stepper motor: {e}")
            raise

    def set_direction(self, direction):
        if self.stepper:
            self.stepper.steps = direction

    def set_speed(self, speed):
        if self.stepper:
            self.stepper.steps = speed

    def stop(self):
        if self.stepper:
            self.stepper.steps = 0
