import time
import datetime
import os
import sys
import signal
import spidev
import RPi.GPIO as GPIO

# Configuration
DHT_PIN = 4
LED_PIN = 25
PUMP_PIN = 17
FAN_PIN = 27
LIGHT_PIN = 22
SPI_BUS = 0
SPI_DEVICE = 0
SPI_SPEED_HZ = 1000000
SPI_MODE = 0
SPI_BITS_PER_WORD = 8

# Global state
running = True
last_sensor_time = time.time()
last_actuator_time = time.time()
watchdog_timeout = 600

# Logging setup
log_file = "greenhouse.log"
def log_message(message):
    timestamp = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    try:
        with open(log_file, "a") as f:
            f.write(f"{timestamp} - {message}\n")
    except Exception as e:
        print(f"Error writing to log file: {e}")

# GPIO setup
def setup_gpio():
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(LED_PIN, GPIO.OUT, initial=GPIO.LOW)
        GPIO.setup(PUMP_PIN, GPIO.OUT, initial=GPIO.LOW)
        GPIO.setup(FAN_PIN, GPIO.OUT, initial=GPIO.LOW)
        GPIO.setup(LIGHT_PIN, GPIO.OUT, initial=GPIO.LOW)
        log_message("GPIO setup complete.")
    except Exception as e:
        log_message(f"GPIO setup failed: {e}")
        raise

# SPI setup
def setup_spi():
    try:
        spi = spidev.SpiDev()
        spi.open(SPI_BUS, SPI_DEVICE)
        spi.max_speed_hz = SPI_SPEED_HZ
        spi.mode = SPI_MODE
        spi.bits_per_word = SPI_BITS_PER_WORD
        log_message("SPI setup complete.")
        return spi
    except Exception as e:
        log_message(f"SPI setup failed: {e}")
        raise

# DHT22 sensor reading
def read_dht22(dht_device):
    try:
        # DHT22 requires a 1-second delay after power-up
        time.sleep(1)
        # Send start signal
        dht_device.writebytes([0x01, 0x00, 0x00])
        time.sleep(0.01)
        # Read 4 bytes
        data = dht_device.readbytes(4)
        if len(data) != 4:
            log_message("DHT22: Incomplete data read.")
            return None
        # Parse
        humidity = ((data[0] & 0x0F) << 16) | (data[1] << 8) | data[2]
        temperature = (((data[2] & 0xF0) << 8) | data[3]) >> 4
        if not (0 <= humidity <= 100 and -40 <= temperature <= 80):
            log_message("DHT22: Out-of-range values.")
            return None
        return {"humidity": humidity, "temperature": temperature}
    except Exception as e:
        log_message(f"DHT22 read error: {e}")
        return None

# MCP3008 ADC reading
def read_mcp3008(spi, channel):
    try:
        # MCP3008 single-ended read: start bit, config byte, don't-care
        adc = spi.xfer2([0x01, (0x08 | channel) << 4, 0x00])
        data = ((adc[1] & 0x03) << 8) | adc[2]
        return data
    except Exception as e:
        log_message(f"MCP3008 read error: {e}")
        return None

# Actuator control
def control_pump(command):
    try:
        if command == "on":
            GPIO.output(PUMP_PIN, GPIO.HIGH)
        elif command == "off":
            GPIO.output(PUMP_PIN, GPIO.LOW)
        else:
            log_message(f"Invalid pump command: {command}")
    except Exception as e:
        log_message(f"Pump control error: {e}")

def control_fan(command):
    try:
        if command == "on":
            GPIO.output(FAN_PIN, GPIO.HIGH)
        elif command == "off":
            GPIO.output(FAN_PIN, GPIO.LOW)
        else:
            log_message(f"Invalid fan command: {command}")
    except Exception as e:
        log_message(f"Fan control error: {e}")

def control_light(command):
    try:
        if command == "on":
            GPIO.output(LIGHT_PIN, GPIO.HIGH)
        elif command == "off":
            GPIO.output(LIGHT_PIN, GPIO.LOW)
        else:
            log_message(f"Invalid light command: {command}")
    except Exception as e:
        log_message(f"Light control error: {e}")

# LED status
def set_led_status(status):
    try:
        if status == "online":
            GPIO.output(LED_PIN, GPIO.HIGH)
        elif status == "offline":
            GPIO.output(LED_PIN, GPIO.LOW)
        elif status == "error":
            for _ in range(5):
                GPIO.output(LED_PIN, GPIO.HIGH)
                time.sleep(0.2)
                GPIO.output(LED_PIN, GPIO.LOW)
                time.sleep(0.2)
        elif status == "synchronizing":
            for _ in range(5):
                GPIO.output(LED_PIN, GPIO.HIGH)
                time.sleep(0.2)
                GPIO.output(LED_PIN, GPIO.LOW)
                time.sleep(0.2)
        else:
            log_message(f"Invalid LED status: {status}")
    except Exception as e:
        log_message(f"LED control error: {e}")

# Watchdog
def watchdog_check():
    global running
    if time.time() - last_actuator_time > watchdog_timeout:
        log_message("Watchdog timeout - restarting process.")
        os.execv(sys.executable, [sys.executable] + sys.argv)

# Signal handler
def signal_handler(signum, frame):
    global running
    running = False

# Main
def main():
    global running, last_sensor_time, last_actuator_time
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    try:
        setup_gpio()
        spi = setup_spi()
        log_message("Greenhouse controller started.")
        while running:
            # Check watchdog
            watchdog_check()
            # Read sensor
            sensor_data = read_dht22(dht_device)
            if sensor_data:
                last_sensor_time = time.time()
                log_message(f"Sensor data: {sensor_data}")
            else:
                log_message("No sensor data received.")
            # Check actuator
            if running:
                now = time.time()
                if now - last_actuator_time > 1:
                    log_message("Actuator timeout - checking sensor.")
                    # Re-read sensor to reset timeout
                    sensor_data = read_dht22(dht_device)
                    if sensor_data:
                        last_sensor_time = time.time()
                        log_message(f"Sensor data: {sensor_data}")
                    else:
                        log_message("No sensor data received after actuator timeout.")
                if sensor_data:
                    command = input("Enter actuator command (on/off): ").strip().lower()
                    if command:
                        control_pump(command)
                        control_fan(command)
                        control_light(command)
                        last_actuator_time = time.time()
                        log_message(f"Actuator command: {command}")
                else:
                    log_message("No sensor data received.")
            time.sleep(1)
    except Exception as e:
        log_message(f"Fatal error: {e}")
    finally:
        GPIO.cleanup()
        if spi:
            spi.close()
        log_message("Greenhouse controller stopped.")

if __name__ == "__main__":
    main()

