import time
import signal
import sys
import smbus2

# ADS1115 constants
ADS1115_I2C_ADDR = 0x48
ADS1115_REG_CONVERSION = 0x00
ADS1115_REG_CONFIG = 0x01

# Config register bit fields
ADS1115_OS_BEGIN = 0x8000
ADS1115_MUX_BASE = 0x4000  # Single-ended AINp vs GND
ADS1115_PGA_4_096V = 0x0200
ADS1115_MODE_SINGLE = 0x0100
ADS1115_DR_128_SPS = 0x0080
ADS1115_CQUE_NONE = 0x0003

# Full-scale range for PGA_4_096V: 4.096 V / 32768 = 0.125 V per LSB
ADS1115_FULLSCALE_VOLTS = 4.096

# Conversion timeout (seconds)
CONV_TIMEOUT = 0.1

# Poll interval (seconds)
POLL_INTERVAL = 0.1

# Number of full scan cycles before graceful exit
NUM_SCANS = 10

# Global flag for graceful shutdown
_running = True


def _signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for clean shutdown."""
    global _running
    _running = False


def _swap_bytes(word: int) -> int:
    """Swap the two bytes of a 16-bit word (ADS1115 is big-endian)."""
    return ((word & 0xFF00) >> 8) | ((word & 0x00FF) << 8)


def _build_config(channel: int) -> int:
    """Build the 16-bit config word for a single-ended channel."""
    if not 0 <= channel <= 3:
        raise ValueError(f"Invalid channel {channel}; must be 0-3.")
    return (
        ADS1115_OS_BEGIN
        | (ADS1115_MUX_BASE | (channel << 12))
        | ADS1115_PGA_4_096V
        | ADS1115_MODE_SINGLE
        | ADS1115_DR_128_SPS
        | ADS1115_CQUE_NONE
    )


def _read_config(bus: smbus2.SMBus) -> int:
    """Read the 16-bit config register."""
    return _swap_bytes(bus.read_word_data(ADS1115_I2C_ADDR, ADS1115_REG_CONFIG))


def _read_conversion(bus: smbus2.SMBus) -> int:
    """Read the 16-bit conversion register."""
    return _swap_bytes(bus.read_word_data(ADS1115_I2C_ADDR, ADS1115_REG_CONVERSION))


def _wait_for_conversion(bus: smbus2.SMBus, channel: int) -> bool:
    """Poll the config register until the conversion bit (bit 15) clears."""
    config = _read_config(bus)
    while config & ADS1115_OS_BEGIN:
        time.sleep(CONV_TIMEOUT)
        config = _read_config(bus)
    return config & ~ADS1115_OS_BEGIN


def read_adc(bus: smbus2.SMBus, channel: int) -> int:
    """Read a single-ended ADC value from the given channel."""
    if not _wait_for_conversion(bus, channel):
        raise TimeoutError(f"Conversion timeout on channel {channel}.")
    raw = _read_conversion(bus)
    if raw & 0x8000:
        raise OverflowError(f"Conversion result exceeds 16-bit range on channel {channel}.")
    return raw


def main() -> int:
    global _running

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        bus = smbus2.SMBus(1)
    except OSError as exc:
        print(f"Error: cannot open I2C bus 1: {exc}", file=sys.stderr)
        return 1

    try:
        while _running:
            readings = []
            for ch in range(4):
                try:
                    readings.append(read_adc(bus, ch))
                except (TimeoutError, OverflowError) as exc:
                    print(f"Error reading channel {ch}: {exc}", file=sys.stderr)

            print(f"Channel readings: {readings}")
            time.sleep(POLL_INTERVAL)

            if not _running:
                break

            for _ in range(NUM_SCANS):
                if not _running:
                    break
                for ch in range(4):
                    try:
                        read_adc(bus, ch)
                    except (TimeoutError, OverflowError) as exc:
                        print(f"Error reading channel {ch}: {exc}", file=sys.stderr)
                time.sleep(POLL_INTERVAL)

    finally:
        bus.close()
        print("\nI2C bus closed. Exiting.")

    return 0


if __name__ == "__main__":
    sys.exit(main())

