    try:
        i2c = busio.I2C(board.SCL, board.SDA)
        while not i2c.try_lock():
            time.sleep(0.01)
        try:
            return_list = i2c.scan()
        finally:
            i2c.unlock()
        if not return_list:
            raise RuntimeError("I2C bus not found")
        return i2c
    except Exception as e:
        print(f"I2C init error: {e}")
        sys.exit(1)

