        GPIO.setup(STEP_PIN, GPIO.OUT)
        GPIO.setup(MS0_PIN, GPIO.OUT)
        GPIO.setup(MS1_PIN, GPIO.OUT)
        pwm = GPIO.PWM(STEP_PIN, PWM_FREQ)
        pwm.start(0)
        GPIO.output(DIR_PIN, GPIO.LOW)
        GPIO.output(MS0_PIN, GPIO.LOW)
        GPIO.output(MS1_PIN, GPIO.LOW)
    except Exception as e:
        print(f"Motor init error: {e}")
        sys.exit(1)

def read_adc(ads, channel=0):
    try:
        return AnalogIn(ads, channel).value
    except Exception as e:
        print(f"ADC read error: {e}")
        return 0

def read_accelerometer(accel):
    try:
        return accel.acceleration
    except Exception as e:
        print(f"Accelerometer read error: {e}")
        return (0, 0, 0)

def read_heading(mag):
    try:
        return mag.magnetic_heading
    except Exception as e:
        print(f"Magnetometer read error: {e}")
        return 0

def set_motor_speed(pwm, speed):
    try:
        speed = max(0, min(255, int(speed)))
        pwm.ChangeDutyCycle(speed)
    except Exception as e:
        print(f"Motor speed error: {e}")

def main():
