    init_gpio()
    init_i2c()
    init_accelerometer()
    init_magnetometer()
    init_adc()
    init_motor()

    print("Starting main loop. Press Ctrl+C to exit.")
    try:
        while running:
            adc_value = read_adc(init_adc(), 0)
            voltage = adc_value * 4.096 / ADC_MAX_ADC
            pwm_duty_cycle = int(adc_value * 255 / ADC_MAX_ADC)
            set_motor_speed(pwm, pwm_duty_cycle)
            print(f"ADC: {adc_value}, Voltage: {voltage:.3f} V, PWM Duty Cycle: {pwm_duty_cycle}")

            accel_x, accel_y, accel_z = read_accelerometer(accel)
            print(f"Acceleration (m/s^2): X={accel_x:.3f}, Y={accel_y:.3f}, Z={accel_z:.3f}")

            heading = read_heading(mag)
            print(f"Heading: {heading:.0f} degrees")

            time.sleep(1)
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        cleanup()

if __name__ == "__main__":
    main()

