import argparse
import time
import logging
import queue
import threading
import spidev
import RPi.GPIO as GPIO

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')


class SoundSensor:
    """
    A class to represent a sound sensor on a Raspberry Pi.

    Supports both digital (e.g., KY-038) and analog (e.g., MCP3008) sound sensors.
    """

    def __init__(self, sensor_id, sensor_type, threshold, sample_rate, gpio_pins, channels, spi_speed=1000000, log_queue=None):
        self.sensor_id = sensor_id
        self.sensor_type = sensor_type
        self.threshold = threshold
        self.sample_rate = sample_rate
        self.gpio_pins = gpio_pins
        self.channels = channels
        self.spi_speed = spi_speed
        self.log_queue = log_queue
        self.running = False
        self.spi = None
        self.gpio_initialized = False
        self.gpio_initialized_error = None

        if self.sensor_type == "digital":
            self.gpio_pins = [int(p) for p in gpio_pins]
            self.gpio_initialized = True
            GPIO.setmode(GPIO.BCM)
            for pin in self.gpio_pins:
                GPIO.setup(pin, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
            self.gpio_initialized_error = None
        elif self.sensor_type == "analog":
            self.spi = spidev.SpiDev()
            self.spi.open(0, 0)
            self.spi.max_speed_hz = self.spi_speed
            self.spi.mode = 0
            self.channels = [int(ch) for ch in channels]
            self.running = True
            self.last_reading = None
        else:
            raise ValueError("Invalid sensor_type. Must be 'digital' or 'analog'.")

        if self.sensor_type == "analog":
            self.last_reading = self._read_analog_channel()

    def _read_analog_channel(self):
        """Reads the analog value from the specified MCP3008 channel in single-ended mode."""
        if self.spi is None:
            raise RuntimeError("SPI not initialized.")
        try:
            # MCP3008 command: start bit (1), single-ended mode (1), channel bits (3), dummy byte
            cmd = [1, (8 + self.channels[0]) << 4, 0]
            resp = self.spi.xfer2(cmd)
            adc_value = ((resp[1] & 3) << 8) + resp[2]
            return adc_value
        except Exception as e:
            logging.error(f"Error reading analog channel {self.channels[0]}: {e}")
            return None

    def _debounce(self):
        """Debounces the sensor reading by waiting for a short period."""
        time.sleep(0.1)

    def check_sound(self):
        """Checks for sound events based on the sensor type."""
        if self.sensor_type == "digital":
            try:
                if GPIO.input(self.gpio_pins[0]) == GPIO.HIGH:
                    self._log_event()
            except Exception as e:
                logging.error(f"Error reading digital sensor {self.sensor_id}: {e}")
        elif self.sensor_type == "analog":
            try:
                adc_value = self._read_analog_channel()
                if adc_value is not None:
                    if adc_value >= self.threshold:
                        self._log_event()
            except Exception as e:
                logging.error(f"Error reading analog sensor {self.sensor_id}: {e}")

    def _log_event(self):
        """Logs the detected sound event."""
        if self.log_queue:
            try:
                self.log_queue.put_nowait(f"Sound detected by sensor {self.sensor_id}")
            except queue.Full:
                logging.warning(f"Log queue for sensor {self.sensor_id} is full. Dropping event.")

    def start(self):
        """Starts the sensor reading loop in a separate thread."""
        if self.sensor_type == "digital":
            self.running = True
            try:
                while self.running:
                    self._debounce()
                    self.check_sound()
                    time.sleep(1 / self.sample_rate)
            except Exception as e:
                logging.error(f"Error in digital sensor {self.sensor_id} thread: {e}")
            finally:
                self.running = False
                self.cleanup()
        elif self.sensor_type == "analog":
            self.running = True
            try:
                while self.running:
                    self._debounce()
                    self.check_sound()
                    time.sleep(1 / self.sample_rate)
            except Exception as e:
                logging.error(f"Error in analog sensor {self.sensor_id} thread: {e}")
            finally:
                self.running = False
                self.cleanup()

    def stop(self):
        """Stops the sensor reading loop and performs cleanup."""
        self.running = False
        if self.spi:
            try:
                self.spi.close()
            except Exception as e:
                logging.error(f"Error closing SPI for sensor {self.sensor_id}: {e}")
        if self.gpio_initialized:
            try:
                GPIO.cleanup()
            except Exception as e:
                logging.error(f"Error cleaning up GPIO for sensor {self.sensor_id}: {e}")
        self.gpio_initialized = False

    def cleanup(self):
        """Performs any necessary cleanup for the sensor."""
        pass


def parse_arguments():
    parser = argparse.ArgumentParser(description="Raspberry Pi Sound Sensor Program")
    parser.add_argument("--sensor_type", required=True, help="Type of sound sensor (digital or analog)")
    parser.add_argument("--threshold", type=int, required=True, help="Sound level threshold for digital sensor")
    parser.add_argument("--sample_rate", type=int, required=True, help="Sampling rate for digital sensor")
    parser.add_argument("--log_file", type=str, required=True, help="Path to the log file")
    parser.add_argument("--gpio_pins", type=str, required=True, help="GPIO pins for digital sensor (comma-separated)")
    parser.add_argument("--channels", type=str, required=True, help="MCP3008 channels for analog sensor (comma-separated)")
    parser.add_argument("--spi_speed", type=int, default=1000000, help="SPI speed for analog sensor")
    parser.add_argument("--sensor_ids", type=str, required=True, help="Unique identifier for each sound sensor")
    return parser.parse_args()


def main():
    args = parse_arguments()
    sensors = {}
    try:
        sensor_ids = [int(id) for id in args.sensor_ids.split(",")]
        for sensor_id in sensor_ids:
            sensor_type = args.sensor_type
            threshold = args.threshold
            sample_rate = args.sample_rate
            gpio_pins = args.gpio_pins
            channels = args.channels
            spi_speed = args.spi_speed
            log_queue = args.log_file

            sensor = SoundSensor(
                sensor_id=sensor_id,
                sensor_type=sensor_type,
                threshold=threshold,
                sample_rate=sample_rate,
                gpio_pins=gpio_pins,
                channels=channels,
                spi_speed=spi_speed,
                log_queue=log_queue
            )
            sensor.start()
            sensors[sensor_id] = sensor

        while True:
            time.sleep(1)

    except KeyboardInterrupt:
        logging.info("Program terminated by user.")
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        for sensor in sensors.values():
            sensor.stop()
        logging.info("Program finished.")


if __name__ == "__main__":
    main()

