                logging.error(f"Error in digital sensor {self.sensor_id} thread: {e}")
            finally:
                self.running = False
                self.cleanup()
        elif self.sensor_type == "analog":
            self.running = True
            try:
                while self.running:
                    self._debounce()
                    self.check_sound()
                    time.sleep(1 / self.sample_rate)
            except Exception as e:
                logging.error(f"Error in analog sensor {self.sensor_id} thread: {e}")
            finally:
                self.running = False
                self.cleanup()

    def stop(self):
        """Stops the sensor reading loop and performs cleanup."""
        self.running = False
        if self.spi:
            try:
                self.spi.close()
            except Exception as e:
                logging.error(f"Error closing SPI for sensor {self.sensor_id}: {e}")
        if self.gpio_initialized:
            try:
                GPIO.cleanup()
            except Exception as e:
                logging.error(f"Error cleaning up GPIO for sensor {self.sensor_id}: {e}")
        self.gpio_initialized = False

    def cleanup(self):
        """Performs any necessary cleanup for the sensor."""
        pass


def parse_arguments():
    parser = argparse.ArgumentParser(description="Raspberry Pi Sound Sensor Program")
    parser.add_argument("--sensor_type", required=True, help="Type of sound sensor (digital or analog)")
    parser.add_argument("--threshold", type=int, required=True, help="Sound level threshold for digital sensor")
    parser.add_argument("--sample_rate", type=int, required=True, help="Sampling rate for digital sensor")
    parser.add_argument("--log_file", type=str, required=True, help="Path to the log file")
    parser.add_argument("--gpio_pins", type=str, required=True, help="GPIO pins for digital sensor (comma-separated)")
    parser.add_argument("--channels", type=str, required=True, help="MCP3008 channels for analog sensor (comma-separated)")
    parser.add_argument("--spi_speed", type=int, default=1000000, help="SPI speed for analog sensor")
    parser.add_argument("--sensor_ids", type=str, required=True, help="Unique identifier for each sound sensor")
    return parser.parse_args()


def main():
    args = parse_arguments()
    sensors = {}
    try:
        sensor_ids = [int(id) for id in args.sensor_ids.split(",")]
        for sensor_id in sensor_ids:
            sensor_type = args.sensor_type
            threshold = args.threshold
            sample_rate = args.sample_rate
            gpio_pins = args.gpio_pins
            channels = args.channels
            spi_speed = args.spi_speed
            log_queue = args.log_file

            sensor = SoundSensor(
                sensor_id=sensor_id,
                sensor_type=sensor_type,
                threshold=threshold,
                sample_rate=sample_rate,
                gpio_pins=gpio_pins,
                channels=channels,
                spi_speed=spi_speed,
                log_queue=log_queue
            )
            sensor.start()
            sensors[sensor_id] = sensor

        while True:
            time.sleep(1)

    except KeyboardInterrupt:
        logging.info("Program terminated by user.")
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        for sensor in sensors.values():
            sensor.stop()
        logging.info("Program finished.")


