import smbus
import time
import logging

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)


class ADS1x15:
    """
    ADS1x15 ADC driver for Raspberry Pi using smbus.
    Supports single-ended read on channels 0-3 with PGA scaling.
    """

    _ADS1115_ADDRESS = 0x48
    _REG_CONVERSION = 0x00
    _REG_CONFIG = 0x01

    _PGA_VALUES = {6144: 0x8000, 4096: 0x4000, 2048: 0x0000, 1024: 0x0000,
                   512: 0x0000, 256: 0x0000}

    def __init__(self, bus_number=1, address=0x48):
        self.address = address
        try:
            self.bus = smbus.SMBus(bus_number)
        except OSError as e:
            logger.error(f"Failed to open I2C bus {bus_number}: {e}")
            raise

    def _configure(self, channel, pga):
        if channel not in (0, 1, 2, 3):
            raise ValueError(f"Invalid channel {channel}; must be 0-3")
        if pga not in self._PGA_VALUES:
            raise ValueError(f"Invalid PGA {pga}; must be one of {list(self._PGA_VALUES.keys())}")

        config = self._PGA_VALUES[pga]
        config |= (channel << 12)
        config |= 0x8000  # Begin single conversion
        try:
            self.bus.write_i2c_block_data(self.address, self._REG_CONFIG, [config])
        except OSError as e:
            logger.error(f"I2C write failed (config ch={channel}, PGA={pga}): {e}")
            raise

    def _read_raw(self):
        try:
            data = self.bus.read_i2c_block_data(self.address, self._REG_CONVERSION, 2)
        except OSError as e:
            logger.error(f"I2C read failed: {e}")
            raise
        raw = (data[0] << 8) | data[1]
        if raw > 32767:
            raw -= 65536
        return raw

    def read(self, channel=0, pga=6144):
        self._configure(channel, pga)
        time.sleep(0.01)  # 10 ms conversion delay
        try:
            raw = self._read_raw()
        except OSError:
            raise
        if raw > 32767:
            raw -= 65536
        return raw * (1000.0 / self._PGA_VALUES[pga])

    def close(self):
        if hasattr(self, 'bus') and self.bus:
            try:
                self.bus.close()
            except OSError:
                pass
            self.bus = None


def main():
    adc = None
    try:
        adc = ADS1x15(bus_number=1, address=0x48)
        for ch, pga in [(0, 6144), (1, 4096), (2, 2048), (3, 1024)]:
            try:
                voltage = adc.read(channel=ch, pga=pga)
                logger.info(f"Channel {ch} (PGA {pga}mV): {voltage:.3f} mV")
            except Exception as e:
                logger.error(f"Read failed for ch={ch}, PGA={pga}: {e}")
    except Exception as e:
        logger.error(f"Initialization failed: {e}")
    finally:
        if adc:
            adc.close()


if __name__ == '__main__':
    main()

