import json
import time
import signal
import sys
import logging
import cv2
import numpy as np
from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class CameraHandler:
    def __init__(self, config):
        self.config = config
        self.camera = None
        self.running = True
        self.door_control = None
        self.door_pin = None
        self.bird_detected = False
        self.last_frame = None
        self.inference_lock = threading.Lock()
        self.inference_thread = None

    def initialize(self):
        try:
            self.camera = cv2.VideoCapture(self.config['camera_index'])
            if not self.camera.isOpened():
                raise RuntimeError("Failed to open camera.")
            self.camera.set(cv2.CAP_PROP_FRAME_WIDTH, self.config['preview_width'])
            self.camera.set(cv2.CAP_PROP_FRAME_HEIGHT, self.config['preview_height'])
            self.camera.set(cv2.CAP_PROP_FPS, self.config['preview_fps'])
            logging.info("Camera initialized successfully.")
        except Exception as e:
            logging.error(f"Error initializing camera: {e}")
            raise

    def capture_frame(self):
        if self.camera is None:
            return None
        ret, frame = self.camera.read()
        if not ret or frame is None:
            logging.warning("Failed to capture frame.")
            return None
        return frame

    def run_inference(self, frame):
        try:
            with self.inference_lock:
                if self.last_frame is None:
                    self.last_frame = frame
                else:
                    self.last_frame = cv2.absdiff(frame, self.last_frame)
                if self.last_frame.size == 0:
                    return False
                return self.detect_bird(self.last_frame)
        except Exception as e:
            logging.error(f"Error during inference: {e}")
            return False

    def detect_bird(self, frame):
        try:
            bird_cascade = cv2.CascadeClassifier(self.config['bird_cascade_filepath'])
            if bird_cascade.empty():
                logging.error("Failed to load bird cascade classifier.")
                return False
            gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
            birds = bird_cascade.detectMultiScale(gray, scaleFactor=1.1, minNeighbors=5, minSize=(30, 30))
            return len(birds) > 0
        except Exception as e:
            logging.error(f"Error detecting bird: {e}")
            return False

    def indicate_bird(self, led_pin):
        if self.bird_detected:
            logging.info("Bird detected! Indicating with LED.")
            try:
                self.door_control.on()
                time.sleep(1)
                self.door_control.off()
                self.bird_detected = False
            except GPIOZeroError as e:
                logging.error(f"Error controlling LED: {e}")
        else:
            logging.info("No bird detected.")

    def cleanup(self):
        logging.info("Cleaning up resources...")
        if self.camera is not None:
            self.camera.release()
            self.camera = None
        if self.door_control is not None:
            try:
                self.door_control.close()
            except Exception as e:
                logging.error(f"Error closing door control device: {e}")
            self.door_control = None

class DoorController:
    def __init__(self, config):
        self.config = config
        self.door_pin = None
        self.is_open = True
        self.door_control = None
        self.door_open_event = threading.Event()
        self.door_close_event = threading.Event()
        self.door_open_thread = None
        self.door_close_thread = None

    def initialize(self):
        try:
            self.door_pin = self.config['door_pin']
            self.door_control = OutputDevice(self.door_pin, active_high=True, initial_value=self.is_open)
            logging.info("Door controller initialized successfully.")
        except GPIOZeroError as e:
            logging.error(f"Error initializing door controller: {e}")
            raise

    def open_door(self):
        if self.door_control is not None:
            self.door_control.off()
            self.door_open_event.set()

    def close_door(self):
        if self.door_control is not None:
            self.door_control.on()
            self.door_close_event.set()

    def control_door(self):
        while self.config['door_control_enabled']:
            if self.door_open_event.is_set():
                self.open_door()
                self.door_open_event.clear()
            elif self.door_close_event.is_set():
                self.close_door()
                self.door_close_event.clear()
            time.sleep(0.1)

    def cleanup(self):
        logging.info("Cleaning up door controller...")
        if self.door_control is not None:
            try:
                self.door_control.close()
            except Exception as e:
                logging.error(f"Error closing door control device: {e}")
            self.door_control = None

def signal_handler(sig, frame):
    logging.info("Signal received, shutting down...")
    sys.exit(0)

def main():
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    config_file = 'config.json'
    try:
        with open(config_file, 'r') as f:
            config = json.load(f)
    except FileNotFoundError:
        logging.error(f"Config file not found: {config_file}")
        sys.exit(1)
    except json.JSONDecodeError:
        logging.error(f"Invalid JSON format in config file: {config_file}")
        sys.exit(1)

    camera_handler = CameraHandler(config)
    door_controller = DoorController(config)

    try:
        camera_handler.initialize()
        door_controller.initialize()

        if config['gpio_door_control']:
            door_controller.control_door()

        logging.info("Starting main loop...")
        while camera_handler.running:
            frame = camera_handler.capture_frame()
            if frame is not None:
                if camera_handler.running:
                    if camera_handler.run_inference(frame):
                        bird_detected = camera_handler.bird_detected
                        if bird_detected:
                            camera_handler.bird_detected = False
                            camera_handler.indicating_bird_led = True
                            camera_handler.indicating_bird_led_pin = 17
                            threading.Thread(target=camera_handler.indicating_bird_led_callback, args=(camera_handler.indicating_bird_led_pin,), daemon=True).start()
                time.sleep(0.1)
            else:
                logging.warning("Failed to capture frame. Retrying...")
                time.sleep(0.1)

    except Exception as e:
        logging.error(f"An error occurred: {e}")
    finally:
        camera_handler.cleanup()
        door_controller.cleanup()
        logging.info("Program terminated.")

if __name__ == "__main__":
    main()

