import sys

try:
    from picamera2 import Picamera2
except ImportError:
    logging.error("picamera2 library not found. Install with: pip install picamera2")
    sys.exit(1)

try:
    from gpiozero import LED
except ImportError:
    logging.error("gpiozero library not found. Install with: pip install gpiozero")
    sys.exit(1)

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class CameraMotionDetector:
    def __init__(self, config_file_path):
        self.config_file_path = config_file_path
        self.config = self.load_config()
        self.camera = None
        self.led = None
        self.frame_queue = queue.Queue(maxsize=self.config['queue_size'])
        self.running = True
        self.timer = None
        self.gpio_pin = self.config.get('gpio_pin', 17)
        self.led_activation_duration = self.config.get('led_activation_duration', 1)
        self.motion_detection_threshold = self.config.get('motion_detection_threshold', 50)
        self.camera_framerate = self.config.get('camera_framerate', 30)
        self.camera_resolution_width = self.config.get('camera_resolution_width', 640)
        self.camera_resolution_height = self.config.get('camera_resolution_height', 480)
        self.camera_warmup_time = self.config.get('camera_warmup_time', 2)
        self.camera_resolution = (self.camera_resolution_width, self.camera_resolution_height)
        self.camera_framerate_limit = self.config.get('camera_framerate_limit', 100)
        self.camera_warmup_time_start = time.time()

    def load_config(self):
        try:
            with open(self.config_file_path, 'r') as f:
                config = json.load(f)
            required_keys = ['queue_size', 'gpio_pin', 'led_activation_duration', 'motion_detection_threshold',
                             'camera_framerate', 'camera_resolution_width', 'camera_resolution_height',
                             'camera_warmup_time', 'camera_framerate_limit']
            for key in required_keys:
                if key not in config:
                    raise KeyError(f"Missing required config key: {key}")
            return config
        except FileNotFoundError:
            logging.error(f"Configuration file not found: {self.config_file_path}")
            sys.exit(1)
        except (json.JSONDecodeError, KeyError) as e:
            logging.error(f"Error parsing configuration file: {e}")
            sys.exit(1)

    def initialize_camera(self):
        try:
            self.camera = Picamera2()
            config = self.camera.create_still_configuration(main={"size": self.camera_resolution})
            self.camera.configure(config)
            self.camera.start()
            time.sleep(self.camera_warmup_time)
