import cv2
import time
import signal
import sys
import os

try:
    from gpiozero import LED, Button, Servo
    from gpiozero.exc import GPIOZeroError
except ImportError:
    print("Error: gpiozero is required. Install with: pip install gpiozero")
    sys.exit(0)

# Constants
CAMERA_INDEX = 0
CASCADE_FILE = "/home/raspberry/RaspPi_CV/haarcascade_frontalface_default.xml"
LED_PIN = 14
BUTTON_PIN = 15
SERVO_PIN = 18
WINDOW_NAME = "Human Detection"
FACE_SIZE = 32

# Global resources for cleanup
camera = None
led = None
button = None
servo = None
running = True


def signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for graceful shutdown."""
    global running
    print(f"\nReceived signal {signum}, shutting down...")
    running = False


def cleanup():
    """Release all resources safely."""
    global camera, led, button, servo
    if camera is not None:
        try:
            camera.release()
        except Exception:
            pass
        camera = None
    if led is not None:
        try:
            led.close()
        except Exception:
            pass
        led = None
    if button is not None:
        try:
            button.close()
        except Exception:
            pass
        button = None
    if servo is not None:
        try:
            servo.close()
        except Exception:
            pass
        servo = None
    cv2.destroyAllWindows()
    print("Resources released.")


def init_camera():
    """Initialize the camera; return the VideoCapture object or None on failure."""
    global camera
    try:
        camera = cv2.VideoCapture(CAMERA_INDEX)
        if not camera.isOpened():
            print(f"Error: Could not open camera at index {CAMERA_INDEX}.")
            return None
        return camera
    except Exception as e:
        print(f"Error initializing camera: {e}")
        return None


def init_gpio():
    """Initialize GPIO devices; return (led, button, servo) or (None, None, None) on failure."""
    global led, button, servo
    try:
        led = LED(LED_PIN)
        button = Button(BUTTON_PIN, pull_up=True)
        servo = Servo(SERVO_PIN)
        return led, button, servo
    except GPIOZeroError as e:
        print(f"Error initializing GPIO: {e}")
        return None, None, None
    except Exception as e:
        print(f"Unexpected error initializing GPIO: {e}")
        return None, None, None


def init_face_detector(cascade_file):
    """Load the face cascade classifier; return the classifier or None on failure."""
    global face_cascade
    try:
        face_cascade = cv2.CascadeClassifier(cascade_file)
        if face_cascade.empty():
            print(f"Error: Could not load face cascade from {cascade_file}.")
            return None
        return face_cascade
    except Exception as e:
        print(f"Error initializing face detector: {e}")
        return None


def process_frame(frame, face_cascade, led, button, servo):
    """Process a single frame: detect faces, update LED/button/servo, and draw rectangles."""
    global running
    if not running:
        return

    try:
        resized_frame = cv2.resize(frame, (FACE_SIZE, FACE_SIZE))
        gray_frame = cv2.cvtColor(resized_frame, cv2.COLOR_BGR2GRAY)

        faces = face_cascade.detectMultiScale(
            gray_frame, scaleFactor=1.1, minNeighbors=5, minSize=(30, 30)
        )

        if len(faces) > 0:
            led.on()
            button.on()
            servo_angle = 0
            if any(
                (x + FACE_SIZE / 2) > FACE_SIZE / 2
                for x, y in faces
            ):
                servo_angle += 20
            if any(
                (x + FACE_SIZE / 2) < FACE_SIZE / 2
                for x, y in faces
            ):
                servo_angle -= 20
            servo_angle = max(0, min(180, servo_angle))
            servo.value = servo_angle / 180.0
            print("Face detected!")
        else:
            led.off()
            button.off()
            print("No face detected.")

        for (x, y, w, h) in faces:
            cv2.rectangle(resized_frame, (x, y), (x + w, y + h), (255, 0, 0), 2)

        cv2.imshow(WINDOW_NAME, resized_frame)

    except Exception as e:
        print(f"Error processing frame: {e}")
        running = False


def main():
    """Main entry point: initialize, run, and clean up."""
    global running

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    camera = init_camera()
    if camera is None:
        print("Error: Camera initialization failed. Exiting.")
        sys.exit(0)

    led, button, servo = init_gpio()
    if led is None or button is None or servo is None:
        print("Warning: GPIO initialization failed. Continuing without GPIO control.")

    face_cascade = init_face_detector(CASCADE_FILE)
    if face_cascade is None:
        print("Warning: Face detector initialization failed. Continuing without face detection.")

    try:
        while running:
            ret, frame = camera.read()
            if not ret:
                print("Error: Could not read frame from camera.")
                break

            process_frame(frame, face_cascade, led, button, servo)

            if cv2.waitKey(1) & 0xFF == ord('q'):
                break

    except Exception as e:
        print(f"An error occurred during the main loop: {e}")
    finally:
        cleanup()


if __name__ == "__main__":
    main()

