import time
import datetime
import sqlite3
import logging
import signal
import sys
import os
from typing import Optional, Dict, Any, List

try:
    import smbus2
except ImportError:
    smbus2 = None

try:
    from adafruit_bmp280 import BMP280
except ImportError:
    BMP280 = None

try:
    from adafruit_bme280 import BME280
except ImportError:
    BME280 = None

try:
    from adafruit_ms8607 import MS8607
except ImportError:
    MS8607 = None

# Constants
DEFAULT_SAMPLING_INTERVAL = 60
DATABASE_NAME = 'wildlife_data.db'
ERROR_LOG_FILE = 'error.log'
I2C_BUS = 1

# Global state
running = True
db_connection: Optional[sqlite3.Connection] = None

# Configure logging
logging.basicConfig(
    filename=ERROR_LOG_FILE,
    level=logging.ERROR,
    format='%(asctime)s - %(levelname)s - %(message)s'
)

# Global sensor configuration
sensor_config: Dict[str, Dict[str, Any]] = {
    'Sensor1': {'type': 'BMP280', 'address': 0x76, 'id': 'Sensor1'},
    'Sensor2': {'type': 'BME280', 'address': 0x76, 'id': 'Sensor2'},
    'Sensor3': {'type': 'MS8607', 'address': 0x76, 'id': 'Sensor3'},
}

# Global sensor objects
sensors: Dict[str, Any] = {}

# Signal handler for graceful shutdown
def signal_handler(sig, frame):
    global running
    running = False

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)


def initialize_database() -> bool:
    """Initialize the SQLite database and create the sensor_data table if it doesn't exist."""
    global db_connection
    try:
        db_connection = sqlite3.connect(DATABASE_NAME)
        cursor = db_connection.cursor()
        cursor.execute('''
            CREATE TABLE IF NOT EXISTS sensor_data (
                timestamp TEXT PRIMARY KEY,
                sensor_type TEXT,
                sensor_id TEXT,
                pressure_pa REAL,
                temperature_c REAL,
                humidity_percent REAL
            )
        ''')
        db_connection.commit()
        logging.info("Database initialized successfully.")
        return True
    except sqlite3.Error as e:
        logging.error(f"Database initialization error: {e}")
        return False


def read_sensor_data(sensor_id: str, sensor_type: str) -> Optional[Dict[str, Any]]:
    """Read data from a specific sensor. Returns validated data or None."""
    if sensor_type not in sensors:
        logging.error(f"Sensor type '{sensor_type}' not found in config.")
        return None

    if sensor_id not in sensors[sensor_type]:
        logging.error(f"Sensor ID '{sensor_id}' not found for type '{sensor_type}'.")
        return None

    sensor = sensors[sensor_type][sensor_id]

    if sensor_type == 'BMP280':
        if not isinstance(sensor, BMP280):
            logging.error(f"BMP280 sensor not initialized.")
            return None
        try:
            pressure = sensor.pressure
            temperature = sensor.temperature
            return {
                'timestamp': datetime.datetime.now().isoformat(),
                'sensor_type': sensor_type,
                'sensor_id': sensor_id,
                'pressure_pa': pressure,
                'temperature_c': temperature,
            }
        except Exception as e:
            logging.error(f"Error reading BMP280 sensor '{sensor_id}': {e}")
            return None
    elif sensor_type == 'BME280':
        if not isinstance(sensor, BME280):
            logging.error(f"BME280 sensor not initialized.")
            return None
        try:
            pressure = sensor.pressure
            temperature = sensor.temperature
            humidity = sensor.humidity
            return {
                'timestamp': datetime.datetime.now().isoformat(),
                'sensor_type': sensor_type,
                'sensor_id': sensor_id,
                'pressure_pa': pressure,
                'temperature_c': temperature,
                'humidity_percent': humidity,
            }
        except Exception as e:
            logging.error(f"Error reading BME280 sensor '{sensor_id}': {e}")
            return None
    elif sensor_type == 'MS8607':
        if not isinstance(sensor, MS8607):
            logging.error(f"MS8607 sensor not initialized.")
            return None
        try:
            pressure = sensor.pressure
            temperature = sensor.temperature
            humidity = sensor.relative_humidity
            return {
                'timestamp': datetime.datetime.now().isoformat(),
                'sensor_type': sensor_type,
                'sensor_id': sensor_id,
                'pressure_pa': pressure,
                'temperature_c': temperature,
                'humidity_percent': humidity,
            }
        except Exception as e:
            logging.error(f"Error reading MS8607 sensor '{sensor_id}': {e}")
            return None
    else:
        logging.error(f"Unsupported sensor type: {sensor_type}")
        return None


def validate_data(data: Dict[str, Any]) -> bool:
    """Validate sensor readings against predefined ranges."""
    if not isinstance(data, dict):
        return False

    pressure_pa = data.get('pressure_pa')
    temperature_c = data.get('temperature_c')
    humidity_percent = data.get('humidity_percent')

    if pressure_pa is not None:
        if not (70000 <= pressure_pa <= 110000):
            logging.warning(f"Invalid pressure reading: {pressure_pa} Pa")
            return False
    if temperature_c is not None:
        if not (-20 <= temperature_c <= 50):
            logging.warning(f"Invalid temperature reading: {temperature_c} °C")
            return False
    if humidity_percent is not None:
        if not (0 <= humidity_percent <= 100):
