    sys.exit(1)

SERIAL_PORT = "/dev/serial0"
BAUD_RATE = 9600
LOG_FILE = "distance_log.txt"
READ_INTERVAL = 1.0

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def log_distance(distance_cm):
    timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    log_entry = f"{timestamp},{distance_cm}\n"
    try:
        with open(LOG_FILE, "a", encoding="utf-8") as logfile:
            logfile.write(log_entry)
            logfile.flush()
    except OSError as e:
        print(f"Error writing to log file: {e}", file=sys.stderr)
    print(log_entry, end="")


def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        ser = serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=1.0,
        )
    except serial.SerialException as e:
        print(f"Error opening serial port {SERIAL_PORT}: {e}", file=sys.stderr)
        sys.exit(1)

    print(f"Connected to {SERIAL_PORT} at {BAUD_RATE} baud. Press Ctrl+C to stop.")

    try:
        while _running:
            try:
                raw = ser.readline()
            except serial.SerialException as e:
                print(f"Serial read error: {e}", file=sys.stderr)
                time.sleep(READ_INTERVAL)
                continue

            if not raw:
                continue

            try:
                line = raw.decode("ascii", errors="replace").strip()
            except Exception:
                continue

            if not line:
                continue

            try:
                distance_cm = float(line)
            except ValueError:
                print(f"Invalid data received (not a float): '{line}'", file=sys.stderr)
                continue

            log_distance(distance_cm)

            time.sleep(READ_INTERVAL)
    finally:
        try:
            ser.close()
        except Exception:
            pass
        print("\nSerial port closed. Exiting.")


if __name__ == "__main__":
    main()

