import time
import os
import signal
import sys
import json
from typing import Optional, Tuple, List

try:
    from picamera2 import Picamera2
except ImportError:
    Picamera2 = None

try:
    from gpiozero import OutputDevice, InputDevice
except ImportError:
    OutputDevice = None
    InputDevice = None

# Constants for GPIO pin numbers (BCM numbering)
X_DIR_PIN = 17
X_STEP_PIN = 18
X_ENABLE_PIN = 27
Y_DIR_PIN = 22
Y_STEP_PIN = 23
Y_ENABLE_PIN = 24
X_LIMIT_SWITCH_PIN = 5
Y_LIMIT_SWITCH_PIN = 6

# Global state
running = True
camera: Optional[Picamera2] = None
x_dir = None
x_step = None
x_enable = None
y_dir = None
y_step = None
y_enable = None
x_position = 0
y_position = 0

# Limit switch states for safety
_x_triggered = False
_y_triggered = False

# Global flag to indicate a scan is in progress
_scan_in_progress = False


def signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for graceful shutdown."""
    global running
    running = False


def cleanup():
    """Release all resources and disable motors."""
    global camera, x_dir, x_step, x_enable, y_dir, y_step, y_enable
    if camera is not None:
        try:
            camera.stop()
            camera.close()
        except Exception:
            pass
        camera = None
    for dev in [x_dir, x_step, x_enable, y_dir, y_step, y_enable]:
        if dev is not None:
            try:
                dev.close()
            except Exception:
                pass
    x_dir = x_step = x_enable = y_dir = y_step = y_enable = None


def move_steps(motor, direction, steps, delay):
    """Moves the specified motor a given number of steps in the specified direction."""
    global _scan_in_progress
    if not running:
        return
    if motor == "X":
        dir_pin, step_pin, enable_pin = X_DIR_PIN, X_STEP_PIN, X_ENABLE_PIN
    elif motor == "Y":
        dir_pin, step_pin, enable_pin = Y_DIR_PIN, Y_STEP_PIN, Y_ENABLE_PIN
    else:
        return

    if direction == 0:
        dir_pin.off()
    else:
        dir_pin.on()

    enable_pin.off()  # Enable motor (active-low)
    for _ in range(steps):
        if not running:
            return
        step_pin.on()
        time.sleep(delay)
        step_pin.off()
        time.sleep(delay)
    enable_pin.on()  # Disable motor
    if motor == "X":
        x_position = steps
    elif motor == "Y":
        y_position = steps
    _scan_in_progress = True


def home_stage():
    """Moves the stage to its home position (limit switch triggered)."""
    global _x_triggered, _y_triggered
    if _x_triggered or _y_triggered:
        print("Stage already at home position.")
        return
    print("Moving to home position...")
    move_steps("X", 0, 1000, 0.0005)
    move_steps("Y", 0, 1000, 0.0005)
    if not running:
        return
    if X_LIMIT_SWITCH_PIN.value == 0:
        print("X limit switch triggered.")
        move_steps("X", 1, 1000, 0.0005)
    if Y_LIMIT_SWITCH_PIN.value == 0:
        print("Y limit switch triggered.")
        move_steps("Y", 1, 1000, 0.0005)
    move_steps("X", 0, 1000, 0.0005)
    move_steps("Y", 0, 1000, 0.0005)
    if not running:
        return
    _x_triggered = X_LIMIT_SWITCH_PIN.value == 0
    _y_triggered = Y_LIMIT_SWITCH_PIN.value == 0
    print("Stage at home position.")


def capture_image(x, y, image_dir):
    """Captures an image at the specified coordinates and saves it with metadata."""
    global camera
    if not running:
        return
    if camera is None:
        print("Camera not initialized.")
        return
    try:
        image_path = os.path.join(image_dir, f"image_{x}_{y}.jpg")
        camera.capture_file(image_path)
        print(f"Captured image: {image_path}")
    except Exception as e:
        print(f"Error capturing image: {e}")


def run_scan(start_x, start_y, end_x, end_y, step_size, image_dir):
    """Runs a full scan from start_x, start_y to end_x, end_y in step_size increments."""
    global _scan_in_progress
    if not running:
        return
    if step_size <= 0:
        print("Step size must be positive.")
        return
    if start_x < 0 or start_y < 0 or end_x > 1023 or end_y > 1023:
        print("Coordinates out of range.")
        return
    if not os.path.exists(image_dir):
        print(f"Image directory does not exist: {image_dir}")
        return
    try:
        for x in range(start_x, end_x + 1, step_size):
            if not running:
                return
            if _scan_in_progress:
                break
            move_steps("X", 1, step_size, 0.0005)
            if not running:
                return
            if y_limit_switch_triggered:
                print("Y limit switch triggered. Aborting scan.")
                break
            capture_image(x, start_y, image_dir)
    except Exception as e:
        print(f"Error during scan: {e}")
    finally:
        _scan_in_progress = False


def get_user_input():
    """Gets user input for coordinates and other parameters."""
    global start_x, start_y, end_x, end_y, step_size, image_dir
    try:
        start_x = int(input("Enter start X coordinate (0-1023): "))
        start_y = int(input("Enter start Y coordinate (0-1023): "))
        end_x = int(input("Enter end X coordinate (0-1023): "))
        end_y = int(input("Enter end Y coordinate (0-1023): "))
        step_size = int(input("Enter step size (1-1023): "))
        if step_size <= 0:
            print("Step size must be positive.")
            return
        image_dir = input("Enter image directory path: ").strip()
        if not image_dir:
            print("Image directory path cannot be empty.")
            return
        if not os.path.exists(image_dir):
            os.makedirs(image_dir)
    except ValueError:
        print("Invalid input. Please enter an integer.")
        return
    except EOFError:
        print("\nNo input received. Exiting.")
        return


def main_menu():
    """Displays and processes the main menu for the user."""
    global running
    while running:
        print("\n=== Main Menu ===")
        print("1. Home Stage")
        print("2. Run Scan")
        print("3. Exit")
        choice = input("Enter your choice: ")
        if choice == "1":
            home_stage()
        elif choice == "2":
            start_x = int(input("Enter start X coordinate (0-1023): "))
