            return
        image_dir = input("Enter image directory path: ").strip()
        if not image_dir:
            print("Image directory path cannot be empty.")
            return
        if not os.path.exists(image_dir):
            os.makedirs(image_dir)
    except ValueError:
        print("Invalid input. Please enter an integer.")
        return
    except EOFError:
        print("\nNo input received. Exiting.")
        return


def main_menu():
    """Displays and processes the main menu for the user."""
    global running
    while running:
        print("\n=== Main Menu ===")
        print("1. Home Stage")
        print("2. Run Scan")
