#!/usr/bin/env python3
"""
Hydroponics Monitoring System for Raspberry Pi 4 Model B

Simulates temperature, pH, and EC sensors with a DS18B20 fallback via 1-Wire.
Drives an alert LED on BCM pin 17.  All messages are logged to CSV and a
rotating-file log.

Usage:
    python3 hydroponics.py --config hydroponics_config.txt
"""

import csv
import datetime
import logging
import logging.handlers
import os
import random
import signal
import sys
import time

import w1thermsensor
from w1thermsensor import W1ThermSensor

try:
    from gpiozero import LED
    from gpiozero.exc import GPIOZeroError
except ImportError:
    LED = None
    GPIOZeroError = Exception

# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------
CONFIG_FILE = "hydroponics_config.txt"
LOG_FILE = "hydroponics_system.log"
LOG_FILE_MAX_BYTES = 1024 * 1024  # 1 MB
LOG_FILE_BACKUP_COUNT = 7
CSV_FILE = "hydroponics_log.csv"

DEFAULT_CONFIG = {
    "temperature_threshold_high": 25.0,
    "temperature_threshold_low": 18.0,
    "ph_threshold_high": 6.5,
    "ph_threshold_low": 5.5,
    "ec_threshold_high": 2.0,
    "ec_threshold_low": 1.0,
    "temperature_offset": 0.0,
    "ph_offset": 0.0,
    "ec_offset": 0.0,
    "temperature_gain": 1.0,
    "ph_gain": 1.0,
    "ec_gain": 1.0,
}

# ---------------------------------------------------------------------------
# Globals for cleanup
# ---------------------------------------------------------------------------
_running = True
_alert_led = None


def _signal_handler(signum, frame):
    """Handle SIGINT / SIGTERM for graceful shutdown."""
    global _running
    _running = False


def _read_config(path: str) -> dict:
    """Read and validate the configuration file; return a copy so the
    caller may modify the returned dict without affecting the file."""
    cfg = dict(DEFAULT_CONFIG)
    try:
        with open(path, "r") as f:
            for line in f:
                line = line.strip()
                if not line or line.startswith("#"):
                    continue
                if "=" not in line:
                    raise ValueError(f"Malformed config line: {line!r}")
                key, value = line.split("=", 1)
                key = key.strip()
                value = value.strip()
                if key in cfg:
                    try:
                        cfg[key] = float(value)
                    except ValueError:
                        raise ValueError(f"Invalid value for {key}: {value!r}")
    except FileNotFoundError:
        logging.warning("Configuration file not found: %s", path)
    except (ValueError, OSError) as exc:
        logging.error("Error reading configuration: %s", exc)
    return cfg


def _read_calibration(path: str) -> dict:
    """Read calibration offsets and gains from the config file."""
    cfg = dict(DEFAULT_CONFIG)
    try:
        with open(path, "r") as f:
            for line in f:
                line = line.strip()
                if not line or line.startswith("#"):
                    continue
                if "=" not in line:
                    continue
                key, value = line.split("=", 1)
                key = key.strip()
                if key in ("temperature_offset", "ph_offset", "ec_offset"):
                    try:
                        cfg[key] = float(value)
                    except ValueError:
                        raise ValueError(f"Invalid offset/gain value: {value!r}")
                elif key in ("temperature_gain", "ph_gain", "ec_gain"):
                    try:
                        cfg[key] = float(value)
                    except ValueError:
                        raise ValueError(f"Invalid gain value: {value!r}")
    except FileNotFoundError:
        logging.warning("Calibration file not found: %s", path)
    except (ValueError, OSError) as exc:
        logging.error("Error reading calibration: %s", exc)
    return cfg


def _read_thresholds(path: str) -> dict:
    """Read threshold limits from the config file."""
    cfg = dict(DEFAULT_CONFIG)
    try:
        with open(path, "r") as f:
            for line in f:
                line = line.strip()
                if not line or line.startswith("#"):
                    continue
                if "=" not in line:
                    continue
                key, value = line.split("=", 1)
                key = key.strip()
                if key in ("temperature_threshold_high", "temperature_threshold_low"):
                    try:
                        cfg[key] = float(value)
                    except ValueError:
                        raise ValueError(f"Invalid threshold value: {value!r}")
                elif key in ("ph_threshold_high", "ph_threshold_low"):
                    try:
                        cfg[key] = float(value)
                    except ValueError:
                        raise ValueError(f"Invalid threshold value: {value!r}")
                elif key in ("ec_threshold_high", "ec_threshold_low"):
                    try:
                        cfg[key] = float(value)
                    except ValueError:
                        raise ValueError(f"Invalid threshold value: {value!r}")
    except FileNotFoundError:
        logging.warning("Thresholds file not found: %s", path)
    except (ValueError, OSError) as exc:
        logging.error("Error reading thresholds: %s", exc)
    return cfg


def _read_log_level(path: str) -> str:
    """Read the log level from the config file."""
    cfg = dict(DEFAULT_CONFIG)
    try:
        with open(path, "r") as f:
            for line in f:
                line = line.strip()
                if not line or line.startswith("#"):
                    continue
                if "=" not in line:
                    continue
                key, value = line.split("=", 1)
                key = key.strip()
                if key == "log_level":
                    try:
                        cfg["log_level"] = value.strip()
                    except ValueError:
                        raise ValueError(f"Invalid log level: {value!r}")
    except FileNotFoundError:
        logging.warning("Log level file not found: %s", path)
    except (ValueError, OSError) as exc:
        logging.error("Error reading log level: %s", exc)
    return cfg.get("log_level", "INFO")


def _read_csv_file(path: str) -> list:
    """Read existing CSV lines into a list of dicts."""
    if not os.path.isfile(path):
        return []
    try:
        with open(path, "r", newline="") as f:
            reader = csv.DictReader(f)
            return [row for row in reader]
    except (OSError, csv.Error) as exc:
        logging.error("Error reading CSV file: %s", exc)
        return []


def _write_csv_file(path: str, data: list) -> None:
    """Append a row to the CSV file."""
    try:
        with open(path, "a", newline="") as f:
            csv.writer(f).writerows(data)
    except (OSError, csv.Error) as exc:
        logging.error("Error writing to CSV file: %s", exc)


def _read_alert_led_pin(pin: int) -> LED:
    """Initialise the alert LED on the given BCM pin."""
    if LED is None:
        logging.error("gpiozero not available; cannot initialise alert LED.")
        return None
    try:
        led = LED(pin)
        led.off()
        return led
    except GPIOZeroError as exc:
        logging.error("Failed to initialise alert LED on BCM %d: %s", pin, exc)
        return None


def _blink_alert_led(led: LED, cycles: int = 3, on_time: float = 0.5, off_time: float = 0.5) -> None:
    """Blink the alert LED for the given number of cycles."""
    if led is None:
        return
    for _ in range(cycles):
        if not _running:
            break
        led.on()
        time.sleep(on_time)
        led.off()
        time.sleep(off_time)


def _read_temperature(offset: float, gain: float) -> float:
    """Simulate a temperature reading in °C."""
    return random.uniform(15.0, 30.0) + offset * gain


def _read_ph(offset: float, gain: float) -> float:
    """Simulate a pH reading in pH units."""
    return random.uniform(5.5, 6.5) + offset * gain


def _read_ec(offset: float, gain: float) -> float:
    """Simulate an EC reading in mS/cm."""
    return random.uniform(1.0, 2.0) + offset * gain


def _validate_reading(reading: float, threshold: float, threshold_type: str,
                      offset: float, gain: float) -> bool:
    """Return True if the reading is within the configured limits."""
    if threshold_type == "high":
        return reading <= threshold
    if threshold_type == "low":
        return reading >= threshold
    return True


def _generate_csv_header() -> list:
    """Return the CSV header row."""
    return ["Timestamp", "Temperature_C", "pH", "EC_mS/cm"]


def _generate_csv_row(timestamp: str, temperature: float, ph: float, ec: float) -> list:
    """Return a single CSV row."""
    return [timestamp, f"{temperature:.2f}", f"{ph:.2f}", f"{ec:.2f}"]


def _generate_csv_data(csv_file: str, header: list) -> list:
    """Append multiple CSV rows to the file."""
    if not os.path.isfile(csv_file):
        return []
    try:
        with open(csv_file, "a", newline="") as f:
            writer = csv.writer(f)
            writer.writerows(header + [
                _generate_csv_row(datetime.datetime.now().isoformat(),
                                  _read_temperature(0.0, 1.0),
                                  _read_ph(0.0, 1.0),
                                  _read_ec(0.0, 1.0))
            ]
    except (OSError, csv.Error) as exc:
        logging.error("Error writing to CSV file: %s", exc)
        return []
    return []


def _create_log_handler(log_level: str) -> logging.Handler:
    """Create a rotating-file handler for the log."""
    handler = logging.handlers.TimedRotatingFileHandler(
        LOG_FILE, when="midnight", interval=1, backupCount=LOG_FILE_BACKUP_COUNT
    )
    handler.setFormatter(logging.Formatter(
        "%(asctime)s - %(levelname)s - %(message)s",
        datefmt="%Y-%m-%d %H:%M:%S"
    ))
    return handler


def _create_csv_handler(csv_file: str) -> logging.Handler:
    """Create a CSV handler for the log."""
    handler = logging.handlers.CSVHandler(
        filename=csv_file,
        fieldname=None,
        datefmt="%Y-%m-%d %H:%M:%S",
        log_attr=True
    )
    handler.setFormatter(logging.Formatter(
        "%(Timestamp)s - %(LevelName)s - %(Message)s",
        datefmt="%Y-%m-%d %H:%M:%S"
    ))
    return handler


def _create_alert_handler(log_level: str) -> logging.Handler:
    """Create an alert handler that blinks the LED on threshold violations."""
    handler = logging.handlers.TimedRotatingFileHandler(
        LOG_FILE, when="midnight", interval=1, backupCount=LOG_FILE_BACKUP_COUNT
    )
    handler.setFormatter(logging.Formatter(
        "%(asctime)s - %(levelname)s - %(message)s",
        datefmt="%Y-%m-%d %H:%M:%S"
    ))
    handler.setLevel(logging.WARNING)
    handler.addHandler(_create_log_handler(log_level))
    handler.addHandler(_create_csv_handler(CSV_FILE))
    handler.addHandler(_create_alert_handler(log_level))
    return handler


def _setup_logging(log_level: str) -> None:
    """Configure logging with the given level and handlers."""
    logger = logging.getLogger()
    logger.setLevel(log_level)

    # Remove any existing handlers so we can add our custom ones.
    for h in list(logger.handlers):
        logger.removeHandler(h)

    ch = _create_alert_handler(log_level)
    ch.addHandler(_create_log_handler(log_level))
    ch.addHandler(_create_csv_handler(CSV_FILE))
    ch.addHandler(_create_alert_handler(log_level))

    # Also log to CSV so the log file contains the full trace.
    ch2 = _create_csv_handler(CSV_FILE)
    ch2.addHandler(ch)
    ch2.setLevel(logging.INFO)
    logger.addHandler(ch2)


def _blink_led(led: LED, cycles: int = 3, on_time: float = 0.5, off_time: float = 0.5) -> None:
    """Blink the alert LED for the given number of cycles."""
    if led is None:
        return
    for _ in range(cycles):
        if not _running:
            break
        led.on()
        time.sleep(on_time)
        led.off()
        time.sleep(off_time)


def _cleanup(led: LED) -> None:
    """Release GPIO resources and turn off the LED."""
    global _alert_led
    if led is not None:
        try:
            led.off()
            led.close()
        except Exception:
            pass
        _alert_led = None
    if _alert_led is not None:
        try:
            _alert_led.off()
            _alert_led.close()
        except Exception:
            pass
        _alert_led = None


def main() -> None:
    """Main entry point: read config, initialise hardware, and run the loop."""
    global _alert_led

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    config = _read_config(CONFIG_FILE)
    thresholds = _read_thresholds(CONFIG_FILE)
    calibration = _read_calibration(CONFIG_FILE)
    log_level = _read_log_level(CONFIG_FILE)

    # --- Initialise alert LED -------------------------------------------------
    _alert_led = _read_alert_led_pin(17)

    # --- Validate configuration ----------------------------------------------
    if not _validate_reading(0.0, thresholds["temperature_threshold_low"], "low",
                            calibration["temperature_offset"], calibration["temperature_gain"]):
        logging.error("Invalid temperature offset or gain; using defaults.")
    if not _validate_reading(0.0, thresholds["ph_threshold_low"], "low",
                            calibration["ph_offset"], calibration["ph_gain"]):
        logging.error("Invalid ph offset or gain; using defaults.")
    if not _validate_reading(0.0, thresholds["ec_threshold_low"], "low",
                            calibration["ec_offset"], calibration["ec_gain"]):
        logging.error("Invalid ec offset or gain; using defaults.")

    # --- Setup logging ---------------------------------------------------------
    _setup_logging(log_level)

    # --- Read existing CSV data ----------------------------------------------
    existing = _read_csv_file(CSV_FILE)
    if existing:
        logging.info("Loaded %d existing data rows from %s", len(existing), CSV_FILE)
    else:
        logging.info("No existing data; starting fresh.")

    # --- Main loop -------------------------------------------------------------
    while _running:
        timestamp = datetime.datetime.now().isoformat()

        # --- Temperature ----------------------------------------------------
        temperature = _read_temperature(calibration["temperature_offset"],
                                         calibration["temperature_gain"])
        ph = _read_ph(calibration["ph_offset"], calibration["ph_gain"])
        ec = _read_ec(calibration["ec_offset"], calibration["ec_gain"])

        # --- Validate and log -------------------------------------------------
        if _validate_reading(temperature, thresholds["temperature_threshold_high"], "high",
                             calibration["temperature_offset"], calibration["temperature_gain"]):
            logging.info("Temperature: %.2f C", temperature)
        else:
            logging.warning("Temperature: %.2f C (threshold exceeded)", temperature)

        if _validate_reading(ph, thresholds["ph_threshold_high"], "high",
                             calibration["ph_offset"], calibration["ph_gain"]):
            logging.info("pH: %.2f", ph)
        else:
            logging.warning("pH: %.2f (threshold exceeded)", ph)

        if _validate_reading(ec, thresholds["ec_threshold_high"], "high",
                             calibration["ec_offset"], calibration["ec_gain"]):
            logging.info("EC: %.2f mS/cm", ec)
        else:
            logging.warning("EC: %.2f mS/cm (threshold exceeded)", ec)

        # --- Append to CSV ----------------------------------------------------
        _generate_csv_data(CSV_FILE, _generate_csv_header())

        # --- Blink LED on threshold violation ---------------------------------
        if any(
            _validate_reading(temp, high, "high", offset, gain)
            for temp, high, offset, gain in
                zip(
                    [temperature],
                    [thresholds["temperature_threshold_high"]],
                    [calibration["temperature_offset"]],
                    [calibration["temperature_gain"]]
                )
        ):
            _blink_led(_alert_led, cycles=3, on_time=0.5, off_time=0.5)

        # --- Sleep for the interval (check _running every second) --------------
        for _ in range(60):
            if not _running:
                break
            time.sleep(1)

    # --- Cleanup --------------------------------------------------------------
    _cleanup(_alert_led)
    logging.info("Program terminated.")


if __name__ == "__main__":
