import json
import logging
import signal
import sys
import time
from collections import deque
from statistics import median

try:
    import RPi.GPIO as GPIO
except RuntimeError:
    GPIO = None

# Constants
CONFIG_FILE = "config.json"
LOG_FILE = "water_level.log"
POLL_INTERVAL = 5  # seconds
SENSOR_TIMEOUT = 0.05  # 50 ms
MAX_SENSOR_ERRORS = 5

# Default configuration
DEFAULT_CONFIG = {
    "sensor_offsets": [0.0, 0.0, 0.0],
    "max_distances": [200.0, 200.0, 200.0],
    "low_threshold": 10.0,
    "high_threshold": 180.0,
    "alert_repeat_delay": 60,
    "log_file": LOG_FILE,
}

# Global state
running = True
sensor_readings = deque(maxlen=3)
sensor_error_counts = {1: 0, 2: 0, 3: 0}

# Logging setup
logging.basicConfig(
    filename=LOG_FILE,
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)
logger = logging.getLogger(__name__)


def load_config():
    """Load configuration from JSON file, falling back to defaults."""
    try:
        with open(CONFIG_FILE, "r") as f:
            config = json.load(f)
        merged = DEFAULT_CONFIG.copy()
        merged.update(config)
        logger.info("Configuration loaded from %s", CONFIG_FILE)
        return merged
    except FileNotFoundError:
        logger.warning("Configuration file not found. Using default configuration.")
        return DEFAULT_CONFIG.copy()
    except json.JSONDecodeError as e:
        logger.error("Error decoding JSON from %s: %s. Using default configuration.", CONFIG_FILE, e)
        return DEFAULT_CONFIG.copy()


def setup_gpio():
    """Initialize GPIO pins for HC-SR04 ultrasonic sensors."""
    if GPIO is None:
        logger.error("RPi.GPIO not available. Cannot initialize GPIO.")
        return False
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(17, GPIO.OUT)
        GPIO.setup(22, GPIO.OUT)
        GPIO.setup(24, GPIO.OUT)
        GPIO.setup(18, GPIO.IN)
        GPIO.setup(23, GPIO.IN)
        GPIO.setup(25, GPIO.IN)
        logger.info("GPIO pins configured for HC-SR04 sensors.")
        return True
    except Exception as e:
        logger.error("GPIO setup failed: %s", e)
        return False


def cleanup_gpio():
    """Release GPIO resources."""
    if GPIO is not None:
        try:
            GPIO.cleanup()
            logger.info("GPIO resources released.")
        except Exception as e:
            logger.error("GPIO cleanup failed: %s", e)


def signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for graceful shutdown."""
    global running
    logger.info("Received signal %d, shutting down...", signum)
    running = False


def read_distance(trigger_pin, echo_pin):
    """Read distance from an HC-SR04 sensor. Returns None on timeout or error."""
    try:
        GPIO.output(trigger_pin, GPIO.LOW)
        time.sleep(0.000002)  # 2 µs settle
        GPIO.output(trigger_pin, GPIO.HIGH)
        time.sleep(0.00001)   # 10 µs pulse
        GPIO.output(trigger_pin, GPIO.LOW)

        pulse_start = time.time()
        timeout = time.time() + SENSOR_TIMEOUT
        while GPIO.input(echo_pin) == 0:
            if time.time() > timeout:
                logger.warning("Echo pin 0 stuck low on trigger pin %d", trigger_pin)
                return None
        pulse_start = time.time()

        timeout = time.time() + SENSOR_TIMEOUT
        while GPIO.input(echo_pin) == 1:
            if time.time() > timeout:
                logger.warning("Echo pin 0 stuck high on trigger pin %d", trigger_pin)
                return None
        pulse_end = time.time()

        pulse_duration = pulse_end - pulse_start
        distance = pulse_duration * 17150.0
        return distance
    except Exception as e:
        logger.error("Error reading sensor on trigger pin %d: %s", trigger_pin, e)
        return None


def calculate_water_level(distance_readings):
    """Calculate water level from median distance."""
    if not distance_readings:
        logger.warning("No valid distance readings available.")
        return None
    try:
        return median(distance_readings)
    except Exception as e:
        logger.error("Error calculating water level: %s", e)
        return None


def check_thresholds(water_level, low_threshold, high_threshold):
    """Check water level against thresholds, suppressing repeated alerts."""
    if water_level is None:
        return
    if water_level < low_threshold:
        logger.warning("Water level is low! Level: %.2f", water_level)
        if water_level < low_threshold - 10:
            logger.warning("Water level is critically low! Level: %.2f", water_level)
    elif water_level > high_threshold:
        logger.warning("Water level is high! Level: %.2f", water_level)
        if water_level > high_threshold - 10:
            logger.warning("Water level is critically high! Level: %.2f", water_level)


def main():
    """Main function to read sensor data and check thresholds."""
    global running

    config = load_config()
    sensor_offsets = config["sensor_offsets"]
    max_distances = config["max_distances"]
    low_threshold = config["low_threshold"]
    high_threshold = config["high_threshold"]
    alert_repeat_delay = config["alert_repeat_delay"]
