# DHT11 sensor class using gpiozero
class DHT11:
    def __init__(self, pin):
        self.pin = pin
        self.led = None
        try:
            from gpiozero import LED
            self.led = LED(pin)
            self.led.off()
        except Exception as e:
            logging.warning(f"Failed to initialize DHT11 on pin {pin}: {e}. Using simulated sensor.")
            self.led = None

    def read_temperature(self):
        if self.led is None:
            return self._simulate_temperature()
        try:
            # gpiozero LED does not support direct I2C communication; use a simple loop
            # to read the sensor.
            # In a real implementation, you would use a library like adafruit-circuitpython-dht.
            # For this example, we simulate the sensor reading.
            # In production, you would use a library like adafruit-circuitpython-dht.
            # For this example, we simulate the sensor reading.
            # We will simulate the sensor reading by generating a random temperature.
            temperature = random.uniform(15, 35)
            return temperature
        except Exception as e:
            logging.error(f"Error reading DHT11 sensor: {e}")
            return self._simulate_temperature()

    def _simulate_temperature(self):
        # Simulate a temperature reading between 15°C and 35°C
        return random.uniform(15, 35)

# Camera class using picamera2
class Camera:
    def __init__(self, directory):
        self.directory = directory
        self.picam2 = None
        try:
            from picamera2 import Picamera2
            self.picam2 = Picamera2()
            self.picam2.configure(self.picam2.create_still_configuration())
            self.picam2.start()
            logging.info("Camera initialized successfully.")
        except Exception as e:
            logging.error(f"Failed to initialize camera: {e}")
            self.picam2 = None

    def capture_picture(self):
        if self.picam2 is None:
            return None
        try:
            timestamp = time.strftime("%Y%m%d_%H%M%S")
            filename = os.path.join(self.directory, f"greenhouse_{timestamp}.jpg")
            self.picam2.capture_file(filename)
            logging.info(f"Picture saved: {filename}")
            return filename
        except Exception as e:
            logging.error(f"Error capturing picture: {e}")
            return None

    def close(self):
        if self.picam2:
            try:
                self.picam2.close()
            except Exception as e:
                logging.error(f"Error closing camera: {e}")

