    cam = Picamera2()
    cam.configure(cam.create_preview_configuration(main={"format": "RGB888", "size": (640, 480)}))
    cam.start()
    time.sleep(2)
    baseline = None
    while running:
        try:
            frame = cam.capture_array()
        except Exception as e:
            print(f"Error capturing frame: {e}", file=sys.stderr)
            break
        if frame is None:
            print("Warning: captured frame is None", file=sys.stderr)
