import signal
import sys
import time

try:
    import RPi.GPIO as GPIO
except RuntimeError:
    print("Error: RPi.GPIO requires root privileges. Run with sudo or set up a proper environment.", file=sys.stderr)
    sys.exit(1)

# BCM pin numbers
INPUT_PINS = [4, 5, 6]
OUTPUT_PINS = [23, 24]
POLL_INTERVAL = 0.05

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def setup_gpio():
    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)
    for pin in INPUT_PINS + OUTPUT_PINS:
        GPIO.setup(pin, GPIO.IN, pull_up_down=GPIO.PUD_UP)
    for pin in OUTPUT_PINS:
        GPIO.setup(pin, GPIO.OUT, initial=GPIO.LOW)

def cleanup_gpio():
    GPIO.cleanup()

def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        setup_gpio()
    except Exception as e:
        print(f"GPIO initialization failed: {e}", file=sys.stderr)
        cleanup_gpio()
        sys.exit(1)

    state = {pin: GPIO.LOW for pin in OUTPUT_PINS}
    last_state = {pin: GPIO.LOW for pin in OUTPUT_PINS}

    try:
        while _running:
            for pin in INPUT_PINS:
                try:
                    val = GPIO.input(pin)
                except Exception as e:
                    print(f"Error reading GPIO{pin}: {e}", file=sys.stderr)
                    continue
                if val == GPIO.LOW:
                    if pin == 4:
                        state[OUTPUT_PINS[0]] = GPIO.HIGH
                    elif pin == 5:
                        state[OUTPUT_PINS[0]] = GPIO.LOW
                    elif pin == 6:
                        state[OUTPUT_PINS[0]] = not state[OUTPUT_PINS[0]]
                else:
                    state[OUTPUT_PINS[0]] = GPIO.LOW

            for pin in OUTPUT_PINS:
                try:
                    GPIO.output(pin, state[pin])
                except Exception as e:
                    print(f"Error writing GPIO{pin}: {e}", file=sys.stderr)

            time.sleep(POLL_INTERVAL)
    finally:
        cleanup_gpio()

if __name__ == "__main__":
    main()

