# Logging setup
def setup_logging(log_level: str, log_file: str, backup_log_file: str) -> None:
    numeric_level = getattr(logging, log_level.upper(), None)
    if not isinstance(numeric_level, int):
        raise ValueError(f'Invalid log level: {log_level}')
    logging.basicConfig(
        level=numeric_level,
        format='%(asctime)s - %(levelname)s - %(message)s',
        handlers=[
            logging.FileHandler(log_file),
            logging.handlers.TimedRotatingFileHandler(
                backup_log_file, when="D", interval=1, backupCount=3
            )
        ]
    )

# Configuration loading
def load_configuration(config_file: str) -> configparser.ConfigParser:
    config = configparser.ConfigParser()
    if not config.read(config_file):
        raise FileNotFoundError(f"Configuration file not found: {config_file}")
    return config

# Camera initialization
def initialize_camera(device_id: str) -> cv2.VideoCapture:
    try:
        cap = cv2.VideoCapture(device_id)
        if not cap.isOpened():
            raise IOError(f"Could not open camera at {device_id}")
        return cap
    except Exception as e:
        logging.error(f"Error initializing camera {device_id}: {e}")
        return None

