import io
import os
import time
import signal
import sys
import configparser
from datetime import datetime

import numpy as np
from PIL import Image

try:
    from picamera2 import Picamera2
except ImportError:
    print("picamera2 is not installed. Install with: pip install picamera2")
    sys.exit(1)

CONFIG_FILE = "config.txt"

running = True

def signal_handler(sig, frame):
    global running
    running = False

def load_config(config_file):
    config = configparser.ConfigParser()
    if not config.read(config_file):
        print(f"Error: Config file '{config_file}' not found or empty.")
        return None
    try:
        roi_x1 = int(config['roi']['x1'])
        roi_y1 = int(config['roi']['y1'])
        roi_x2 = int(config['roi']['x2'])
        roi_y2 = int(config['roi']['y2'])
        motion_threshold = float(config['motion_threshold']['threshold'])
        confirmation_delay = int(config['alert_delay']['delay'])
        temperature_threshold = float(config['temperature_threshold']['threshold'])
        simulated_temperature = config.getboolean('temperature_threshold', 'simulated')
        snapshot_dir = config['snapshot_dir']['directory']
        return {
            'roi_x1': roi_x1, 'roi_y1': roi_y1, 'roi_x2': roi_x2, 'roi_y2': roi_y2,
            'motion_threshold': motion_threshold,
            'confirmation_delay': confirmation_delay,
            'temperature_threshold': temperature_threshold,
            'simulated_temperature': simulated_temperature,
            'snapshot_dir': snapshot_dir
        }
    except (ValueError, KeyError) as e:
        print(f"Error parsing config file: {e}")
        return None

def init_camera(config):
    try:
        picam2 = Picamera2()
        config_cam = picam2.create_preview_configuration(
            main={"size": (640, 480), "format": "RGB888"}
        )
        picam2.configure(config_cam)
        picam2.start()
        time.sleep(2)
        return picam2
    except Exception as e:
        print(f"Error initializing camera: {e}")
        return None

def capture_frame(picam2):
    try:
        return picam2.capture_array()
    except Exception as e:
        print(f"Error capturing frame: {e}")
        return None

def detect_motion(frame1, frame2, roi, motion_threshold):
    try:
        roi1 = frame1[roi[0]:roi[0] + roi[2], roi[1]:roi[1] + roi[3], :]
        roi2 = frame2[roi[0]:roi[0] + roi[2], roi[1]:roi[1] + roi[3], :]
        diff = np.abs(roi1.astype(np.int16) - roi2.astype(np.int16))
        motion_percentage = np.sum(diff > 255) / float(diff.size)
        return motion_percentage > motion_threshold
    except Exception as e:
        print(f"Error detecting motion: {e}")
        return False

def generate_alert(message, temperature_threshold, simulated_temperature):
    timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    filename = os.path.join(
        config['snapshot_dir']['directory'],
        f"ALERT_{timestamp}_{int(time.time())}.txt"
    )
    try:
        with open(filename, "w") as f:
            f.write(message)
        if simulated_temperature:
            cpu_temp = 40.0
        else:
            try:
                with open("/proc/cpuinfo", "r") as f:
                    for line in f:
                        if line.startswith("Processor"):
                            cpu_temp_str = line.split(":")[1].strip()
                            cpu_temp = float(cpu_temp_str)
                            break
            except Exception:
                cpu_temp = 40.0
        if cpu_temp > temperature_threshold:
            print(f"ALERT: {message}")
    except Exception as e:
        print(f"Error generating alert: {e}")

def save_snapshot(frame, snapshot_dir):
    try:
        image = Image.fromarray(frame)
        image.save(os.path.join(snapshot_dir, f"snapshot_{datetime.now().strftime('%Y%m%d_%H%M%S')}.jpg"))
    except Exception as e:
        print(f"Error saving snapshot: {e}")

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    config = load_config(CONFIG_FILE)
    if config is None:
        return
    picam2 = init_camera(config)
    if picam2 is None:
        return
    try:
        while running:
            frame1 = capture_frame(picam2)
            if frame1 is None:
                time.sleep(1)
                continue
            time.sleep(0.1)
            frame2 = capture_frame(picam2)
            if frame2 is None:
                time.sleep(1)
                continue
            if detect_motion(frame1, frame2, config['roi'], config['motion_threshold']):
                print("Motion detected!")
                time.sleep(config['confirmation_delay'])
                generate_alert("Motion detected!", config['temperature_threshold'], config['simulated_temperature'])
                save_snapshot(frame1, config['snapshot_dir']['directory'])
            else:
                print("No motion detected.")
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        try:
            picam2.stop()
        except Exception:
            pass

if __name__ == "__main__":
    main()

