import cv2
import numpy as np
import time
import signal
import sys

# Global flag for graceful shutdown
_running = True


def _signal_handler(signum, frame):
    """Handle SIGINT / SIGTERM for clean shutdown."""
    global _running
    _running = False


class BackgroundSubtractor:
    """Running-average background subtractor for part counting on a Raspberry Pi."""

    def __init__(self, learning_rate=0.05):
        self.learning_rate = learning_rate
        self.background_model = None

    def update(self, frame_image):
        """Fit the background model to the given frame and return the mean intensity."""
        if self.background_model is None:
            self.background_model = frame_image.astype("float32")
            return float(np.mean(frame_image))
        self.background_model = cv2.accumulateWeighted(
            frame_image, self.background_model, self.learning_rate
        )
        return float(np.mean(self.background_model))


class PartCounter:
    """Conveyor-belt part counter using background subtraction on Raspberry Pi."""

    def __init__(self, roi_height_fraction=1.0 / 3.0, part_threshold=8.0):
        self.roi_height_fraction = roi_height_fraction
        self.part_threshold = part_threshold
        self.background_subtractor = BackgroundSubtractor()
        self.part_count = 0

    def count_parts(self, capture_frames):
        """Count parts by comparing mean ROI intensity to the threshold."""
        for frame_index, frame_image in enumerate(capture_frames):
            if not _running:
                break

            mean_intensity = self.background_subtractor.update(frame_image)
            if mean_intensity > self.part_threshold:
                self.part_count += 1

            print(f"Frame {frame_index}: mean intensity = {mean_intensity:.2f}", end="  ")
            time.sleep(0.1)

        return self.part_count


def run_conveyor_counter(frame_total=30, frame_interval=0.1, roi_height_fraction=1.0 / 3.0):
    """Run the part-counting loop and return the total count."""
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    counter = PartCounter(roi_height_fraction=roi_height_fraction)
    capture_frames = []

    try:
        # Initialize the camera
        capture_device = cv2.VideoCapture(0)
        if not capture_device.isOpened():
            raise RuntimeError("Failed to open camera (CSI bus) on index 0")

        # Warm up the camera and let the auto-exposure settle
        time.sleep(2.0)

        # Capture frames for counting
        for frame_index in range(frame_total):
            if not _running:
                break

            ret, frame_image = capture_device.read()
            if not ret or frame_image is None:
                print(f"Frame {frame_index}: capture failed, continuing...")
                time.sleep(frame_interval)
                continue

            capture_frames.append(frame_image)

        if not capture_frames:
            raise RuntimeError("No frames captured after warm-up")

        part_total = counter.count_parts(capture_frames)
        print(f"Total parts detected: {part_total}")
        return part_total

    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)
        return None
    finally:
        # Release the camera resource
        if capture_device is not None:
            capture_device.release()


if __name__ == "__main__":
    run_conveyor_counter()

