import cv2
import numpy as np
import serial
import serial.tools.list_ports
import time
import signal
import sys

# Constants for object detection
COLOR_RANGES = [
    ((100, 100, 100), (200, 200, 200)),
    ((100, 100, 100), (200, 200, 200)),
    ((100, 100, 100), (200, 200, 200)),
    ((100, 100, 100), (200, 200, 200)),
    ((100, 100, 100), (200, 200, 200)),
]
MIN_OBJECT_AREA = 500

# UART configuration
UART_PORT = '/dev/ttyACM0'
UART_BAUDRATE = 9600
UART_TIMEOUT = 1

# Global flag for graceful shutdown
running = True

def signal_handler(sig, frame):
    global running
    running = False

def initialize_camera():
    """Initializes the Raspberry Pi camera."""
    try:
        camera = cv2.VideoCapture(0)
        if not camera.isOpened():
            raise IOError("Cannot open camera")
        return camera
    except Exception as e:
        print(f"Error initializing camera: {e}")
        return None

def initialize_uart():
    """Initializes the UART communication."""
    try:
        ser = serial.Serial(
            port=UART_PORT,
            baudrate=UART_BAUDRATE,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=UART_TIMEOUT
        )
        return ser
    except serial.SerialException as e:
        print(f"Error initializing UART: {e}")
        return None

def send_digit(ser, digit):
    """Sends a digit to the UART."""
    try:
        ser.write(str(digit).encode('utf-8'))
        ser.flush()
    except serial.SerialException as e:
        print(f"Error sending digit: {e}")

def process_frame(frame, color_range):
    """Processes a single frame to detect objects and classify their position."""
    hsv_frame = cv2.cvtColor(frame, cv2.COLOR_BGR2HSV)
    mask = cv2.inRange(hsv_frame, color_range[0], color_range[1])
    contours, _ = cv2.findContours(mask, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)

    for contour in contours:
        area = cv2.contourArea(contour)
        if area > MIN_OBJECT_AREA:
            x, y, w, h = cv2.boundingRect(contour)
            cv2.rectangle(frame, (x, y), (x + w, y + h), (255, 0, 0), 2)

            # Calculate object position relative to frame center
            object_x = x + w // 2
            object_y = y + h // 2

            # Classify position relative to center with 50-pixel deadzone
            if object_x > (w // 2 + 50) and object_y > (h // 2 + 50):
                digit = 1
            elif object_x > (w // 2 + 50) and object_y < (h // 2 - 50):
                digit = 2
            elif object_x < (w // 2 - 50) and object_y > (h // 2 + 50):
                digit = 3
            elif object_x < (w // 2 - 50) and object_y < (h // 2 - 50):
                digit = 4
            else:
                digit = 5

            send_digit(ser, digit)

def main():
    """Main function to run the object detection and UART communication."""
    global running

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    camera = initialize_camera()
    if camera is None:
        return

    ser = initialize_uart()
    if ser is None:
        camera.release()
        return

    try:
        while running:
            ret, frame = camera.read()
            if not ret:
                print("Failed to grab frame")
                break

            h, w = frame.shape[:2]
            cx, cy = w // 2, h // 2

            # Allow camera to warm up
            time.sleep(0.1)

            # Get color range input
            if ord('s') in (ord(c) for c in input().encode('utf-8')):
                while running:
                    x1, y1, x2, y2 = map(int, input("Enter top-left and bottom-right x,y (or 'q' to quit): ").split())
                    if (x1, y1, x2, y2) == (cx, cy, cx, cy):
                        break
                    x1, y1, x2, y2 = min(cx, max(x1, x2)), min(cy, max(y1, y2)), max(cx, min(x2, x1)), max(cy, min(y2, y))
