# Global shutdown flag
_shutdown_event = threading.Event()


def _signal_handler(signum, frame):
    logger.info('Signal %s received, shutting down...', signum)
    _shutdown_event.set()


def _validate_frame(frame):
    if frame is None:
        raise ValueError('Frame is None')
    if not isinstance(frame, (bytes, bytearray)):
        raise ValueError('Frame must be bytes or bytearray')


def _validate_frame_list(frames):
    if frames is None:
        raise ValueError('Frame list is None')
    if not isinstance(frames, (list, tuple)):
        raise ValueError('Frame list must be a list or tuple')
    for f in frames:
        _validate_frame(f)


def _validate_frame_array(frame_array):
    if frame_array is None:
        raise ValueError('Frame array is None')
    if not isinstance(frame_array, np.ndarray):
        raise ValueError('Frame array must be a numpy.ndarray')
    if frame_array.size == 0:
        raise ValueError('Frame array cannot be empty')
    if frame_array.dtype != np.uint8:
        raise ValueError('Frame array must be uint8')


def _validate_frame_rgb888(frame):
    _validate_frame_array(frame)
    if frame.ndim != 3 or frame.shape[2] != 3:
        raise ValueError('RGB888 frame must be 3-channel')


