import io
import logging
import signal
import threading
import time
from typing import Callable, Optional

import numpy as np
from picamera2 import Picamera2
from picamera2.encoders import MJPEGEncoder
from picamera2.outputs import Output

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)
logger = logging.getLogger(__name__)


class CameraStreamBuffer:
    """
    Thread-safe buffer for capturing and streaming JPEG frames from a
    Raspberry Pi camera.  Uses a lock to protect shared state and a
    condition to signal downstream consumers when new frames are available.
    """

    def __init__(self, handler: "WebSocketHandler"):
        if handler is None:
            raise ValueError("handler cannot be None")
        self.handler = handler
        self.frame: Optional[bytes] = None
        self.lock = threading.Lock()
        self.condition = threading.Condition(self.lock)
        self.buffer: Optional[Output] = None

    def write(self, data: bytes) -> None:
        """
        Called by the encoder with raw JPEG bytes.  Accumulates data until
        a complete JPEG frame is detected by the 0xFF 0xD8 marker.
        """
        if data is None or len(data) == 0:
            return

        with self.lock:
            if self.buffer is None:
                self.buffer = Output()
            try:
                self.buffer.write(data)
            except Exception as exc:
                logger.error("Error writing to output buffer: %s", exc)
                self.buffer = None

        # Detect JPEG start marker
        if b"\xff\xd8" in data:
            with self.lock:
                self.frame = data
                self.condition.notify_all()

    def flush(self) -> None:
        """Emit any buffered frame to the downstream handler."""
        with self.lock:
            frame = self.frame
            self.frame = None
        if frame is not None:
            try:
                self.handler.on_frame(frame)
            except Exception as exc:
                logger.error("Error sending frame to handler: %s", exc)


class MotionDetectionBuffer:
    """
    Thread-safe buffer for detecting motion between consecutive frames.
    Stores the previous and current frames, and invokes a motion-detection
    function when both are valid.
    """

    def __init__(self, handler: "WebSocketHandler", detect_motion: Callable[[bytes, bytes], None]):
        if handler is None:
            raise ValueError("handler cannot be None")
        if not callable(detect_motion):
            raise TypeError("detect_motion must be callable")
        self.handler = handler
        self.detect_motion = detect_motion
        self.prev_frame: Optional[bytes] = None
        self.curr_frame: Optional[bytes] = None
        self.lock = threading.Lock()
        self.condition = threading.Condition(self.lock)

    def write(self, data: bytes) -> None:
        """
        Called by the encoder with raw JPEG bytes.  Accumulates data until
        a complete JPEG frame is detected by the 0xFF 0xd8 marker.
        """
        if data is None or len(data) == 0:
            return

        with self.lock:
            if self.prev_frame is None or self.curr_frame is None:
                self.prev_frame = self.curr_frame
                self.curr_frame = data
                self.condition.notify_all()
            elif self.prev_frame != data:
                self.prev_frame = self.curr_frame
                self.curr_frame = data
                self.condition.notify_all()

        # Detect JPEG start marker
        if b"\xff\xd8" in data:
            with self.lock:
                self.prev_frame = self.curr_frame
                self.curr_frame = data
                self.condition.notify_all()

    def flush(self) -> None:
        """Emit any buffered frame to the downstream handler for motion
        detection."""
        with self.lock:
            frame = self.curr_frame
            self.prev_frame = None
            self.curr_frame = None
        if frame is not None:
            try:
                self.handler.on_frame(frame)
                if self.detect_motion(self.prev_frame, self.curr_frame):
                    logger.info("Motion detected!")
            except Exception as exc:
                logger.error("Error sending frame to handler for motion detection: %s", exc)


class WebSocketHandler:
    """WebSocket handler that broadcasts frames to connected clients."""

    def __init__(self, host: str, port: int, handler: "WebSocketHandler"):
        if not isinstance(host, str) or not host:
            raise ValueError("host must be a non-empty string")
        if not isinstance(port, int) or not (1 <= port <= 65535):
            raise ValueError("port must be an integer in [1, 65535]")
        if handler is None:
            raise ValueError("handler cannot be None")
        self.host = host
        self.port = port
        self.handler = handler
        self.clients: list[object] = []
        self._running = False

    def connect(self, host: str, port: int) -> None:
        """Register a new WebSocket connection."""
        if not isinstance(host, str) or not host:
            raise ValueError("host must be a non-empty string")
        if not isinstance(port, int) or not (1 <= port <= 65535):
            raise ValueError("port must be an integer in [1, 65535]")
        self.clients.append(self)
        logger.info("WebSocket connection established from %s:%d", host, port)

    def disconnect(self, index: int) -> None:
        """Remove a client by index."""
        if 0 <= index < len(self.clients):
            self.clients.pop(index)
            logger.info("WebSocket connection %d disconnected", index)
        else:
            logger.warning("Invalid client index %d", index)

    def on_frame(self, frame: bytes) -> None:
        """Broadcast a frame to all connected clients."""
        if not isinstance(frame, bytes):
            raise TypeError("frame must be bytes")
        if self._running:
            for client in self.clients:
                try:
                    client.send(frame)
                except Exception as exc:
                    logger.error("Error sending frame to client: %s", exc)
        else:
            logger.warning("WebSocket handler not running; frame not broadcast.")

    def start(self) -> None:
        """Start the WebSocket server loop."""
        if self._running:
            return
        self._running = True
        logger.info("WebSocket server started on %s:%d", self.host, self.port)
        try:
            self.server = signal.signal(signal.SIGINT, self._signal_handler)
            self.server = signal.signal(signal.SIGTERM, self._signal_handler)
            self.server.serve_forever()
        except Exception as exc:
            logger.error("WebSocket server error: %s", exc)
        finally:
            self.stop()

    def _signal_handler(self, signum, frame):
        logger.info("Received signal %d; shutting down.", signum)
        self.stop()

    def stop(self) -> None:
        """Stop the WebSocket server and release resources."""
        self._running = False
        for client in self.clients:
            try:
                client.close()
            except Exception as exc:
                logger.error("Error closing WebSocket client: %s", exc)
        self.clients.clear()
        if self.server is not None:
            try:
                self.server.shutdown()
            except Exception as exc:
                logger.error("Error shutting down WebSocket server: %s", exc)


def _validate_picam2(config: dict) -> Picamera2:
    """Validate and initialize the Picamera2 instance."""
    if not isinstance(config, dict):
        raise TypeError("config must be a dict")
    if "size" not in config or "format" not in config:
        raise ValueError("config must contain 'size' and 'format' keys")
    if not isinstance(config["size"], tuple) or len(config["size"]) != 2:
        raise ValueError("'size' must be a 2-tuple")
    if not isinstance(config["format"], str):
        raise ValueError("'format' must be a string")
    try:
        picam2 = Picamera2()
        config_dict = picam2.create_video_configuration(
            main={"size": config["size"], "format": config["format"]}
        )
        picam2.configure(config_dict)
        picam2.start()
        logger.info("Picamera2 initialized and started.")
        return picam2
    except Exception as exc:
        logger.error("Failed to initialize Picamera2: %s", exc)
        raise


def main() -> None:
    """Main entry point: initialize hardware, start WebSocket server,
    capture JPEG frames, and detect motion."""
    # --- WebSocket handler setup ---
    try:
        handler = WebSocketHandler(host="0.0.0.0", port=8765, handler=None)
        handler.connect("0.0.0.0", 8765)
        handler.start()
    except Exception as exc:
        logger.error("WebSocket initialization failed: %s", exc)
        return

    # --- Camera initialization ---
    try:
        picam2 = _validate_picam2({"size": (640, 480), "format": "RGB888"})
    except Exception as exc:
        logger.error("Camera initialization failed: %s", exc)
        handler.stop()
        return

    # --- Motion detection function ---
    def detect_motion(prev: Optional[bytes], curr: Optional[bytes]) -> bool:
        """Simple JPEG-based motion detection.  Returns True if both frames
        are valid JPEGs and the bytes differ."""
        if prev is None or curr is None:
            return False
        if b"\xff\xd8" not in curr:
            return False
        if b"\xff\xd9" not in curr:
            return False
        return bytes(prev) != bytes(curr)

    # --- Capture loop ---
    try:
        encoder = MJPEGEncoder()
        output = CameraStreamBuffer(handler)
        motion_buffer = MotionDetectionBuffer(handler, detect_motion)

        picam2.start_recording(encoder, output)
        logger.info("Camera recording started.")

        while True:
            time.sleep(0.1)

            # Check if any client is connected
            if handler.clients:
                # Emit any buffered frame to clients
                output.flush()

            # Check for new JPEG frames
            if output.frame is not None:
                output.flush()

            # Check for motion
            if motion_buffer.frame is not None:
                motion_buffer.flush()

            # Check if the encoder has more frames to process
            if picam2.has_new_frame():
                try:
                    frame = picam2.capture_array()
                    if frame is not None:
                        # Convert RGB888 to JPEG bytes
                        from PIL import Image
                        img = Image.fromarray(frame)
                        bytes_io = io.BytesIO()
                        img.save(bytes_io, format="JPEG")
                        frame = bytes_io.getvalue()
                        output.write(frame)
                except Exception as exc:
                    logger.error("Error capturing or encoding frame: %s", exc)

    except KeyboardInterrupt:
        logger.info("Keyboard interrupt received; shutting down.")
    except Exception as exc:
        logger.error("Unexpected error in capture loop: %s", exc)
    finally:
        logger.info("Cleaning up resources...")
        try:
            picam2.stop_recording()
        except Exception as exc:
            logger.error("Error stopping recording: %s", exc)
        try:
            picam2.close()
        except Exception as exc:
            logger.error("Error closing camera: %s", exc)
        handler.stop()
        logger.info("Shutdown complete.")


if __name__ == "__main__":
    main()

