                            self.frame_count += 1
                            if self.frame_count > 10:
                                self.frame_count = 0
                                with self.get_frame_lock():
                                    if self.get_status() == 'streaming':
                                        if self.motion_detector.detect_motion(self.streaming_output.get_frame()):
                                            if self.twilio_client:
                                                self.twilio_client.send_sms("Motion Detected!")
                            time.sleep(0.1)
        else:
