        logging.error(f"Cascade file not found: {FACE_CASCADE_PATH}")
        return

    try:
        twilio_client = TwilioClientManager(TWILIO_ACCOUNT_SID, TWILIO_AUTH_TOKEN, TWILIO_PHONE_NUMBER, RECIPIENT_PHONE_NUMBER)
