import signal
import sys
import time
import numpy as np
import sounddevice as sd
import lib.utils.face as ft
import config
import lib.sound.load as sl

try:
    from picamera2 import Picamera2
except ImportError:
    Picamera2 = None

try:
    from gpiozero import Button
except ImportError:
    Button = None

try:
    from lib.sound.mixer import Mixer
except ImportError:
    Mixer = None

# ---------------------------------------------------------------------------
# Globals for cleanup
# ---------------------------------------------------------------------------
_running = True
_picam2 = None
_button = None
_mixer = None


def _cleanup():
    """Release every resource we hold."""
    global _running, _picam2, _button, _mixer
    _running = False
    if _mixer is not None:
        try:
            _mixer.stop()
        except Exception:
            pass
    if _button is not None:
        try:
            _button.close()
        except Exception:
            pass
    if _picam2 is not None:
        try:
            _picam2.close()
        except Exception:
            pass


def _signal_handler(signum, frame):
    """Handle SIGINT / SIGTERM for a clean shutdown."""
    global _running
    _running = False


def _init_mixer():
    """Initialise the mixer and return the Mixer instance."""
    if Mixer is None:
        print("Warning: lib.sound.mixer unavailable; running without audio.")
        return None
    try:
        return Mixer()
    except Exception as exc:
        print(f"Warning: failed to initialise mixer: {exc}")
        return None


def _init_camera():
    """Initialise Picamera2 if available."""
    global _picam2
    if Picamera2 is None:
        print("Warning: picamera2 not installed; running without camera.")
        return None
    try:
        cam = Picamera2()
        cam.configure(cam.create_preview_configuration(
            main={"size": (640, 480), "format": "RGB888"}))
        cam.start()
        _picam2 = cam
        return cam
    except Exception as exc:
        print(f"Warning: failed to initialise camera: {exc}")
        _picam2 = None
        return None


def _init_button():
    """Initialise the push-button input with internal pull-up."""
    global _button
    if Button is None:
        print("Warning: gpiozero not installed; running without button.")
        return None
    try:
        btn = Button(17, pull_up=True)
        _button = btn
        return btn
    except Exception as exc:
        print(f"Warning: failed to initialise button: {exc}")
        _button = None
        return None


def _init_face_recognizer():
    """Initialise the EigenFaceRecognizer model."""
    try:
        if not hasattr(ft, 'EigenFaceRecognizer'):
            print("Warning: lib.utils.face missing EigenFaceRecognizer; "
                  "running without face recognition.")
            return None
        recognizer = ft.EigenFaceRecognizer()
        print("Training EigenFaceRecognizer...")
        recognizer.train(config.TRAINING_FILE)
        print("Training complete.")
        return recognizer
    except Exception as exc:
        print(f"Warning: failed to initialise face recognizer: {exc}")
        return None


def _load_sounds():
    """Load welcome, wait, and later sound clips."""
    sounds = {
        "welcome": sl.load(config.WELCOME_PATH),
        "wait": sl.load(config.WAIT_PATH),
        "later": sl.load(config.LATER_PATH),
    }
    for name, sound in sounds.items():
        if sound is None:
            print(f"Warning: could not load {name}; using placeholder.")
            sounds[name] = sd.stop()
    return sounds


def _play_sound(sound, label):
    """Play a sound if it exists and the mixer is initialised."""
    if _mixer is None:
        return
    try:
        if sound is not None:
            _mixer.play(sound)
    except Exception as exc:
        print(f"Warning: failed to play sound '{label}': {exc}")


def _process_face(label, confidence):
    """Play the appropriate sound based on recognition result."""
    if label == config.POSITIVE_LABEL and confidence < config.POSITIVE_THRESHOLD:
        print("Unlocking door...")
        _play_sound(sounds["welcome"], "POSITIVE")
        return "POSITIVE"
    _play_sound(sounds["wait"], "POSITIVE")
    return "POSITIVE"


def main():
    global _running, _picam2, _button, _mixer

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    sounds = _load_sounds()
    mixer = _init_mixer()
    cam = _init_camera()
    btn = _init_button()
    recognizer = _init_face_recognizer()

    if mixer is None and cam is None and btn is None:
        print("No hardware available; exiting cleanly.")
        _cleanup()
        sys.exit(0)

    if cam is not None:
        try:
            cam.stop()
        except Exception:
            pass

    try:
        while _running:
            if btn is not None and btn.is_active:
                print("Button pressed; attempting face recognition...")
                try:
                    face_image, label, confidence = ft.detect_single(cam)
                except Exception as exc:
                    print(f"Warning: face detection failed: {exc}")
                    face_image = None
                    label = "unknown"
                    confidence = 0.0

                if face_image is not None:
                    print(f"Recognized face: {label} ({confidence:.2f})")
                    label = _process_face(label, confidence)
                else:
                    label = "unknown"
                    confidence = 0.0

                print(label)

            time.sleep(0.1)
    except Exception as exc:
        print(f"Unexpected error in main loop: {exc}")
    finally:
        _cleanup()


if __name__ == "__main__":
    main()

