import io
import os
import signal
import sys
import time
import logging
import threading
from http.server import BaseHTTPRequestHandler, HTTPServer
from typing import Optional, Tuple

import cv2
import numpy as np
from twilio.rest import Client
from twilio.base.exceptions import TwilioRestException

try:
    from greenlet import getcurrent as get_ident
except ImportError:
    try:
        from thread import get_ident
    except ImportError:
        from _thread import get_ident

try:
    from PIL import Image
except ImportError:
    Image = None

try:
    from transform import Transform
except ImportError:
    Transform = None

try:
    from camera import Camera
except ImportError:
    Camera = None

try:
    from twilio.base.exceptions import TwilioRestException
except ImportError:
    TwilioRestException = TwilioRestException

# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------
PORT = int(os.environ.get("PORT", 8000))
LOG_LEVEL = os.environ.get("LOG_LEVEL", "INFO").upper()
FACE_CASCADE_PATH = os.environ.get("FACE_CASCADE_PATH", "haarcascade_frontalface_default.xml")
TWILIO_ACCOUNT_SID = os.environ.get("TWILIO_ACCOUNT_SID")
TWILIO_AUTH_TOKEN = os.environ.get("TWILIO_AUTH_TOKEN")
TWILIO_PHONE_NUMBER = os.environ.get("TWILIO_PHONE_NUMBER")
RECIPIENT_PHONE_NUMBER = os.environ.get("RECIPIENT_PHONE_NUMBER")
MOTION_THRESHOLD = int(os.environ.get("MOTION_THRESHOLD", 1000000))
FACE_DETECTION_COOLDOWN = int(os.environ.get("FACE_DETECTION_COOLDOWN", 60))

# ---------------------------------------------------------------------------
# Logging
# ---------------------------------------------------------------------------
logging.basicConfig(
    level=getattr(logging, LOG_LEVEL, logging.INFO),
    format="%(asctime)s [%(levelname)s] %(message)s",
)
logger = logging.getLogger(__name__)

# ---------------------------------------------------------------------------
# Globals
# ---------------------------------------------------------------------------
_running = True
_face_cascade: Optional[cv2.CascadeClassifier] = None
_camera: Optional[Camera] = None
_twilio_client: Optional[Client] = None
_last_face_detection_time: float = 0.0
_lock = threading.Lock()


class StreamingOutput:
    """Thread-safe MJPEG stream writer."""

    def __init__(self):
        self.frame = None
        self.buffer = io.BytesIO()
        self.condition = threading.Condition()

    def write(self, buf: bytes):
        """Called by the HTTP handler for each JPEG chunk."""
        if buf.startswith(b"\xff\xd8"):
            with self.condition:
                self.frame = self.buffer.getvalue()
                self.condition.notify_all()
            self.buffer.seek(0)
            self.buffer.truncate()
        return self.buffer.write(buf)


class StreamingHandler(BaseHTTPRequestHandler):
    """HTTP handler for / and /stream.mjpg."""

    def do_GET(self):
        if self.path == "/":
            self.send_response(301)
            self.send_header("Location", "/index.html")
            self.end_headers()
        elif self.path == "/index.html":
            self.send_html_page()
        elif self.path == "/stream.mjpg":
            self.stream_video()
        else:
            self.send_error(404)
            self.end_headers()

    def send_html_page(self):
        html = (
            "<html><head><title>Raspberry Pi Security Camera</title></head>"
            "<body><h1>Raspberry Pi Security Camera</h1>"
            '<img src="/stream.mjpg" style="width:640px;height:480px;">'
            '<p>Motion threshold: %d, Face detection cooldown: %d s</p>' % (
                MOTION_THRESHOLD, FACE_DETECTION_COOLDOWN,
            )
            + "</body></html>"
        )
        self.send_response(200)
        self.send_header("Content-Type", "text/html")
        self.send_header("Content-Length", str(len(html)))
        self.end_headers()
        self.wfile.write(html.encode("utf-8"))

    def stream_video(self):
        self.send_response(200)
        self.send_header("Age", 0)
        self.send_header("Cache-Control", "no-cache, private")
        self.send_header("Pragma", "no-cache")
        self.send_header(
            "Content-Type",
            "multipart/x-mixed-replace; boundary=FRAME",
        )
        self.end_headers()

        try:
            while _running:
                with output.condition:
                    output.condition.wait()
                    frame = output.frame

                if frame is None:
                    continue

                try:
                    _, jpeg = cv2.imencode(".jpg", frame)
                    self.wfile.write(b"--FRAME\r\n")
                    self.send_header("Content-Type", "image/jpeg")
                    self.send_header("Content-Length", str(len(jpeg)))
                    self.end_headers()
                    self.wfile.write(jpeg.tobytes())
                    self.wfile.write(b"\r\n")
                except Exception as exc:
                    logger.error("JPEG encode failed: %s", exc)
                    self.send_error(500)
                    self.end_headers()
                    break
        except (BrokenPipeError, ConnectionResetError):
            logger.info("Client disconnected.")
        except Exception as exc:
            logger.error("Stream error: %s", exc)

    def log_message(self, fmt, *args):
        logger.debug("HTTP %s - %s", self.client_address[0], fmt % args)


def validate_face_cascade() -> bool:
    """Return True if a valid Haar cascade file exists."""
    if not os.path.isfile(FACE_CASCADE_PATH):
        logger.error("Face cascade file not found: %s", FACE_CASCADE_PATH)
        return False
    cascade = cv2.CascadeClassifier(FACE_CASCADE_PATH)
    if cascade.empty():
        logger.error("Failed to load face cascade classifier: %s", FACE_CASCADE_PATH)
        return False
    return True


def detect_motion(frame1: np.ndarray, frame2: np.ndarray) -> bool:
    """Return True if the absolute difference sum exceeds the threshold."""
    if frame1 is None or frame2 is None:
        return False
    if frame1.shape != frame2.shape:
        return False
    diff = cv2.absdiff(frame1, frame2)
    gray = cv2.cvtColor(diff, cv2.COLOR_BGR2GRAY)
    _, thresh = cv2.threshold(gray, 25, 255, cv2.THRESH_BINARY)
    return int(cv2.countNonZero(thresh)) > 0


def detect_face(frame: np.ndarray) -> Optional[Tuple[int, int, int, int]]:
    """Return (x, y, w, h) of the largest face bounding box, or None."""
    if _face_cascade is None:
        return None
    try:
        gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
        faces = _face_cascade.detectMultiScale(gray, scaleFactor=1.1, minNeighbors=5)
        if len(faces) > 0:
            return tuple(faces[0])
        return None
    except cv2.error as exc:
        logger.error("Face detection error: %s", exc)
        return None


def send_sms(message: str) -> None:
    """Send an SMS via Twilio with a 60-second cooldown between messages."""
    global _last_face_detection_time
    now = time.time()
    if now - _last_face_detection_time < FACE_DETECTION_COOLDOWN:
        logger.debug("SMS cooldown active; skipping.")
        return
    _last_face_detection_time = now
    if _twilio_client is None:
        logger.error("Twilio client not initialised; cannot send SMS.")
        return
    try:
        _twilio_client.messages.create(
            body=message,
            from_=TWILIO_PHONE_NUMBER,
            to=RECIPIENT_PHONE_NUMBER,
        )
        logger.info("SMS sent successfully.")
    except TwilioRestException as exc:
        logger.error("Twilio SMS error: %s", exc)
    except Exception as exc:
        logger.error("Unexpected SMS error: %s", exc)


def _signal_handler(signum, frame):
    global _running
    logger.info("Signal %s received; shutting down.", signum)
    _running = False


def main() -> None:
    global _face_cascade, _camera, _twilio_client

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    if not validate_face_cascade():
        logger.error("Cannot start: face cascade not available.")
        sys.exit(1)

    if not os.path.isfile(FACE_CASCADE_PATH):
        logger.error("Cannot start: face cascade file missing.")
        sys.exit(1)

    if not os.path.isfile(FACE_CASCADE_PATH):
        logger.error("Cannot start: face cascade file missing.")
        sys.exit(1)

    if not os.path.isfile(FACE_CASCADE_PATH):
        logger.error("Cannot start: face cascade file missing.")
