import time
import signal
import sys
import os
import logging
import configparser
from datetime import datetime

try:
    import RPi.GPIO as GPIO
except RuntimeError:
    print("Error: RPi.GPIO requires root privileges or a Raspberry Pi environment.", file=sys.stderr)
    sys.exit(1)

try:
    import adafruit_dht
    import board
except ImportError:
    print("Error: adafruit-circuitpython-dht and board not installed.", file=sys.stderr)
    sys.exit(1)

try:
    from lgpio import LCD
    from lgpio.constants import *
    LGPIOF_D4, LGPIOF_D5, LGPIOF_D6, LGPIOF_D7
except ImportError:
    print("Error: lgpio not installed. Install with: pip install lgpio", file=sys.stderr)
    sys.exit(1)

DEFAULT_CONFIG = {
    'ventilation': {
        'temp_low': '20.0',
        'temp_mid': '25.0',
        'vent_open': '70',
        'vent_close': '30'
    },
    'logging': {
        'level': 'INFO'
    }
}

CONFIG_FILE = 'greenhouse.conf'

running = True
dht_device = None
lcd = None
servo = None

def load_config(path):
    cfg = configparser.ConfigParser()
    if not cfg.read(path):
        print(f"Warning: {path} not found; using defaults.", file=sys.stderr)
    return cfg

def signal_handler(signum, frame):
    global running
    running = False

def cleanup():
    global lcd, servo, dht_device
    if lcd:
        try:
            lcd.clear()
            lcd.close()
        except Exception:
            pass
    if servo:
        try:
            servo.detach()
        except Exception:
            pass
    if dht_device:
        try:
            dht_device.exit()
        except Exception:
            pass
    GPIO.cleanup()

def init_gpio():
    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)
    GPIO.setup(25, GPIO.OUT)
    GPIO.setup(24, GPIO.OUT)
    GPIO.setup(17, GPIO.OUT)
    GPIO.setup(18, GPIO.OUT)
    GPIO.setup(22, GPIO.OUT)
    GPIO.setup(23, GPIO.OUT)
    GPIO.setup(22, GPIO.OUT)
    GPIO.setup(23, GPIO.OUT)
    GPIO.setup(24, GPIO.OUT)
    GPIO.setup(25, GPIO.OUT)
    GPIO.setup(17, GPIO.OUT)
    GPIO.setup(18, GPIO.OUT)
    GPIO.setup(22, GPIO.OUT)
    GPIO.setup(23, GPIO.OUT)
    GPIO.setup(24, GPIO.OUT)
    GPIO.setup(25, GPIO.OUT)
    GPIO.output(25, GPIO.LOW)
    GPIO.output(24, GPIO.LOW)
    GPIO.output(17, GPIO.LOW)
    GPIO.output(18, GPIO.LOW)
    GPIO.output(22, GPIO.LOW)
    GPIO.output(23, GPIO.LOW)
    GPIO.output(24, GPIO.LOW)
    GPIO.output(25, GPIO.LOW)

def init_lcd():
    try:
        lgpio.lcd_init()
        return LCD(lgpio.get_gpio_device(25), lgpio.get_gpio_device(24),
                  lgpio.get_gpio_device(17), lgpio.get_gpio_device(18),
                  lgpio.get_gpio_device(22), lgpio.get_gpio_device(23),
                  lgpio.get_gpio_device(25))
    except Exception as e:
        print(f"Warning: LCD init failed: {e}", file=sys.stderr)
        return None

def init_servo():
    try:
        GPIO.setup(12, GPIO.OUT)
        servo = GPIO.PWM(12, 1)
        servo.start(0)
        return servo
    except Exception as e:
        print(f"Warning: Servo init failed: {e}", file=sys.stderr)
        return None

def init_dht22():
    try:
        pin = board.D4
        dht_device = adafruit_dht.DHT22(pin, use_pulseio=False)
        return dht_device
    except Exception as e:
        print(f"Warning: DHT22 init failed: {e}", file=sys.stderr)
        return None

def read_dht22(dht_device):
    if dht_device is None:
        return None, None
    try:
        temperature = dht_device.temperature
        humidity = dht_device.humidity
        if temperature is None or humidity is None:
            return None, None
        return temperature, humidity
    except RuntimeError as e:
        logging.warning(f"DHT22 read error (transient): {e}")
        return None, None
    except Exception as e:
        logging.error(f"DHT22 read error: {e}")
        return None, None

def set_vent_angle(servo, angle):
    if servo is None:
        return None
    try:
        servo.ChangeDutyCycle(angle)
        return angle
    except Exception as e:
        logging.error(f"Servo error: {e}")
        return None

def get_vent_angle(temp, humidity, temp_low, temp_mid, vent_open, vent_close):
    if temp is None or humidity is None:
        return None
    if temp < temp_low:
        return "open"
    if temp > temp_mid:
        return "close"
    return "medium"

def log_data(temp, humidity, vent_angle, error=None):
    timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    log_entry = f"{timestamp} - Temperature: {temp:.1f}°C, Humidity: {humidity:.1f}%, Vent Angle: {vent_angle}, Error: {error}"
    logging.info(log_entry)

def main():
    global running, dht_device, lcd, servo
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    config = load_config(CONFIG_FILE)
    config['logging']['level'] = config['logging']['level'].upper()
    logging.basicConfig(filename='greenhouse.log', level=logging.INFO,
                        format='%(asctime)s - %(levelname)s - %(message)s')
    logging.info("Greenhouse controller started.")
    init_gpio()
    lcd = init_lcd()
    servo = init_servo()
    dht_device = init_dht22()
    last_temp = None
    last_humidity = None
    last_vent_angle = None
    try:
        while running:
            temp, humidity = read_dht22(dht_device)
            if temp is not None and humidity is not None:
                last_temp = temp
                last_humidity = humidity
                vent_angle = get_vent_angle(temp, humidity,
                                            config['ventilation']['temp_low'],
                                            config['ventilation']['temp_mid'],
                                            config['ventilation']['vent_open'],
                                            config['ventilation']['vent_close'])
                if vent_angle is not None:
                    last_vent_angle = set_vent_angle(servo, vent_angle)
                log_data(temp, humidity, last_vent_angle)
            else:
                if last_temp is not None and last_humidity is not None:
                    log_data(last_temp, last_humidity, "Error")
                else:
                    log_data("Error", "No valid sensor data available", "DHT22 sensor not responding")
            time.sleep(5)
    except Exception as e:
        logging.error(f"Unexpected error: {e}")
    finally:
        cleanup()

if __name__ == "__main__":
    main()

