import smbus
import time
import signal
import sys

# PCF8574 I2C address (default when SDA=3, SCL=5)
PCF8574_ADDR = 0x07

# Proximity sensor pins (active-low)
SENSOR_PINS = [0, 1, 2, 3, 4, 5, 6, 7]

# Global flag for graceful shutdown
_running = True


def _signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for clean shutdown."""
    global _running
    _running = False


def _read_sensor(bus, sensor_index):
    """Read a single PCF8574 port pin; return 0 or 1, or None on error."""
    try:
        return bus.read_byte_data(PCF8574_ADDR, sensor_index)
    except OSError as e:
        print(f"I2C read error on sensor {sensor_index}: {e}")
        return None


def main():
    global _running

    # Register signal handlers for graceful termination
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    # Initialize I2C bus
    try:
        bus = smbus.SMBus(1)
    except OSError as e:
        print(f"Failed to open I2C bus 1: {e}")
        sys.exit(1)

    # Verify device presence
    try:
        bus.read_byte_data(PCF8574_ADDR, 0)
    except OSError as e:
        print(f"No device found at I2C address 0x{PCF8574_ADDR:02X}: {e}")
        bus.close()
        sys.exit(1)

    print("Proximity sensor monitoring started. Press Ctrl+C to exit.")

    try:
        while _running:
            for i in range(8):
                if not _running:
                    break

                sensor_value = _read_sensor(bus, i)
                if sensor_value is None:
                    print(f"Error reading sensor {i}. Retrying in 1 second...")
                    time.sleep(1)
                    continue

                if sensor_value == 0:
                    print(f"Obstacle detected by sensor {i}")
                else:
                    print(f"Sensor {i} is clear")

            if _running:
                time.sleep(0.1)

    except Exception as e:
        print(f"Unexpected error: {e}")

    finally:
        bus.close()
        print("I2C bus closed. Exiting.")


if __name__ == "__main__":
    main()

