import time
import sys

# DHT11 data line connected to BCM GPIO4 (physical pin 7)
DATA_PIN = 4
MAX_RETRIES = 5
RETRY_DELAY = 2  # seconds between retries (DHT11 needs >=1 s between reads)

def read_dht11():
    """
    Attempt to read temperature from a DHT11 sensor.
    Returns the temperature in Celsius as a float, or None on failure.
    """
    for attempt in range(1, MAX_RETRIES + 1):
        try:
            # Use the adafruit-circuitpython-dht library for robust DHT11 support
            import board
            import adafruit_dht
            sensor = adafruit_dht.DHT11(board.D4)
            temperature = sensor.temperature
            sensor.exit()
            if temperature is not None:
                return temperature
            else:
                print(f"Attempt {attempt}/{MAX_RETRIES}: Sensor returned None, retrying...")
        except Exception as e:
            print(f"Attempt {attempt}/{MAX_RETRIES}: Read failed: {e}, retrying...")
        if attempt < MAX_RETRIES:
            time.sleep(RETRY_DELAY)
    return None

def main():
    temperature = read_dht11()
    if temperature is not None:
        print(f"Temperature: {temperature:.1f} °C")
        sys.exit(0)
    else:
        print("Error: Could not read temperature from DHT11 sensor after "
              f"{MAX_RETRIES} attempts. Check wiring and sensor presence.")
        sys.exit(1)

if __name__ == "__main__":
    try:
        main()
    except KeyboardInterrupt:
        print("\nProgram terminated by user.")
        sys.exit(0)

