import json
import random
import time
import signal
import sys
import paho.mqtt.client as mqtt

BROKER_HOST = "test.mosquitto.org"
BROKER_PORT = 1883
KEEPALIVE = 60
TOPIC = "classroom/temperature"
NUM_MESSAGES = 5

running = True

def signal_handler(signum, frame):
    global running
    running = False

def on_connect(client, userdata, flags, reason_code, properties):
    if reason_code == 0:
        print("Connected to broker successfully.")
    else:
        print(f"Connection failed with reason code: {reason_code}")

def on_publish(client, userdata, mid, reason_code, properties):
    if reason_code != 0:
        print(f"Publish failed for message ID {mid} with reason code: {reason_code}")

def generate_temperature_reading():
    return round(random.uniform(19.00, 26.00), 2)

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    client = mqtt.Client(mqtt.CallbackAPIVersion.VERSION2)
    client.on_connect = on_connect
    client.on_publish = on_publish

    try:
        for attempt in range(3):
            if not running:
                print("Shutdown requested; aborting connection attempt.")
                break
            try:
                client.connect(BROKER_HOST, BROKER_PORT, KEEPALIVE)
                client.loop_start()
                break
            except Exception as e:
                print(f"Connection attempt {attempt + 1}/3 failed: {e}")
                if attempt < 2:
                    time.sleep(2)
        else:
            print("Failed to connect to broker after three attempts.")
            return 1

        message_count = 0
        while running and message_count < NUM_MESSAGES:
            temperature = generate_temperature_reading()
            payload = json.dumps({"temperature": temperature, "index": message_count})
            result = client.publish(TOPIC, payload, qos=0)
            if result.rc == mqtt.MQTT_ERR_SUCCESS:
                message_count += 1
                print(f"Published message {message_count}: {payload}")
            else:
                print(f"Publish failed with return code: {result.rc}")

        if message_count == NUM_MESSAGES:
            print(f"Successfully published {message_count} messages.")
            return 0
        else:
            print(f"Publishing failed after {message_count} messages.")
            return 1

    except Exception as e:
        print(f"An error occurred: {e}")
        return 1
    finally:
        client.loop_stop()
        client.disconnect()
        print("Disconnected from broker.")

if __name__ == "__main__":
    sys.exit(main())

