import time
import logging
import signal
import sys
import smbus2

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

DHT20_I2C_ADDR = 0x76
DHT20_STATUS_REG = 0x00
DHT20_DATA_REG = 0x01
DHT20_CRC_REG = 0x02
DHT20_HUMIDITY_REG = 0x03
DHT20_TEMP_REG = 0x04

DHT20_STATUS_OK = 0x00
DHT20_STATUS_CRC_ERR = 0x01
DHT20_STATUS_NACK = 0x02
DHT20_STATUS_BUS_ERR = 0x03
DHT20_STATUS_ERR_MASK = 0x07
DHT20_STATUS_OK_MASK = 0x00
DHT20_STATUS_CRC_ERR_MASK = 0x01
DHT20_STATUS_NACK_MASK = 0x02
DHT20_STATUS_BUS_ERR_MASK = 0x03

DHT20_CRC_POLYNOMIAL = 0x10
DHT20_EXPECTED_STATUS = DHT20_STATUS_OK

class DHT20:
    def __init__(self, bus_num=1, retry_delay=2.0, max_retries=5):
        self.bus_num = bus_num
        self.retry_delay = retry_delay
        self.max_retries = max_retries
        self.bus = None
        self._closed = False
        self._install_signal_handlers()

    def _install_signal_handlers(self):
        for sig in (signal.SIGINT, signal.SIGTERM):
            signal.signal(sig, self._signal_handler)

    def _signal_handler(self, signum, frame):
        logger.info(f"Signal {signum} received; closing DHT20 bus.")
        self.close()
        sys.exit(0)

    def _open_bus(self):
        try:
            self.bus = smbus2.SMBus(self.bus_num)
        except OSError as e:
            logger.error(f"Failed to open I2C bus {self.bus_num}: {e}")
            return False
        return True

    def _close_bus(self):
        if self.bus is not None:
            try:
                self.bus.close()
            except OSError:
                pass
            self.bus = None

    def _read_register(self, register):
        if self.bus is None:
            logger.error("I2C bus is not open.")
            return None
        try:
            return self.bus.read_byte_data(DHT20_I2C_ADDR, register)
        except OSError as e:
            logger.error(f"I2C read error at register 0x{register:02X}: {e}")
            return None

    def _read_bytes(self, register, length):
        if self.bus is None:
            logger.error("I2C bus is not open.")
            return None
        try:
            return self.bus.read_i2c_block_data(DHT20_I2C_ADDR, register, length)
        except OSError as e:
            logger.error(f"I2C block read error at register 0x{register:02X}: {e}")
            return None

    def _calculate_crc8(self, data):
        crc = 0xFF
        for byte in data:
            crc ^= byte
            for _ in range(8):
                if crc & 0x80:
                    crc = ((crc << 1) ^ DHT20_CRC_POLYNOMIAL) & 0xFF
                else:
                    crc = (crc << 1) & 0xFF
        return crc

    def _read_dht20_data(self):
        if self.bus is None:
            logger.error("I2C bus is not open.")
            return None, None, True

        for attempt in range(self.max_retries):
            if self._wait_for_status(DHT20_STATUS_OK):
                break
            if attempt < self.max_retries - 1:
                time.sleep(self.retry_delay)

        if self.bus is None:
            logger.error("I2C bus is not open after retries.")
            return None, None, True

        data = self._read_bytes(DHT20_DATA_REG, 7)
        if data is None:
            logger.error("Failed to read DHT20 data.")
            return None, None, True

        humidity_raw = (data[1] << 12) | (data[2] << 4) | (data[3] >> 4)
        temperature_raw = ((data[3] & 0x0F) << 16) | (data[4] << 8) | data[5]
        crc_error_flag = self._calculate_crc8(data[:6]) != data[6]

        if crc_error_flag:
            logger.warning("CRC error detected in DHT20 data.")
            return None, None, True

        humidity = (humidity_raw / 2**20) * 100.0
        temperature = (temperature_raw / 2**20) * 200.0 - 50.0

        return temperature, humidity, crc_error_flag

    def _wait_for_status(self, expected_status):
        for attempt in range(self.max_retries):
            if self._read_register(DHT20_STATUS_REG) is not None:
                if (self._read_register(DHT20_STATUS_REG) & DHT20_STATUS_OK_MASK) == expected_status:
                    return True
            else:
                logger.warning(f"No status received (attempt {attempt + 1}/{self.max_retries}).")
            if attempt < self.max_retries - 1:
                time.sleep(self.retry_delay)
        logger.error(f"Failed to get valid DHT20 status after {self.max_retries} attempts.")
        return False

    def read(self):
        if self._closed:
            logger.error("DHT20 object is closed; cannot read.")
            return None, None, True

        if not self._open_bus():
            return None, None, True

        try:
            temperature, humidity, crc_error_flag = self._read_dht20_data()
            if crc_error_flag:
                return None, None, True
            return temperature, humidity, False
        finally:
            self._close_bus()

    def close(self):
        if self._closed:
            return
        self._closed = True
        self._close_bus()

if __name__ == '__main__':
    sensor = DHT20(bus_num=1, retry_delay=2.0, max_retries=5)
    try:
        while True:
            temp, hum, err = sensor.read()
            if err:
                logger.error(f"Read failed: {err}")
            else:
                logger.info(f"Temperature: {temp:.2f} C, Humidity: {hum:.2f} %")
    except KeyboardInterrupt:
        logger.info("Interrupted by user.")
    finally:
        sensor.close()

