import asyncio
import json
import logging
import logging.handlers
import signal
import sys
import time
from typing import Dict, List, Optional

import gpiozero

# Constants for GPIO pin numbers (BCM numbering)
DHT22_PIN = 4
TRANSMITTER_PIN = 17

# Default configuration values
DEFAULT_CONFIG = {
    "dht22_read_interval": 60,
    "log_file": "greenhouse.log",
    "log_level": "INFO",
    "outlet_configurations": [
        {"name": "Outlet 1", "unit_code": "1", "state_bit": "1"},
        {"name": "Outlet 2", "unit_code": "2", "state_bit": "1"},
        {"name": "Outlet 3", "unit_code": "3", "state_bit": "1"},
    ],
}

# Global state
config: Dict = {}
outlet_configurations: List = []
dht22_read_interval: int = 60
log_level: str = "INFO"
logger: Optional[logging.Logger] = None
shutdown_event = asyncio.Event()

# 433 MHz PT2262-style command encoding
# Bit 7: long high, Bit 6: short high, Bit 5: short low, Bit 4: long low, Bit 3: sync high, Bit 2: sync low, Bit 1: sync high, Bit 0: sync low
SYNC_HIGH = 0b11000000
SYNC_LOW = 0b00011000
SHORT_HIGH = 0b00001100
SHORT_LOW = 0b00000110
LONG_HIGH = 0b11000000
LONG_LOW = 0b00000000

# Global flag to control the main loop
running = True


def load_configuration(config_file: str = "greenhouse_config.json") -> None:
    """Loads configuration from a JSON file, providing default values if the file is missing or invalid."""
    global config, outlet_configurations, dht22_read_interval, log_level

    try:
        with open(config_file, "r") as f:
            config = json.load(f)

        # Merge with defaults, overriding only keys present in the config file
        defaults = DEFAULT_CONFIG.copy()
        merged = {**defaults, **config}
        config = merged

        # Validate the configuration
        if not isinstance(merged.get("dht22_read_interval"), int) or merged["dht22_read_interval"] <= 0:
            raise ValueError("dht22_read_interval must be a positive integer.")
        if not isinstance(merged.get("log_level"), str) or merged["log_level"] not in ["DEBUG", "INFO", "WARNING", "ERROR", "CRITICAL"]:
            raise ValueError("log_level must be one of DEBUG, INFO, WARNING, ERROR, CRITICAL.")

        # Build outlet configurations
        outlet_configurations = []
        for conf in merged.get("outlet_configurations", []):
            if not isinstance(conf, dict) or "name" not in conf or "unit_code" not in conf or "state_bit" not in conf:
                raise ValueError("Each outlet configuration must have 'name', 'unit_code', and 'state_bit' keys.")
            outlet_configurations.append(conf)

        dht22_read_interval = merged.get("dht22_read_interval", 60)
        log_level = merged.get("log_level", "INFO")

    except (FileNotFoundError, json.JSONDecodeError, ValueError) as e:
        print(f"Error loading configuration: {e}. Using default configuration.")
        config = DEFAULT_CONFIG.copy()
        outlet_configurations = []
        dht22_read_interval = 60
        log_level = "INFO"


def setup_logging(log_file: str, log_level: str) -> None:
    """Sets up the logging configuration with a rotating file handler."""
    global logger
    logger = logging.getLogger(__name__)
    logger.setLevel(getattr(logging, log_level.upper(), logging.INFO))

    # Remove any existing handlers to avoid duplicates
    logger.handlers.clear()

    handler = logging.handlers.RotatingFileHandler(
        log_file, maxBytes=1024 * 1024, backupCount=5
    )
    formatter = logging.Formatter(
        "%(asctime)s - %(levelname)s - %(message)s",
        datefmt="%Y-%m-%d %H:%M:%S",
    )
    handler.setFormatter(formatter)
    logger.addHandler(handler)

    # Also log to console for debugging
    console = logging.StreamHandler()
    console.setFormatter(formatter)
    logger.addHandler(console)


def read_dht22_sensor(dht22_pin: int) -> Optional[Dict]:
    """Reads temperature and humidity from the DHT22 sensor using gpiozero."""
    try:
        dht = gpiozero.DHT22(dht22_pin)
        temperature = dht.temperature
        humidity = dht.humidity
        dht.close()
        return {"temperature": temperature, "humidity": humidity}
    except (RuntimeError, OSError) as e:
        print(f"Error reading DHT22 sensor: {e}")
        return None
    except Exception as e:
        print(f"Unexpected error reading DHT22 sensor: {e}")
        return None


def encode_command(unit_code: str, state_bit: str) -> str:
    """Encodes a command for the 433 MHz transmitter using the PT2262 protocol."""
    if state_bit == "1":
        return (
            SYNC_HIGH
            + SHORT_HIGH
            + state_bit
            + LONG_HIGH
            + LONG_LOW
        )
    else:
        return (
            SYNC_HIGH
            + SHORT_HIGH
            + state_bit
            + LONG_LOW
            + LONG_HIGH
        )


def send_command(transmitter: gpiozero.OutputDevice, command: str) -> bool:
    """Sends a command to the 433 MHz transmitter with retry logic and debounce."""
    for attempt in range(3):
        try:
            transmitter.on()
            time.sleep(0.001)
            transmitter.off()
            time.sleep(0.001)
            transmitter.on()
            time.sleep(0.001)
            transmitter.off()
            time.sleep(0.001)
            transmitter.on()
            time.sleep(0.001)
            transmitter.off()
            time.sleep(0.001)
            transmitter.on()
            time.sleep(0.03)  # 300 µs sync pulse
            time.sleep(0.03)
            return True
        except (RuntimeError, OSError) as e:
            print(f"Error sending command (attempt {attempt + 1}/3): {e}")
            if attempt < 2:
                time.sleep(0.1)
    return False


def control_outlet(transmitter: gpiozero.OutputDevice, unit_code: str, state_bit: str) -> bool:
    """Controls a specific outlet by sending the appropriate command."""
    command = encode_command(unit_code, state_bit)
    return send_command(transmitter, command)


def control_outlets(transmitter: gpiozero.OutputDevice, outlet_configurations: List) -> None:
    """Controls multiple outlets based on their configuration."""
    for config in outlet_configurations:
        if not config:
            continue
        unit_code = config["unit_code"]
        state_bit = config["state_bit"]
        if state_bit == "1":
            control_outlet(transmitter, unit_code, state_bit)
        else:
            control_outlet(transmitter, unit_code, state_bit)


def control_outlet_by_name(transmitter: gpiozero.OutputDevice, name: str) -> bool:
    """Searches for an outlet by name and controls it."""
    for config in outlet_configurations:
        if config["name"] == name:
            return control_outlet(transmitter, config["unit_code"], config["state_bit"])
    return False


def control_all_outlets(transmitter: gpiozero.OutputDevice) -> None:
    """Controls all configured outlets."""
    control_outlets(transmitter, outlet_configurations)


def get_sensor_data(dht22_pin: int) -> Optional[Dict]:
    """Reads temperature and humidity from the DHT22 sensor."""
    return read_dht22_sensor(dht22_pin)


async def sensor_reading_task(
    dht22_pin: int,
    transmitter: gpiozero.OutputDevice,
    config: Dict,
    dht22_read_interval: int,
    shutdown_event: asyncio.Event,
) -> None:
    """Asynchronous task to read sensor data and control outlets."""
    while not shutdown_event.is_set():
        try:
            sensor_data = get_sensor_data(dht22_pin)
            if sensor_data:
                print(f"Sensor data: {sensor_data}")
                for config in outlet_configurations:
                    if config:
                        if config["state_bit"] == "1":
                            control_outlet_by_name(transmitter, config["name"])
                        else:
                            control_outlet_by_name(transmitter, config["name"])
            else:
                print("Failed to read sensor data.")
        except Exception as e:
            print(f"Error in sensor reading task: {e}")
        await asyncio.sleep(dht22_read_interval)


def handle_command(command: str, transmitter: gpiozero.OutputDevice, config: Dict) -> None:
    """Handles commands to control the greenhouse remotely."""
    if command == "on":
        for config in outlet_configurations:
            if config:
                if config["state_bit"] == "1":
                    control_outlet_by_name(transmitter, config["name"])
                else:
                    print("Outlet already on.")
    elif command == "off":
