import time
import datetime
import random
import sqlite3
import logging
import sys
import signal

try:
    import RPi.GPIO as GPIO
except RuntimeError:
    GPIO = None

CONFIG_FILE = 'config.txt'
TEMP_MIN = 25.0
TEMP_MAX = 30.0
DEFAULT_TEMP_MIN = 25.0
DEFAULT_TEMP_MAX = 30.0
DEFAULT_VENT_OPEN_TEMP = 30.0
DEFAULT_VENT_CLOSED_TEMP = 25.0
DEFAULT_VENT_OPEN_PERCENT = 50.0
DEFAULT_VENT_CLOSED_PERCENT = 0.0
DEFAULT_TEMP_TOLERANCE = 1.0
DEFAULT_TEMP_READ_INTERVAL = 60
DEFAULT_LOG_LEVEL = 'DEBUG'
DEFAULT_LOG_FILE = 'greenhouse_vent.log'
DEFAULT_GPIO_PINS = '17,18,27'

logging.basicConfig(
    filename=DEFAULT_LOG_FILE,
    level=logging.DEBUG,
    format='%(asctime)s - %(levelname)s - %(message)s'
)

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def read_config(config_file):
    config = {}
    try:
        with open(config_file, 'r') as f:
            for line in f:
                line = line.strip()
                if not line or line.startswith('#'):
                    continue
                if '=' not in line:
                    logging.warning(f"Skipping malformed config line: {line}")
                    continue
                key, value = line.split('=', 1)
                key = key.strip()
                value = value.strip()
                if key in ('TEMP_MIN', 'TEMP_MAX'):
                    config[key] = float(value)
                elif key in ('TEMP_OPEN_TEMP', 'TEMP_CLOSED_TEMP'):
                    config[key] = float(value)
                elif key in ('TEMP_OPEN_PERCENT', 'TEMP_CLOSED_PERCENT'):
                    config[key] = float(value)
                elif key in ('TEMP_TOLERANCE', 'TEMP_READ_INTERVAL'):
                    config[key] = float(value)
                elif key in ('LOG_LEVEL', 'LOG_FILE'):
                    config[key] = str(value)
                elif key in ('GPIO_PINS'):
                    config[key] = [int(pin) for pin in value.split(',')]
    except FileNotFoundError:
        logging.warning(f"Config file '{config_file}' not found; using defaults.")
    except Exception as e:
        logging.error(f"Error reading config: {e}; using defaults.")
    return config

def read_temperature():
    return random.uniform(TEMP_MIN, TEMP_MAX)

def calculate_vent_position(temperature, temp_open, temp_closed):
    if temperature > temp_open:
        return min(100.0, (temperature - temp_open) / (temp_open - temp_closed) * 100.0)
    elif temperature < temp_closed:
        return max(0.0, (temp_closed - temperature) / (temp_closed - temp_open) * 100.0)
    else:
        return 50.0

def log_data(timestamp, temperature, vent_position):
    try:
        conn = sqlite3.connect('greenhouse_data', timeout=5)
        cursor = conn.cursor()
        cursor.execute('''
            CREATE TABLE IF NOT EXISTS data (
                timestamp TEXT,
                temperature REAL,
                vent_position REAL
            )
        ''')
        cursor.execute(
            'INSERT INTO data VALUES (?, ?, ?)',
            (timestamp, temperature, vent_position)
        )
        conn.commit()
        conn.close()
    except sqlite3.Error as e:
        logging.error(f"Database error: {e}")

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    config = read_config(CONFIG_FILE)
    temp_min = config.get('TEMP_MIN', DEFAULT_TEMP_MIN)
    temp_max = config.get('TEMP_MAX', DEFAULT_TEMP_MAX)
    temp_open = config.get('TEMP_OPEN_TEMP', DEFAULT_TEMP_OPEN_TEMP)
    temp_closed = config.get('TEMP_CLOSED_TEMP', DEFAULT_VENT_CLOSED_TEMP)
    temp_tolerance = config.get('TEMP_TOLERANCE', DEFAULT_TEMP_TOLERANCE)
    temp_read_interval = config.getint('TEMP_READ_INTERVAL', DEFAULT_TEMP_READ_INTERVAL)
    log_level = config.get('LOG_LEVEL', DEFAULT_LOG_LEVEL)
