import signal
import sys
import time

import adafruit_dht
import board
from adafruit_dht import DHT11

try:
    from adafruit_motor import adafruit_neopixel
    from adafruit_neopixel.effects import Color
except ImportError:
    print("Error: adafruit-circuitpython-neopixel and adafruit-circuitpython-dht not installed.")
    sys.exit(1)

# --- Configuration -----------------------------------------------------------
DHT_PIN = board.D4          # BCM 4 (physical pin 7)
RED_PIN = 17
GREEN_PIN = 27
BLUE_PIN = 22
PWM_FREQ = 100              # Hz
SAMPLE_INTERVAL = 1.0       # seconds (DHT11 max sampling rate ~1 Hz)
RETRY_DELAY = 2.0           # seconds between retries on read failure

# --- Globals for cleanup -----------------------------------------------------
_strip = None
_dht = None
_running = True


def cleanup():
    """Release hardware resources on every exit path."""
    global _strip, _dht
    if _strip is not None:
        try:
            _strip.clear()
        except Exception:
            pass
        try:
            _strip.cleanup()
        except Exception:
            pass
        _strip = None
    if _dht is not None:
        try:
            _dht.exit()
        except Exception:
            pass
        _dht = None


def handle_signal(signum, frame):
    """Graceful shutdown on SIGINT / SIGTERM."""
    global _running
    _running = False


def read_temperature():
    """Return the temperature in °C, or None on failure."""
    try:
        temp = _dht.temperature
        if temp is None:
            return None
        return float(temp)
    except RuntimeError as exc:
        # DHT11 checksum / timing glitches are common; log and retry.
        print(f"Warning: DHT11 read failed ({exc}). Retaining previous state.")
        return None
    except Exception as exc:
        print(f"Warning: unexpected DHT11 error ({exc}). Retaining previous state.")
        return None


def set_color(temperature):
    """Map temperature to an RGB LED colour and apply PWM duty cycle."""
    if temperature is None:
        return
    # Temperature range: 0–40 °C -> 0–100 % duty (Red)
    # 40 °C  -> 100 % Red, 0 % Green, 0 % Blue
    # 0 °C   -> 0 % Red, 100 % Green, 0 % Blue
    duty = min(100, int(temperature / 40.0 * 100))
    if temperature <= 0:
        red, green, blue = 0, 0, 0
    elif temperature <= 40:
        red, green, blue = duty, 0, 0
    else:
        red, green, blue = 0, 100, 0
    try:
        _strip.set_pixel(red, green, blue)
        _strip.show()
    except Exception as exc:
        print(f"Warning: failed to update LEDs: {exc}")


def main():
    global _strip, _dht

    # --- Initialise DHT11 ----------------------------------------------------
    try:
        _dht = DHT11(DHT_PIN, use_pulseio=False)
    except Exception as exc:
        print(f"Fatal: failed to initialise DHT11 on BCM 4: {exc}")
        sys.exit(1)

    # --- Initialise RGB LED (neopixel) ---------------------------------------
    try:
        _strip = adafruit_neopixel.NeoPixel(
            RED_PIN, GREEN_PIN, BLUE_PIN,
            PWM_FREQ,
            brightness=1.0,
            auto_write=False,
        )
    except Exception as exc:
        print(f"Fatal: failed to initialise RGB LED on pins "
              f"(R={RED_PIN}, G={GREEN_PIN}, B={BLUE_PIN}): {exc}")
        cleanup()
        sys.exit(1)

    # --- Signal handlers -----------------------------------------------------
    signal.signal(signal.SIGINT, handle_signal)
    signal.signal(signal.SIGTERM, handle_signal)

    # --- Main loop -----------------------------------------------------------
    try:
        while _running:
            temperature = read_temperature()
            set_color(temperature)
            time.sleep(SAMPLE_INTERVAL)
    except Exception as exc:
        print(f"Fatal: unexpected error in main loop: {exc}")
    finally:
        cleanup()


if __name__ == "__main__":
    main()

