#!/usr/bin/env python3
"""
CPU temperature monitor for Raspberry Pi 4 Model B.

Reads the on-board CPU temperature every 5 seconds and prints it to two
decimal places.  A missing thermal file is treated as a per-read error so
that the program does not fail at startup.
"""

import time
import sys

try:
    from gpiozero import CPUTemperature
except ImportError:
    print("Error: gpiozero is not installed.  Install with: sudo apt install python3-gpiozero",
          file=sys.stderr)
    sys.exit(1)


def read_cpu_temp() -> float:
    """
    Lazily create a CPUTemperature object and return its value in °C.

    Raises FileNotFoundError if the thermal file cannot be opened,
    any other exception if the reading fails.
    """
    try:
        return float(CPUTemperature().temperature)
    except FileNotFoundError:
        raise
    except Exception as exc:
        raise RuntimeError(f"Error reading CPU temperature: {exc}") from exc


def main() -> int:
    """Continuously print the CPU temperature every 5 seconds."""
    try:
        while True:
            try:
                temp_c = read_cpu_temp()
                print(f"CPU Temperature: {temp_c:.2f} °C")
            except FileNotFoundError:
                print("Error: thermal file not found. Is this running on a Raspberry Pi?",
                      file=sys.stderr)
            except RuntimeError as exc:
                print(f"Error: {exc}", file=sys.stderr)
            except KeyboardInterrupt:
                print("Program terminated")
                return 0
            time.sleep(5)
    except Exception as exc:
        print(f"Unexpected error: {exc}", file=sys.stderr)
        return 1


if __name__ == "__main__":
    sys.exit(main())

