import urllib.error
import board
import adafruit_dht

CONFIG_FILE = "config.json"

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(message)s",
)
logger = logging.getLogger(__name__)

_running = True
_dht_device = None


def _signal_handler(signum, frame):
    global _running
    logger.info("Signal %s received, shutting down...", signum)
    _running = False


def load_config(path: str) -> dict:
    try:
        with open(path, "r") as f:
            return json.load(f)
    except FileNotFoundError:
        logger.error("Config file not found: %s", path)
        raise
    except json.JSONDecodeError as exc:
        logger.error("Invalid JSON in config: %s", exc)
        raise


def read_dht22(device: adafruit_dht.DHT22) -> tuple[float, float]:
    try:
        temperature = device.temperature
        humidity = device.humidity
        if temperature is None or humidity is None:
            raise RuntimeError("Sensor returned None")
        if not (-40.0 <= temperature <= 80.0):
            raise ValueError(f"Temperature out of range: {temperature}")
        if not (0.0 <= humidity <= 100.0):
            raise ValueError(f"Humidity out of range: {humidity}")
        return temperature, humidity
    except RuntimeError as exc:
        logger.warning("DHT22 read error (simulation active): %s", exc)
        return 20.0, 60.0
    except Exception as exc:
        logger.warning("Unexpected DHT22 error (simulation active): %s", exc)
        return 20.0, 60.0


def validate_readings(temperature: float, humidity: float) -> bool:
    if not (-40.0 <= temperature <= 80.0):
        logger.warning("Temperature out of range: %.1f", temperature)
        return False
    if not (0.0 <= humidity <= 100.0):
        logger.warning("Humidity out of range: %.1f", humidity)
        return False
    return True


def moving_average(samples: list[float], window: int = 5) -> float:
    if not samples:
        return 0.0
    if len(samples) < window:
        return sum(samples) / len(samples)
    return sum(samples[-window:]) / window


def send_webhook(url: str, payload: dict) -> bool:
    for attempt in (1, 3, 9):
        try:
            req = urllib.request.Request(
                url,
                data=json.dumps(payload).encode("utf-8"),
                headers={"Content-Type": "application/json"},
            )
            with urllib.request.urlopen(req, timeout=10) as resp:
                if 200 <= resp.status < 300:
                    return True
            logger.warning("Webhook attempt %d failed: HTTP %d", attempt, resp.status)
        except urllib.error.URLError as exc:
            logger.warning("Webhook attempt %d URL error: %s", attempt, exc)
        except Exception as exc:
            logger.warning("Webhook attempt %d error: %s", attempt, exc)
        time.sleep(attempt)
    logger.error("All webhook attempts failed after 300s pause.")
    return False


def main() -> None:
    global _dht_device

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    config = load_config(CONFIG_FILE)
    url = config["webhook"]["url"]
    interval = config["interval"]
    window = config["window"]
    max_retries = config["max_retries"]
    pause = config["pause"]

    try:
        _dht_device = adafruit_dht.DHT22(board.D4, use_pulseio=False)
        logger.info("DHT22 initialized on BCM pin 4.")
    except Exception as exc:
        logger.error("Failed to initialize DHT22: %s", exc)
        sys.exit(1)

    last_webhook_time = 0.0
    last_error_time = 0.0
    last_error_type = None

    try:
