                logger.warning("Error type: %s", last_error_type)

            if last_error_time > 0.0 and (time.monotonic() - last_error_time) < 300.0:
                logger.info("Retrying webhook in %.0fs...", 300 - (time.monotonic() - last_error_time))
                if not send_webhook(url, {"temperature": temperature, "humidity": humidity}):
                    logger.error("Webhook failed after 300s pause.")
                    last_error_time = time.monotonic()
                    last_error_type = "webhook_failure"
                    continue

            if last_error_time > 0.0:
                last_error_time = time.monotonic()
                last_error_type = None

            samples = []
            for _ in range(window):
                samples.append(temperature)
                samples.append(humidity)
