    logging.error("Required libraries not installed. Install with: pip install adafruit-circuitpython-dht")
    sys.exit(1)

import config

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

DEGREE_CELSIUS = '\u00B0C'

running = True

def signal_handler(signum, frame):
    global running
    logger.info(f"Signal {signum} received, shutting down...")
    running = False

def init_dht22():
    try:
        pin_map = {4: board.D4}
        pin = pin_map.get(config.dhtegpiopin)
        if pin is None:
            raise ValueError(f"Unsupported BCM pin {config.dhtegpiopin}")
        dht_device = adafruit_dht.DHT22(pin, use_pulseio=False)
        logger.info(f"DHT22 initialized on BCM pin {config.dhtegpiopin}")
        return dht_device
    except Exception as e:
        logger.error(f"Failed to initialize DHT22: {e}")
        return None

def publish_mqtt_message(client, topic, payload, retain=True, qos=0):
    try:
        full_topic = f"homie/{config.homieclientid}/{config.homienodes}/{topic}"
        info = client.publish(full_topic, str(payload).encode(), retain=retain, qos=qos)
        info.wait_for_publish(timeout=5)
        logger.debug(f"Published to {full_topic}: {payload}")
    except Exception as e:
        logger.error(f"Error publishing to MQTT topic {topic}: {e}")

def on_connect(client, userdata, flags, reason_code, properties):
    if reason_code == 0:
        logger.info("Connected to MQTT broker")
        client.subscribe(f"homie/{config.homieclientid}/$state", qos=0)
        client.subscribe(f"homie/{config.homieclientid}/{config.homienodes}/$state", qos=0)
    else:
        logger.error(f"Failed to connect to MQTT broker, reason code: {reason_code}")

def on_message(client, userdata, msg):
    try:
        payload = msg.payload.decode()
        logger.info(f"Received Homie state message: {payload}")
        if payload == "$state":
            client.publish(f"homie/{config.homieclientid}/$state", "active", retain=True, qos=0)
    except Exception as e:
        logger.error(f"Error processing MQTT message: {e}")

def mqtt_connect():
    client = mqtt.Client(
        mqtt.CallbackAPIVersion.VERSION2,
        client_id=config.mqttclientid,
        clean_session=True
    )
    if config.mqttusername and config.mqttpassword:
        client.username_pw_set(config.mqttusername, config.mqttpassword)
    client.on_connect = on_connect
    client.on_message = on_message
    try:
        client.connect(config.mqttbroker, port=config.mqttport, keepalive=60)
        client.loop_start()
    except Exception as e:
        logger.error(f"Error connecting to MQTT broker: {e}")
        return None
    return client

def mqtt_publish(client, topic, payload):
    publish_mqtt_message(client, topic, payload)

def mqtt_reconnect():
    global running
    while running:
        try:
            mqtt_connect()
            if mqtt_connect().is_connected():
                logger.info("Reconnected to MQTT broker")
                break
            else:
                logger.warning("Failed to reconnect to MQTT broker, retrying...")
                time.sleep(5)
        except Exception as e:
            logger.error(f"Error reconnecting to MQTT broker: {e}")
            time.sleep(5)

def mqtt_disconnect():
    global running
    if running:
        try:
            mqtt_connect().loop_stop()
            mqtt_connect().disconnect()
            logger.info("Disconnected from MQTT broker")
        except Exception as e:
            logger.error(f"Error disconnecting from MQTT broker: {e}")

def mqtt_init():
    client = mqtt_connect()
    if client:
        client.publish(f"homie/{config.homieclientid}/$state", "init", retain=True, qos=0)
        client.publish(f"homie/{config.homieclientid}/{config.homienodes}/$name", config.homieclientname, retain=True, qos=0)
        client.publish(f"homie/{config.homieclientid}/{config.homienodes}/$nodes", config.homienodes, retain=True, qos=0)
        client.publish(f"homie/{config.homieclientid}/$properties", "$name, $nodes, $temperature, $humidity, $lastseen", retain=True, qos=0)
        client.publish(f"homie/{config.homieclientid}/{config.homienodes}/$name", config.homieclientname, retain=True, qos=0)
        client.publish(f"homie/{config.homieclientid}/{config.homienodes}/$nodes", config.homienodes, retain=True, qos=0)
        client.publish(f"homie/{config.homieclientid}/{config.homienodes}/$properties", "$name, $nodes, $temperature, $humidity, $lastseen", retain=True, qos=0)
        client.publish(f"homie/{config.homieclientid}/{config.homienodes}/$temperature/$unit", DEGREE_CELSIUS, retain=True, qos=0)
        client.publish(f"homie/{config.homieclientid}/{config.homienodes}/$temperature/$datatype", "float", retain=True, qos=0)
        client.publish(f"homie/{config.homieclientid}/{config.homienodes}/$temperature/$settable", "false", retain=True, qos=0)
        client.publish(f"homie/{config.homieclientid}/{config.homienodes}/$humidity/$unit", "%", retain=True, qos=0)
        client.publish(f"homie/{config.homieclientid}/{config.homienodes}/$humidity/$datatype", "float", retain=True, qos=0)
        client.publish(f"homie/{config.homieclientid}/{config.homienodes}/$humidity/$settable", "false", retain=True, qos=0)
        client.publish(f"homie/{config.homieclientid}/{config.homienodes}/$lastseen", time.time(), retain=True, qos=0)
        client.publish(f"homie/{config.homieclientid}/$state", "ready", retain=True, qos=0)
        mqtt_reconnect()
    else:
        logger.error("Failed to initialize MQTT connection")

def read_dht22(dht_device):
    for attempt in range(3):
        try:
            temperature = dht_device.temperature
            humidity = dht_device.humidity
            if temperature is not None and humidity is not None:
                return temperature, humidity
            else:
                logger.warning(f"DHT22 returned None values (attempt {attempt + 1}/3)")
        except RuntimeError as e:
            logger.warning(f"DHT22 read error (attempt {attempt + 1}/3): {e}")
        except Exception as e:
            logger.error(f"Unexpected DHT22 error (attempt {attempt + 1}/3): {e}")
        time.sleep(2)
    logger.error("DHT22 read failed after 3 attempts")
    return None, None

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    dht_device = init_dht22()
    if dht_device is None:
        logger.error("DHT22 initialization failed, exiting")
        sys.exit(1)

    mqtt_init()

    try:
        while running:
            temperature, humidity = read_dht22(dht_device)
            if temperature is not None and humidity is not None:
                mqtt_publish(config.mqttclient, f"{config.homienodes}/temperature", f"{temperature:.1f}")
                mqtt_publish(config.mqttclient, f"{config.homienodes}/humidity", f"{humidity:.1f}")
                logger.info(f"Temperature: {temperature:.1f} {DEGREE_CELSIUS}, Humidity: {humidity:.1f} %")
            else:
                logger.warning("Skipping publish due to invalid sensor readings")
            time.sleep(config.publishtime)
    except Exception as e:
        logger.error(f"Unexpected error in main loop: {e}")
    finally:
        mqtt_disconnect()
        if dht_device:
            try:
                dht_device.exit()
            except Exception:
                pass
        logger.info("Program terminated")

if __name__ == "__main__":
    main()

