import signal
import sys
import time
from datetime import datetime

try:
    import RPi.GPIO as GPIO
except (ImportError, RuntimeError):
    print("Error: RPi.GPIO is not available. Install with: sudo apt install python3-rpi.gpio", file=sys.stderr)
    sys.exit(1)

DHT_PIN = 17
FAN_PIN = 18
LOG_FILE = "urban_data_log.txt"
TEMP_THRESHOLD = 30.0
HUMIDITY_THRESHOLD = 70.0
READ_COUNT = 5
READ_INTERVAL = 2.0

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def log_data(temperature, humidity):
    timestamp = datetime.now().isoformat(timespec="seconds")
    log_entry = f"{timestamp} - Temperature: {temperature:.1f}°C, Humidity: {humidity:.1f}%\n"
    try:
        with open(LOG_FILE, "a", encoding="utf-8") as f:
            f.write(log_entry)
    except OSError as e:
        print(f"Error writing to log file: {e}", file=sys.stderr)


def control_fan(temperature, humidity):
    if temperature > TEMP_THRESHOLD or humidity > HUMIDITY_THRESHOLD:
        GPIO.output(FAN_PIN, GPIO.HIGH)
        print("Fan ON: Temperature or humidity too high.")
    else:
        GPIO.output(FAN_PIN, GPIO.LOW)
        print("Fan OFF: Temperature and humidity normal.")


def read_dht11():
    """Return (temperature, humidity) or (None, None) on failure."""
    try:
        import adafruit_dht
        sensor = adafruit_dht.DHT11(DHT_PIN, use_pulseio=False)
        temperature = sensor.temperature
        humidity = sensor.humidity
        sensor.exit()
        if temperature is None or humidity is None:
            return None, None
        return temperature, humidity
    except Exception as e:
        print(f"Error reading DHT11 sensor: {e}", file=sys.stderr)
        return None, None


def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(FAN_PIN, GPIO.OUT, initial=GPIO.LOW)
    except Exception as e:
        print(f"Error initializing GPIO: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        for i in range(READ_COUNT):
            if not _running:
                break

            temperature, humidity = read_dht11()
            if temperature is not None and humidity is not None:
                print(f"Reading {i + 1}/{READ_COUNT}: "
