import time
import board
import busio
import adafruit_ahtx0

# --- Configuration -----------------------------------------------------------
READ_INTERVAL_S = 5
MAX_RETRIES = 3
RETRY_DELAY_S = 5
TEMP_MIN_C = -40.0
TEMP_MAX_C = 85.0
HUM_MIN_PCT = 0.0
HUM_MAX_PCT = 100.0

# --- Globals for cleanup -----------------------------------------------------
i2c = None
sensor = None
running = True


def cleanup():
    """Release I2C resources exactly once."""
    global i2c, sensor
    if sensor is not None:
        try:
            sensor.deinit()
        except Exception:
            pass
        sensor = None
    if i2c is not None:
        try:
            i2c.deinit()
        except Exception:
            pass
        i2c = None


def init_i2c():
    """Initialize the I2C bus; return the bus object or None on failure."""
    try:
        return busio.I2C(board.SCL, board.SDA)
    except Exception as exc:
        print(f"Error initializing I2C bus: {exc}")
        return None


def init_sensor():
    """Initialize the AHT20 sensor; return the sensor object or None."""
    try:
        return adafruit_ahtx0.AHTx0(i2c)
    except Exception as exc:
        print(f"Error initializing AHT20 sensor: {exc}")
        return None


def read_sensor_data():
    """Read temperature and humidity; return (temp, hum) or (None, None) on error."""
    try:
        return sensor.temperature, sensor.humidity
    except Exception as exc:
        print(f"Error reading sensor data: {exc}")
        return None, None


def validate_data(temp, hum):
    """Return True if readings are within sensor limits."""
    if temp is None or hum is None:
        return False
    if not (TEMP_MIN_C <= temp <= TEMP_MAX_C):
        print(f"Warning: temperature out of range: {temp:.1f} C")
        return False
    if not (HUM_MIN_PCT <= hum <= HUM_MAX_PCT):
        print(f"Warning: humidity out of range: {hum:.1f} %")
        return False
    return True


def main():
    global i2c, sensor, running

    # --- I2C bus -------------------------------------------------------------
    i2c = init_i2c()
    if i2c is None:
        print("Failed to initialize I2C bus. Exiting.")
        return

    # --- Sensor initialization with retry -----------------------------------
    sensor = None
    for attempt in range(1, MAX_RETRIES + 1):
        sensor = init_sensor()
        if sensor is not None:
            break
        if attempt < MAX_RETRIES:
            print(f"Retrying sensor initialization (attempt {attempt}/{MAX_RETRIES})...")
            time.sleep(RETRY_DELAY_S)

    if sensor is None:
        print("Failed to initialize AHT20 sensor after retries. Exiting.")
        cleanup()
        return

    # --- Main loop -----------------------------------------------------------
    while running:
        timestamp = time.strftime("%Y-%m-%d %H:%M:%S")
        print(f"[{timestamp}]")

        temp, hum = read_sensor_data()
        if temp is not None and hum is not None:
            if validate_data(temp, hum):
                print(f"Temperature: {temp:.1f} C Humidity: {hum:.1f} %")
            else:
                print("Sensor data is invalid; skipping.")
        else:
            print("Failed to read sensor data. Retrying...")

        # Sleep in small increments so KeyboardInterrupt is responsive
        slept = 0
        while slept < READ_INTERVAL_S and running:
            time.sleep(0.5)
            slept += 0.5

    print("\nShutting down...")
    cleanup()


if __name__ == "__main__":
    try:
        main()
    except KeyboardInterrupt:
        print("\nProgram stopped by user.")
    except Exception as exc:
        print(f"Unexpected error: {exc}")
    finally:
        cleanup()
        print("Program exited.")

