import time
import datetime
import logging
import fcntl
import os
import random
import signal
import sys
import threading
import queue
import argparse
import traceback

try:
    import RPi.GPIO as GPIO
except RuntimeError:
    GPIO = None

try:
    import adafruit_dht
except ImportError:
    adafruit_dht = None

# Constants
DHT_PIN_1 = 17
DHT_PIN_2 = 27
HIGH_HUMIDITY_THRESHOLD = 75
LOW_HUMIDITY_THRESHOLD = 45
DEBOUNCE_TIME = 30
SENSOR_READ_INTERVAL = 60
MAX_RETRIES = 3
RETRY_DELAY = 2

# Logging setup
logging.basicConfig(
    filename='error.log',
    level=logging.ERROR,
    format='%(asctime)s - %(levelname)s - %(message)s'
)

# Global state
running = True
data_queue = queue.Queue()
high_humidity_alert_1 = False
low_humidity_alert_1 = False
high_humidity_alert_2 = False
low_humidity_alert_2 = False
last_high_humidity_alert_time = 0
last_low_humidity_alert_time = 0

# Locking for CSV file
lock_file = 'retail_data.lock'

def signal_handler(signum, frame):
    global running
    running = False

def log_error(message):
    logging.error(message)

def log_alert(sensor_id, alert_type, message):
    timestamp = datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    log_message = f"{timestamp} - Sensor {sensor_id} - {alert_type} - {message}"
    print(log_message)
    try:
        with open('retail_alerts.log', 'a') as f:
            f.write(log_message + '\n')
    except Exception as e:
        log_error(f"Error writing to alerts log: {e}")

def log_cloud_data(sensor_id, data):
    timestamp = datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    log_message = f"{timestamp} - Sensor {sensor_id} - {data}"
    print(log_message)
    try:
        with open('cloud_log.log', 'a') as f:
            f.write(log_message + '\n')
    except Exception as e:
        log_error(f"Error writing to cloud log: {e}")

def read_dht22(sensor, sensor_id):
    retries = 0
    while retries < MAX_RETRIES:
        try:
            temperature = sensor.temperature
            humidity = sensor.humidity
            if temperature is None or humidity is None:
                raise ValueError("Sensor returned None")
            if not (0 <= humidity <= 100):
                raise ValueError(f"Humidity out of range: {humidity}")
            if not (0 <= temperature <= 35):
                raise ValueError(f"Temperature out of range: {temperature}")
            return temperature, humidity
        except Exception as e:
            retries += 1
            log_error(f"Error reading DHT22 sensor {sensor_id}: {e}")
            if retries < MAX_RETRIES:
                time.sleep(RETRY_DELAY)
    return None, None

def validate_data(sensor_id, temperature, humidity):
    if not (0 <= humidity <= 100):
        return False, "Humidity out of range"
    if not (0 <= temperature <= 35):
        return False, "Temperature out of range"
    return True, None

def check_alerts(sensor_id, temperature, humidity, last_time):
    global high_humidity_alert_1, low_humidity_alert_1, high_humidity_alert_2, low_humidity_alert_2
    now = time.time()
    if sensor_id == 1:
        if humidity > HIGH_HUMIDITY_THRESHOLD and (last_high_humidity_alert_time == 0 or now - last_high_humidity_alert_time > DEBOUNCE_TIME):
            log_alert(sensor_id, "High Humidity", f"High humidity detected: {humidity}%")
            high_humidity_alert_1 = True
            last_high_humidity_alert_time = now
        elif humidity < LOW_HUMIDITY_THRESHOLD and (last_low_humidity_alert_time == 0 or now - last_low_humidity_alert_time > DEBOUNCE_TIME):
            log_alert(sensor_id, "Low Humidity", f"Low humidity detected: {humidity}%")
