import time
import signal
import sys
import logging

try:
    import RPi.GPIO as GPIO
except RuntimeError:
    logging.error("RPi.GPIO import failed. This script must run on a Raspberry Pi.")
    sys.exit(1)

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(message)s",
)
logger = logging.getLogger(__name__)

FAN_PIN = 14
PWM_FREQ = 100
CHECK_INTERVAL = 5
TEMP_FILE = "/sys/class/thermal/thermal_zone0/temp"
TEMP_FILE_PATH = "/proc/cpu/temp"

_running = True


def _signal_handler(signum, frame):
    global _running
    logger.info("Signal %s received, shutting down...", signum)
    _running = False


class FanController:
    def __init__(self, pin, freq, temp_file):
        self.pin = pin
        self.freq = freq
        self.temp_file = temp_file
        self.pwm = None
        self._setup_gpio()

    def _setup_gpio(self):
        GPIO.setmode(GPIO.BCM)
        GPIO.setwarnings(False)
        GPIO.setup(self.pin, GPIO.OUT, initial=GPIO.LOW)
        self.pwm = GPIO.PWM(self.pin, self.freq)
        self.pwm.start(0)
        logger.info("PWM controller initialized on GPIO%d at %d Hz.", self.pin, self.freq)

    def _read_temp(self):
        for path in (self.temp_file, TEMP_FILE_PATH):
            try:
                with open(path, "r") as f:
                    return float(f.read().strip()) / 1000.0
            except (OSError, ValueError):
                continue
        return None

    def _compute_speed(self, temp):
        if temp <= 25.0:
            return 0.0
        elif temp <= 40.0:
            return 50.0
        elif temp <= 60.0:
            return 75.0
        elif temp <= 80.0:
            return 100.0
        else:
            return 100.0

    def set_speed(self, speed):
        if self.pwm is None:
            return
        try:
            self.pwm.ChangeDutyCycle(speed)
        except Exception as exc:
            logger.error("Failed to set duty cycle: %s", exc)

    def cleanup(self):
        if self.pwm is not None:
            try:
                self.pwm.stop()
            except Exception:
                pass
        try:
            GPIO.cleanup(self.pin)
        except Exception:
            pass
        logger.info("GPIO cleanup complete.")


def main():
    signal.signal(signal.SIGTERM, _signal_handler)
    signal.signal(signal.SIGINT, _signal_handler)

    controller = FanController(FAN_PIN, PWM_FREQ, TEMP_FILE)

    try:
        while _running:
            temp = controller._read_temp()
            if temp is None:
                logger.warning("Temperature read failed; keeping previous speed.")
            else:
                speed = controller._compute_speed(temp)
                controller.set_speed(speed)
                logger.info("CPU temp: %.1f °C  ->  fan speed: %.0f %%", temp, speed)
            for _ in range(CHECK_INTERVAL):
                if not _running:
                    break
                time.sleep(1)
    except Exception as exc:
        logger.exception("Unexpected error: %s", exc)
    finally:
        controller.cleanup()


if __name__ == "__main__":
    main()

