import time
import signal
import sys
import paho.mqtt.client as mqtt
from wificonnection import connect_wifi
from bme280 import BME280

import config

# Global handles so the signal handler can clean up.
_mqtt_client = None
_dht_sensor = None
_running = True


def _cleanup():
    """Disconnect the MQTT client and release the DHT22 sensor."""
    global _mqtt_client, _dht_sensor
    if _mqtt_client is not None:
        try:
            _mqtt_client.loop_stop()
            _mqtt_client.disconnect()
        except Exception:
            pass
        _mqtt_client = None
    if _dht_sensor is not None:
        try:
            _dht_sensor.data = None
        except Exception:
            pass
        _dht_sensor = None


def _signal_handler(signum, frame):
    """Handle SIGINT / SIGTERM for a clean shutdown."""
    global _running
    _running = False


def main():
    global _mqtt_client, _dht_sensor

    # --- MQTT connection -------------------------------------------------
    try:
        _mqtt_client = mqtt.Client(
            mqtt.CallbackAPIVersion.VERSION2,
            client_id=config.mqttclientid,
        )
        _mqtt_client.username_pw_set(config.mqttusername, config.mqttpassword)
        _mqtt_client.on_connect = _mqtt_on_connect
        _mqtt_client.on_disconnect = _mqtt_on_disconnect

        _mqtt_client.connect(config.mqttbroker, config.mqttport, keepalive=30)
        _mqtt_client.loop_start()
    except Exception as e:
        print(f"MQTT connection error: {e}", file=sys.stderr)
        sys.exit(1)

    # --- DHT22 sensor -----------------------------------------------------
    try:
        _dht_sensor = BME280(
            data_pin=getattr(config, 'dhtgpiopin', 27),
            use_pulseio=False,
        )
    except Exception as e:
        print(f"DHT22 init error: {e}", file=sys.stderr)
        _cleanup()
        sys.exit(1)

    # --- Signal handlers --------------------------------------------------
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    # --- Main loop ---------------------------------------------------------
    try:
        while _running:
            try:
                temperature = _dht_sensor.temperature
                humidity = _dht_sensor.humidity

                if temperature is not None and humidity is not None:
                    _mqtt_client.publish(
                        f"homie/{config.homieclientid}/{config.homienodes}/temperature",
                        f"{temperature:.1f}",
                        qos=1,
                    )
                    _mqtt_client.publish(
                        f"homie/{config.homieclientid}/{config.homienodes}/humidity",
                        f"{humidity:.1f}",
                        qos=1,
                    )
                    print(
                        f"Published: T={temperature:.1f}°C  H={humidity:.1f}%"
                    )
                else:
                    print("DHT22 returned None — skipping publish.", file=sys.stderr)

            except RuntimeError as e:
                # DHT22 checksum / timing glitches are common; retry after gap.
                print(f"DHT22 read error: {e}", file=sys.stderr)
            except Exception as e:
                print(f"Unexpected error: {e}", file=sys.stderr)

            # Wait at least 2 s between reads.
            if _running:
                time.sleep(2)

    finally:
        _cleanup()


def _mqtt_on_connect(client, userdata, flags, reason_code, properties):
    if reason_code == 0:
        print("Connected to MQTT broker.")
    else:
        print(f"MQTT connect failed with reason code: {reason_code}", file=sys.stderr)


def _mqtt_on_disconnect(client, userdata, flags, reason_code, properties):
    print(f"Disconnected from MQTT broker (reason code: {reason_code}).")


if __name__ == "__main__":
    main()

