import signal
import sys
import time
import numpy as np
import matplotlib.pyplot as plt

try:
    from picamera2 import Picamera2
except ImportError:
    Picamera2 = None

try:
    from thermalci import ThermalCI
except ImportError:
    ThermalCI = None

SERIAL_PORT = "/dev/ttyUSB0"
BAUD_RATE = 9600
FRAME_SIZE = 24 * 32  # 768 integers
UPDATE_INTERVAL = 0.1

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def _cleanup(thermal_api=None, fig=None):
    if thermal_api is not None:
        try:
            thermal_api.close()
        except Exception:
            pass
    if fig is not None:
        try:
            plt.close(fig)
        except Exception:
            pass

def main():
    global _running

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    thermal_api = None
    fig = None

    try:
        thermal_api = ThermalCI(
            serial_port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            timeout=1.0,
        )
        if Picamera2 is not None:
            picam2 = Picamera2()
            config = picam2.create_preview_configuration(
                main={"size": (768, 1024), "format": "RGB888"}
            )
            picam2.configure(config)
            picam2.start()
            try:
                while _running:
                    frame = picam2.capture_array()
                    if frame is None:
                        time.sleep(UPDATE_INTERVAL)
                        continue
                    thermal_api.set_frame(frame)
                    plt.imshow(frame, cmap="inferno", interpolation="nearest")
                    plt.show()
                    time.sleep(UPDATE_INTERVAL)
            finally:
                picam2.stop()
                picam2.close()
        else:
            while _running:
                try:
                    frame = thermal_api.get_frame()
                    if frame is None:
                        time.sleep(UPDATE_INTERVAL)
                        continue
                    thermal_api.set_frame(frame)
                    plt.imshow(frame, cmap="inferno", interpolation="nearest")
                    plt.show()
                    time.sleep(UPDATE_INTERVAL)
                except Exception as e:
                    print(f"Error reading frame: {e}", file=sys.stderr)
                    time.sleep(UPDATE_INTERVAL)
        _cleanup(thermal_api, fig)
    except Exception as e:
        print(f"Error initializing thermal camera: {e}", file=sys.stderr)
        _cleanup(thermal_api, fig)
        sys.exit(1)

    plt.show()

if __name__ == "__main__":
    main()

