import time
import random
import logging
import os
import signal
import sys
import datetime
import traceback

try:
    import RPi.GPIO as GPIO
except (ImportError, RuntimeError):
    GPIO = None

# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------
DHT_PIN = 4          # BCM GPIO4 (placeholder digital input)
READ_INTERVAL = 5    # seconds between readings
MAX_RETRIES = 3
RETRY_DELAY = 1      # seconds between retry attempts

TEMP_MIN, TEMP_MAX = 10, 55
HUM_MIN, HUM_MAX = 20, 100

LOG_FILE = "/var/log/wearable"
BACKUP_COUNT = 7
HOME_DIR = os.path.expanduser("~")
HOME_LOG = os.path.join(HOME_DIR, ".local", "log", "wearable")

# ---------------------------------------------------------------------------
# Logging setup
# ---------------------------------------------------------------------------
logger = logging.getLogger("wearable")
logger.setLevel(logging.INFO)

_file_handler = logging.FileHandler(LOG_FILE)
_file_handler.setFormatter(
    logging.Formatter("%(asctime)s - %(levelname)s - %(message)s")
)
logger.addHandler(_file_handler)

_console_handler = logging.StreamHandler()
_console_handler.setFormatter(
    logging.Formatter("%(asctime)s - %(levelname)s - %(message)s")
)
logger.addHandler(_console_handler)

# ---------------------------------------------------------------------------
# GPIO setup
# ---------------------------------------------------------------------------
if GPIO is not None:
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(DHT_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)
    except Exception as exc:
        logger.error("GPIO setup failed: %s", exc)
        GPIO = None

_original_handlers = list(logger.handlers)

# ---------------------------------------------------------------------------
# Signal handling for clean shutdown
# ---------------------------------------------------------------------------
_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

signal.signal(signal.SIGINT, _signal_handler)
signal.signal(signal.SIGTERM, _signal_handler)

# ---------------------------------------------------------------------------
# Helpers
# ---------------------------------------------------------------------------
def _rotate_log():
    """Rotate the log file by moving the oldest backup to the current file."""
    try:
        if not os.path.exists(LOG_FILE):
            return
        try:
            os.rename(LOG_FILE, LOG_FILE + ".1")
        except OSError as exc:
            logger.error("Failed to rename %s -> %s: %s", LOG_FILE, LOG_FILE + ".1", exc)
            return

        for i in range(BACKUP_COUNT, 0, -1):
            if i > 1:
                try:
                    os.rename(LOG_FILE + i, LOG_FILE + i + 1)
                except OSError as exc:
                    logger.error("Failed to rename %s -> %s: %s", LOG_FILE + i, LOG_FILE + i + 1, exc)
            else:
                break

        logger.info("Log rotated: %s", LOG_FILE)
    except OSError as exc:
        logger.error("Failed to rotate log: %s", exc)

def _write_log(message):
    """Append a message to the log file, rotating if necessary."""
    try:
        with open(LOG_FILE, "a") as f:
            f.write(message + "\n")
    except OSError as exc:
        logger.error("Failed to write to %s: %s", LOG_FILE, exc)

def _validate_data(temperature, humidity):
    """Validate temperature and humidity ranges and return a formatted string."""
    if not isinstance(temperature, (int, float)):
        return "Invalid temperature data type"
    if not isinstance(humidity, (int, float)):
        return "Invalid humidity data type"
    if not (TEMP_MIN <= temperature <= TEMP_MAX):
        return f"Temperature out of range: {temperature}"
    if not (HUM_MIN <= humidity <= HUM_MAX):
        return f"Humidity out of range: {humidity}"
    return f"Temperature: {temperature:.1f}°C, Humidity: {humidity:.1f}%"

def _simulate_reading():
    """Simulate a DHT22 reading with retries."""
    for attempt in range(1, MAX_RETRIES + 1):
        if not _running:
            return None, None
        try:
            temperature = random.uniform(TEMP_MIN, TEMP_MAX)
            humidity = random.uniform(HUM_MIN, HUM_MAX)
            return temperature, humidity
        except (TypeError, ValueError, OSError) as exc:
            logger.error("Attempt %d/%d: Failed to simulate reading: %s", attempt, MAX_RETRIES, exc)
            if attempt < MAX_RETRIES:
                time.sleep(RETRY_DELAY)
    logger.error("Attempt %d/%d: Failed to simulate reading after retries", attempt, MAX_RETRIES)
    return None, None

# ---------------------------------------------------------------------------
# Main loop
# ---------------------------------------------------------------------------
def main():
    global _original_handlers

    _rotate_log()

    _original_handlers.clear()
    for handler in _original_handlers:
        logger.removeHandler(handler)

    try:
        while _running:
            temperature, humidity = _simulate_reading()

            if temperature is not None and humidity is not None:
                message = _validate_data(temperature, humidity)
                logger.info(message)
            else:
                logger.error("Failed to obtain valid sensor data after retries")

            _write_log(f"Temperature: {temperature:.1f}°C, Humidity: {humidity:.1f}%")

            for _ in range(READ_INTERVAL):
                if not _running:
                    break
                time.sleep(1)

    except KeyboardInterrupt:
        logger.info("Program terminated by user (KeyboardInterrupt)")
    except (OSError, TypeError, ValueError) as exc:
        logger.error("Fatal error: %s", exc)
        traceback.print_exc()
    except Exception as exc:
        logger.error("Unexpected error: %s", exc)
        traceback.print_exc()
    finally:
        for handler in _original_handlers:
            logger.removeHandler(handler)
        if GPIO is not None:
            try:
                GPIO.cleanup()
            except Exception:
                pass
        logger.info("Program exiting")

if __name__ == "__main__":
    main()

