import time
import random
import logging
import sys

# Configure logging
logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)

# Constants
LED_PIN = 17
PPM_THRESHOLD = 500
SAMPLE_INTERVAL = 5  # seconds

# Global flag for graceful shutdown
running = True


def signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for graceful shutdown."""
    global running
    logging.info(f"Received signal {signum}, shutting down gracefully...")
    running = False


def get_temperature():
    """Simulates reading temperature data from a sensor."""
    return round(random.uniform(20.00, 30.00), 2)


def get_humidity():
    """Simulates reading humidity data from a sensor."""
    return round(random.uniform(40.00, 60.00), 2)


def get_ppm():
    """Simulates reading PPM data from a sensor."""
    return random.randint(0, 800)


def control_led(state):
    """Controls the LED based on the state."""
    try:
        if state:
            GPIO.output(LED_PIN, GPIO.HIGH)
            logging.info("LED turned ON")
        else:
            GPIO.output(LED_PIN, GPIO.LOW)
            logging.info("LED turned OFF")
    except Exception as e:
        logging.error(f"Error controlling LED: {e}")


def main():
    """Main function to simulate air quality monitoring."""
    global running

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    # Initialize GPIO using RPi.GPIO
    try:
        import RPi.GPIO as GPIO
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(LED_PIN, GPIO.OUT, initial=GPIO.LOW)
    except Exception as e:
        logging.error(f"Failed to initialize GPIO: {e}")
        sys.exit(1)

    try:
        while running:
            try:
                temperature = get_temperature()
                humidity = get_humidity()
                ppm = get_ppm()

                logging.info(f"Temperature: {temperature}°C, Humidity: {humidity}%, PPM: {ppm}")

                if ppm > PPM_THRESHOLD:
                    logging.warning(
                        f"ALERT! PPM level exceeded threshold. "
                        f"Temperature: {temperature}°C, Humidity: {humidity}%, PPM: {ppm}"
                    )

                control_led(True)  # Turn on LED
                time.sleep(SAMPLE_INTERVAL)
                control_led(False)  # Turn off LED
                time.sleep(SAMPLE_INTERVAL)

            except Exception as e:
                logging.error(f"An error occurred during monitoring: {e}")
                time.sleep(SAMPLE_INTERVAL)

    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        GPIO.cleanup()
        logging.info("GPIO cleanup completed. Exiting.")


if __name__ == "__main__":
    main()

