import signal
import sys
import time

try:
    import smbus
except ImportError:
    print("Error: smbus module not found. Install with: pip install smbus2", file=sys.stderr)
    sys.exit(1)

I2C_BUS = 1
MCP23017_ADDR = 0x22

# MCP23017 register addresses
REG_IODIRA = 0x00
REG_IODIRB = 0x01
REG_GPPUA = 0x0C
REG_GPPUB = 0x0D
REG_GPIOA = 0x12
REG_GPIOB = 0x13
REG_OLATA = 0x14
REG_OLATB = 0x15

# Pin definitions
LED_PIN = 0      # GPA0
SWITCH_PIN = 7   # GPB7

DEBOUNCE_MS = 20

_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


def _write_reg(bus, reg, value):
    bus.write_byte_data(MCP23017_ADDR, reg, value)


def _read_reg(bus, reg):
    return bus.read_byte_data(MCP23017_ADDR, reg)


def _read_block(bus, reg, length):
    return bus.read_i2c_block_data(MCP23017_ADDR, reg, length)


def _write_block(bus, reg, data):
    bus.write_i2c_block_data(MCP23017_ADDR, reg, data)


def initialize_mcp23017(bus):
    """Configure the MCP23017: GPA0 output, GPB7 input with pull-up, all other pins input."""
    try:
        _write_reg(bus, REG_IODIRA, 0xFF & ~(1 << LED_PIN))
        _write_reg(bus, REG_IODIRB, 0xFF)
        _write_reg(bus, REG_GPPUA, 0x01 << SWITCH_PIN)
        _write_reg(bus, REG_GPPUB, 0x01 << SWITCH_PIN)
        _write_reg(bus, REG_OLATA, 0x00)
        _write_reg(bus, REG_OLATB, 0x00)
    except OSError as e:
        raise RuntimeError(f"MCP23017 initialization failed: {e}")


def read_switch(bus):
    """Read GPB7 with pull-up; return 0 if pin is high, 1 if low."""
    try:
        port_b = _read_reg(bus, REG_GPIOB)
        if port_b & (1 << SWITCH_PIN):
            return 1
        return 0
    except OSError as e:
        raise RuntimeError(f"Failed to read switch on GPB7: {e}")


def toggle_led(bus):
    """Toggle the LED on GPA0, debounce, and print state."""
    try:
        current = _read_reg(bus, REG_OLATA)
        if current & (1 << LED_PIN):
            _write_reg(bus, REG_OLATA, current & ~(1 << LED_PIN))
            print("LED OFF")
        else:
            _write_reg(bus, REG_OLATA, current | (1 << LED_PIN))
            print("LED ON")
    except OSError as e:
        raise RuntimeError(f"Failed to toggle LED: {e}")


def main():
    global _running

    signal.signal(signal.SIGINT, _signal_handler)

    try:
        bus = smbus.SMBus(I2C_BUS)
    except OSError as e:
        print(f"Error: cannot open I2C bus {I2C_BUS}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        initialize_mcp23017(bus)
        print("MCP23017 initialized. Press Ctrl+C to exit.")

        while _running:
            try:
                state = read_switch(bus)
                toggle_led(bus)
            except RuntimeError as e:
                print(f"Read/write error: {e}", file=sys.stderr)
            time.sleep(DEBOUNCE_MS / 1000.0)

    except RuntimeError as e:
        print(f"Fatal error: {e}", file=sys.stderr)
        sys.exit(1)
    finally:
        try:
            _write_reg(bus, REG_OLATA, 0x00)
        except OSError:
            pass
        try:
            bus.close()
        except OSError:
            pass
        print("Program terminated cleanly.")


if __name__ == "__main__":
    main()

