    print(help_text)


def _process_command(command, args, help_text, help_available):
    """Process a single command, handling help requests and sending data."""
    parts = command.split()
    if not parts:
        return
    cmd = parts[0].lower()

    if cmd == "help":
        if len(parts) < 2:
            _display_help(help_text)
        else:
            _display_help(help_text.format(help_available=help_available))

    elif cmd == "start":
        if len(parts) < 2:
            print("Usage: start ")
            return
        filename = parts[1]
        try:
            with open(filename, 'a') as f:
                _dog_lib.APIcall()
        except Exception as e:
            print(f"Error starting logging: {e}")
        except FileNotFoundError:
            print(f"Error: File '{filename}' not found.")

    elif cmd == "stop":
        _dog_lib.APIcall()

    elif cmd == "display":
        try:
            with open(args.filename, 'r') as f:
                print(f.read())
        except FileNotFoundError:
            print(f"Error: File '{args.filename}' not found.")
        except Exception as e:
            print(f"Error displaying file: {e}")

    elif cmd == "send":
        if len(parts) < 2:
            print("Usage: send <data>")
            return
        data = " ".join(parts[1:])
        try:
            _dog_lib.send(data)
        except Exception as e:
            print(f"Error sending data: {e}")

    elif cmd == "write":
        if len(parts) < 2:
            print("Usage: write <data>")
            return
        data = " ".join(parts[1:])
        try:
            with open(args.filename, 'a') as f:
                f.write(data + "\n")
        except Exception as e:
            print(f"Error writing to file: {e}")

    elif cmd == "exit":
        _cleanup_library()
        print("Exiting program.")
        sys.exit(0)

    else:
        print(f"Unknown command: {cmd}")


def _run_library_thread(args, help_text, help_available):
    """Run the DOG library API call in a separate thread."""
    try:
        _dog_lib.APIcall()
    except Exception as e:
        print(f"Error in API call: {e}")
    finally:
        _cleanup_library()


def _run_receive_thread(args, help_text, help_available):
    """Run the receive thread in a separate thread."""
    try:
        while not _shutdown_requested:
            try:
                data = _dog_lib.receive()
                if data:
                    with open(args.filename, 'a') as f:
                        f.write(data + "\n")
            except Exception as e:
                print(f"Error receiving data: {e}")
            time.sleep(0.1)
    except Exception as e:
        print(f"Error in receive thread: {e}")
    finally:
        _cleanup_library()


def run_dog():
    """Main function to run the DOG program with CLI."""
    global _shutdown_requested

    _install_signal_handlers()

    # Initialize GPIO
    try:
        import RPi.GPIO as GPIO
        GPIO.setmode(GPIO.BCM)
        GPIO.setwarnings(False)
    except Exception as e:
        print(f"Error initializing GPIO: {e}")
        print("Continuing without GPIO (simulation mode).")
        GPIO = None

    args = None
    help_text = """Usage: run_dog.py [options] <command> <arguments>
Commands:
  start   Start logging to 
  stop            Stop the library API call
  help [command]  Display help information
  display           Display the contents of the log file
  send <data>      Send data via the library
  write <data>     Write data directly to the log file
  exit             Exit the program
"""

    help_available = False
    try:
        import __main__ as _main_lib
        help_available = True
    except Exception:
        pass

    try:
        import threading
        import time
        import signal
        import sys
        import traceback

        # Create a file for logging
        try:
            with open('log.txt', 'a') as f:
                pass
        except Exception as e:
            print(f"Error creating log file: {e}")
            sys.exit(1)

        args = threading.local()
        args.filename = 'log.txt'
        args.help_text = help_text
        args.help_available = help_available
        args.help_available_flag = help_available

        # Start the receive thread
        receive_thread = threading.Thread(
            target=_run_receive_thread,
            args=(args, help_text, help_available),
            daemon=True
        )
        receive_thread.start()

        # Start the library API call thread
        library_thread = threading.Thread(
            target=_run_library_thread,
            args=(args, help_text, help_available),
            daemon=True
        )
        library_thread.start()

        # Main loop for CLI
        while True:
            try:
                command = input("Enter command: ").strip()
                args.args = command
                args.help_available = help_available
                _process_command(command, args, args.help_text, args.help_available)
            except EOFError:
                print("\nEOF received, exiting.")
                break
            except Exception as e:
                print(f"An unexpected error occurred: {e}")
                traceback.print_exc()

    except KeyboardInterrupt:
        print("\nProgram interrupted by user.")
    finally:
        _cleanup_library()
        if GPIO is not None:
            try:
                GPIO.cleanup()
            except Exception:
                pass


if __name__ == "__main__":
    run_dog()

