import time
import requests
import signal
import sys
import RPi.GPIO as GPIO

VOLTAGE_PIN = 17
ALERT_ENDPOINT = 'http://example.com/alert'
REQUEST_TIMEOUT = 5

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def send_alert(payload):
    try:
        response = requests.post(ALERT_ENDPOINT, json=payload, timeout=REQUEST_TIMEOUT)
        response.raise_for_status()
        print(f"Alert sent successfully. Status code: {response.status_code}")
    except requests.exceptions.Timeout:
        print("Error sending alert: Request timed out.")
    except requests.exceptions.ConnectionError as e:
        print(f"Error sending alert: Connection error - {e}")
    except requests.exceptions.HTTPError as e:
        print(f"Error sending alert: HTTP error - {e}")
    except requests.exceptions.RequestException as e:
        print(f"Error sending alert: {e}")

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(VOLTAGE_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)
    except Exception as e:
        print(f"Failed to initialize GPIO: {e}")
        sys.exit(1)

    try:
        while _running:
            try:
                voltage_status = GPIO.input(VOLTAGE_PIN)
            except Exception as e:
                print(f"Error reading GPIO pin: {e}")
                time.sleep(1)
                continue

            if voltage_status == GPIO.LOW:
                print("Power failure detected!")
                send_alert({"alert": "Power failure detected"})
            elif voltage_status == GPIO.HIGH:
                print("Power is present.")
            time.sleep(1)
    finally:
        GPIO.cleanup()
        print("GPIO cleanup completed.")

if __name__ == "__main__":
    main()

