import signal
import sys
import time

try:
    import smbus2
except ImportError:
    print("Error: smbus2 library not found. Install with: pip install smbus2")
    sys.exit(1)

# Constants
I2C_BUS_NUMBER = 1
BH1750_I2C_ADDRESS = 0x5C
BH1750_ONE_SHOT_MODE = 0x01
BH1750_POWER_ON_RESET = 0x00
BH1750_HIGH_RESOLUTION_MODE = 0x00
TRIGGER_DELAY_S = 0.120
MEASUREMENT_DELAY_S = 0.005
READ_INTERVAL_S = 3.0

# Global flag for graceful shutdown
_running = True


def _signal_handler(signum, frame):
    """Handle SIGINT and SIGTERM for graceful shutdown."""
    global _running
    _running = False


def _read_byte(bus, address, register, count):
    """Read `count` bytes from `register` on the I2C device at `address`."""
    return bus.read_i2c_block_data(address, register, count)


def _write_byte(bus, address, register, value):
    """Write a single byte `value` to `register` on the I2C device at `address`."""
    bus.write_byte_data(address, register, value)


def _init_sensor(bus):
    """Initialize the BH1750 sensor in power-on reset mode."""
    try:
        bus.write_byte(BH1750_I2C_ADDRESS, BH1750_POWER_ON_RESET)
        time.sleep(0.010)  # Wait for power-on reset to complete
    except OSError as e:
        raise RuntimeError(f"Failed to initialize BH1750 sensor: {e}")


def _trigger_measurement(bus):
    """Trigger a one-shot high-resolution illuminance measurement."""
    try:
        _write_byte(bus, BH1750_I2C_ADDRESS, BH1750_ONE_SHOT_MODE, 0x01)
        time.sleep(TRIGGER_DELAY_S)
    except OSError as e:
        raise RuntimeError(f"Failed to trigger BH1750 measurement: {e}")


def _read_illuminance(bus):
    """Read the illuminance value from the BH1750 sensor."""
    try:
        data = _read_byte(bus, BH1750_I2C_ADDRESS, 2, 2)
        raw = (data[0] << 8) | data[1]
        illuminance = raw / 1.2
        return round(illuminance, 2)
    except OSError as e:
        raise RuntimeError(f"Failed to read BH1750 illuminance: {e}")


def main():
    """Main function to read and display illuminance from the BH1750 sensor."""
    global _running

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    bus = None
    try:
        bus = smbus2.SMBus(I2C_BUS_NUMBER)
        _init_sensor(bus)
        print("BH1750 initialized. Reading illuminance every 3 seconds (Ctrl+C to stop)...")

        while _running:
            try:
                _trigger_measurement(bus)
                illuminance = _read_illuminance(bus)
                print(f"Illuminance: {illuminance} lux")
            except RuntimeError as e:
                print(f"Error: {e}", file=sys.stderr)

            # Sleep in small increments to allow prompt signal handling
            elapsed = 0.0
            while _running and elapsed < READ_INTERVAL_S:
                time.sleep(0.1)
                elapsed += 0.1

    except RuntimeError as e:
        print(f"Fatal error: {e}", file=sys.stderr)
        sys.exit(1)
    except OSError as e:
        print(f"Fatal error: I2C bus error: {e}", file=sys.stderr)
        sys.exit(1)
    finally:
        if bus is not None:
            try:
                bus.close()
            except OSError:
                pass
        print("\nProgram terminated. I2C bus closed.")


if __name__ == "__main__":
    main()

