import time
import signal
import atexit

try:
    from gpiozero import Button, LED
    from gpiozero.exc import GPIOZeroError
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero")
    raise

BUTTON_PIN = 4
LED_PIN = 17
POLL_DELAY = 0.1

button = None
led = None

def cleanup():
    """Release GPIO resources on exit."""
    global button, led
    if led is not None:
        try:
            led.close()
        except Exception:
            pass
    if button is not None:
        try:
            button.close()
        except Exception:
            pass

atexit.register(cleanup)

def signal_handler(signum, frame):
    """Handle SIGTERM/SIGINT for clean shutdown."""
    print("\nTermination signal received. Exiting...")
    cleanup()
    raise SystemExit(0)

signal.signal(signal.SIGTERM, signal_handler)

try:
    button = Button(BUTTON_PIN, pull_up=False)
    led = LED(LED_PIN)

    print("Monitoring button on GPIO4. Press Ctrl+C to exit.")

    while True:
        if button.is_active:
            led.on()
        else:
            led.off()
        time.sleep(POLL_DELAY)

except KeyboardInterrupt:
    print("\nProgram terminated by user.")
except GPIOZeroError as e:
    print(f"GPIO error: {e}")
except Exception as e:
    print(f"Unexpected error: {e}")
finally:
    cleanup()

