import logging
from gpiozero import OutputDevice, InputDevice
from gpiozero.exc import GPIOZeroError, DeviceClosed

logging.basicConfig(level=logging.INFO, format="%(asctime)s [%(levelname)s] %(message)s")
logger = logging.getLogger(__name__)


class OutputPin:
    """Generic output pin with validation and shutdown support."""

    ALLOWED_VALUES = (0, 1)
    _LOCK = threading.Lock()

    def __init__(self, number, name, initial_value=None):
        if not isinstance(number, int) or not 0 <= number <= 31:
            raise ValueError(f"Invalid GPIO number {number!r}; must be an integer in 0-31.")
        if initial_value is not None and initial_value not in self.ALLOWED_VALUES:
            raise ValueError(f"Invalid initial value {initial_value!r}; must be one of {self.ALLOWED_VALUES}.")
        self.number = number
        self.name = name
        self._value = initial_value
        self._device = None
        try:
            self._device = OutputDevice(number, initial_value=self._value)
            logger.info("OutputPin %s (GPIO %d) initialized on GPIO %d (value=%s).", name, number, self.number, self._value)
        except GPIOZeroError as exc:
            logger.error("Failed to initialize OutputPin %s on GPIO %d: %s", name, self.number, exc)
            raise

    def shutdown(self):
        """Revert the pin to input mode and release resources."""
        if self._device is not None:
            try:
                self._device.close()
            except DeviceClosed:
                pass
            except GPIOZeroError as exc:
                logger.warning("Error while closing OutputPin %s: %s", self.name, exc)
            finally:
                self._device = None
        logger.info("OutputPin %s (GPIO %d) shutdown.", self.name, self.number)

    def get_value(self):
        """Return the current pin value."""
        with self._LOCK:
            return self._value

    def set_value(self, value):
        """Set the pin value, validating the type and range."""
        if value not in self.ALLOWED_VALUES:
            raise ValueError(f"Invalid value {value!r}; must be one of {self.ALLOWED_VALUES}.")
        with self._LOCK:
            self._value = value
        try:
            self._device.value = value
        except DeviceClosed:
            logger.error("Cannot set value for OutputPin %s (GPIO %d): device is closed.", self.name, self.number)
            raise
        except GPIOZeroError as exc:
            logger.error("Failed to set value for OutputPin %s (GPIO %d): %s", self.name, self.number, exc)
            raise

    def trigger(self):
        """Generate a 100‑microsecond high pulse (thread-safe)."""
        with self._LOCK:
            if self._device is None:
                raise RuntimeError("OutputPin %s is not initialized; cannot trigger." % self.name)
            self._device.on()
            time.sleep(0.0001)
            self._device.off()


class TriggerPin(OutputPin):
    """Output pin that can be pulsed high to trigger an event."""

    def __init__(self, number, name, initial_value=None, pulse_high=False):
        super().__init__(number, name, initial_value)
        self.pulse_high = pulse_high
