import zmq
import time
import logging
import signal
import sys
import atexit

try:
    import RPi.GPIO as GPIO
except (ImportError, RuntimeError):
    GPIO = None

logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)
logger = logging.getLogger(__name__)


class PIDHandler:
    """
    Manages a PID controller with a PWM error output on physical pin 12
    (BCM GPIO 18) and a digital error output on physical pin 10
    (BCM GPIO 15).
    """

    def __init__(self, error_pin=12, digital_pin=10, frequency=1000,
                 last_msg_timeout=20):
        self.error_pin = error_pin
        self.digital_pin = digital_pin
        self.frequency = frequency
        self.last_msg_timeout = last_msg_timeout
        self.global_err_state = False
        self.last_msg = time.time()
        self.pwm_initialized = False
        self.digital_initialized = False
        self.zmq_socket = None
        self._closed = False

        if GPIO is None:
            logger.error("RPi.GPIO is not available; cannot initialize GPIO.")
            return

        try:
            GPIO.setmode(GPIO.BOARD)
            GPIO.setwarnings(False)
            GPIO.setup(self.error_pin, GPIO.OUT)
            GPIO.setup(self.digital_pin, GPIO.OUT)
            self.pwm_initialized = True
            self.digital_initialized = True
            logger.info(
                "GPIO initialized: error pin BCM %d, digital pin BCM %d",
                self.error_pin, self.digital_pin
            )
        except Exception as e:
            logger.error("GPIO initialization failed: %s", e)
            self.cleanup()
            return

    def cleanup(self):
        """Release GPIO resources."""
        if self._closed:
            return
        self._closed = True
        try:
            if self.pwm_initialized:
                try:
                    GPIO.output(self.error_pin, 0)
                except Exception:
                    pass
            if self.digital_initialized:
                try:
                    GPIO.output(self.digital_pin, 0)
                except Exception:
                    pass
            GPIO.cleanup()
            logger.info("GPIO resources released.")
        except Exception as e:
            logger.error("Error during GPIO cleanup: %s", e)

    def _signal_handler(self, signum, frame):
        logger.info("Received signal %d; initiating cleanup.", signum)
        self.cleanup()
        sys.exit(0)

    def _atexit_handler(self):
        self.cleanup()

    atexit.register(self._atexit_handler)

    def _init_gpio(self):
        """Initialize GPIO pins; raise on failure so caller can re-raise."""
        if self.pwm_initialized:
            return
        try:
            GPIO.setmode(GPIO.BOARD)
            GPIO.setwarnings(False)
            GPIO.setup(self.error_pin, GPIO.OUT)
            GPIO.setup(self.digital_pin, GPIO.OUT)
            self.pwm_initialized = True
            logger.info(
                "GPIO initialized: error pin BCM %d, digital pin BCM %d",
                self.error_pin, self.digital_pin
            )
        except Exception as e:
            logger.error("GPIO initialization failed: %s", e)
            raise

    def _init_zmq(self):
        """Initialize the ZeroMQ watchdog socket; raise on failure."""
        if self.zmq_socket is not None:
            return
        try:
            self.zmq_socket = zmq.Context().socket(zmq.PUB)
            self.zmq_socket.setsockopt(zmq.LINGER, 0)
            self.zmq_socket.connect("tcp://127.0.0.1:5555")
            logger.info("ZMQ watchdog socket connected.")
        except Exception as e:
            logger.error("ZMQ initialization failed: %s", e)
            raise

    def update_error_output(self, state: bool):
        """Set the global error state and drive the output."""
        self.global_err_state = state
        if self.pwm_initialized:
            try:
                GPIO.output(self.error_pin, 1 if state else 0)
            except Exception as e:
                logger.error("Failed to update PWM error output: %s", e)
        else:
            try:
                GPIO.output(self.digital_pin, 1 if state else 0)
            except Exception as e:
                logger.error("Failed to update digital error output: %s", e)

    def set_error_output(self, state: bool):
        """Directly set the global error state."""
        self.global_err_state = state

    def handle_message(self):
        """
        Non-blocking receive.  If no message arrives within last_msg_timeout
        seconds, set the global error state to True.
        """
        if self.zmq_socket is None:
            logger.warning("ZMQ socket not initialized; cannot handle message.")
            return
        try:
            self.zmq_socket.setsockopt_string(zmq.RCVHWM, 1)
            msg = self.zmq_socket.recv()
            if msg is None:
                logger.warning("No message received within timeout; setting error.")
                self.update_error_output(True)
            else:
                self.last_msg = time.time()
                self.last_msg_timeout = 20
                try:
                    self._process_message(msg)
                except Exception as e:
                    logger.error("Error processing message: %s", e)
        except zmq.ZMQError as e:
            logger.error("ZMQ error during message handling: %s", e)
        except Exception as e:
            logger.error("Unexpected error handling message: %s", e)

    def _process_message(self, msg):
        """Placeholder for message processing logic."""
        logger.debug("Received message: %s", msg)

    def run(self):
        """Main loop: handle messages and enforce watchdog timeout."""
        self._init_gpio()
        self._init_zmq()
        logger.info("PIDHandler running. Watchdog timeout: %d s.",
                    self.last_msg_timeout)
        try:
            while True:
                time.sleep(0.1)
                self.handle_message()
        except KeyboardInterrupt:
            logger.info("KeyboardInterrupt received; shutting down.")
        except Exception as e:
            logger.error("Unhandled exception in main loop: %s", e)
        finally:
            self.cleanup()


def main():
    handler = PIDHandler(error_pin=12, digital_pin=10, frequency=1000,
                         last_msg_timeout=20)
    signal.signal(signal.SIGINT, handler._signal_handler)
    signal.signal(signal.SIGTERM, handler._signal_handler)
    handler.run()


if __name__ == "__main__":
    main()

