import socket
import logging
import signal
import sys
import time
from gpiozero import OutputDevice

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s"
)

BACKLIGHT_PIN = 24
ACCEPT_TIMEOUT = 5
MAX_COMMAND_LENGTH = 64

backlight = None
server_socket = None
running = True


def cleanup(signum=None, frame=None):
    global running, backlight, server_socket
    running = False
    logging.info("Shutting down...")
    if server_socket is not None:
        try:
            server_socket.close()
        except Exception as e:
            logging.error(f"Error closing socket: {e}")
    if backlight is not None:
        try:
            backlight.close()
        except Exception as e:
            logging.error(f"Error closing GPIO device: {e}")
    if signum is not None:
        sys.exit(0)


def handle_command(command: str) -> str:
    if not command:
        return "unknown command"
    if command == "on":
        backlight.on()
        return "backlight on"
    elif command == "off":
        backlight.off()
        return "backlight off"
    else:
        return "unknown command"


def main():
    global backlight, server_socket

    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    try:
        backlight = OutputDevice(BACKLIGHT_PIN)
        logging.info(f"Backlight initialized on GPIO {BACKLIGHT_PIN}")
    except Exception as e:
        logging.error(f"Failed to initialize backlight on GPIO {BACKLIGHT_PIN}: {e}")
        sys.exit(1)

    try:
        server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        server_socket.bind(("0.0.0.0", 9100))
        server_socket.listen(1)
        server_socket.settimeout(ACCEPT_TIMEOUT)
        logging.info(f"Listening on port 9100...")

        while running:
            try:
                conn, addr = server_socket.accept()
            except socket.timeout:
                continue
            except OSError as e:
                if running:
                    logging.error(f"Accept error: {e}")
                continue

            try:
                data = conn.recv(MAX_COMMAND_LENGTH)
                if not data:
                    logging.info("Client disconnected without data")
                    continue

                command = data.decode("utf-8", errors="ignore").strip()
                response = handle_command(command)
