        except Exception as e:
            logger.error(f"Failed to initialize GPIO pins {clk_pin}/{dt_pin}: {e}")
            raise

        self._register_events()

    def _register_events(self):
        self.clk.when_activated = self._clockwise
        self.clk.when_deactivated = self._counter_clockwise
        self.dt.when_activated = self._clockwise
        self.dt.when_deactivated = self._counter_clockwise

