import signal
import sys
import time

try:
    import smbus2
except ImportError:
    print("Error: smbus2 library not found. Install with: pip install smbus2")
    sys.exit(1)

# BH1750 I2C address (default)
BH1750_ADDR = 0x76

# Register addresses
BH1750_REG_CONTROL = 0x80
BH1750_REG_LIGHT = 0x81

# Global flag for graceful shutdown
_running = True


def _signal_handler(signum, frame):
    """Handle SIGINT (Ctrl+C) for clean shutdown."""
    global _running
    _running = False


def _read_register(bus, reg):
    """Read a single byte from a BH1750 register with error handling."""
    try:
        return bus.read_byte_data(BH1750_ADDR, reg)
    except OSError as e:
        print(f"I2C read error at register 0x{reg:02X}: {e}")
        return None


def _write_register(bus, reg, value):
    """Write a single byte to a BH1750 register with error handling."""
    try:
        bus.write_byte_data(BH1750_ADDR, reg, value)
    except OSError as e:
        print(f"I2C write error at register 0x{reg:02X}: {e}")


def _init_sensor(bus):
    """Initialize the BH1750 sensor with a forced measurement."""
    _write_register(bus, BH1750_REG_CONTROL, 0x01)  # Start measurement
    time.sleep(0.18)  # Wait for measurement to complete (max 180 ms)
    raw = _read_register(bus, BH1750_REG_LIGHT)
    if raw is None:
        raise RuntimeError("BH1750 sensor did not respond to initialization.")
    return raw


def main():
    global _running

    # Install SIGINT handler for clean Ctrl+C exit
    signal.signal(signal.SIGINT, _signal_handler)

    i2c_bus = None
    try:
        i2c_bus = smbus2.SMBus(1)
    except OSError as e:
        print(f"Error: Failed to open I2C bus 1: {e}")
        print("Ensure I2C is enabled (raspi-config) and the sensor is connected.")
        sys.exit(1)

    try:
        # Initialize the sensor
        _init_sensor(i2c_bus)
        print("BH1750 light sensor initialized successfully.")

        while _running:
            try:
                raw = _read_register(i2c_bus, BH1750_REG_LIGHT)
                if raw is None:
                    print("Error: Failed to read lux value from sensor.")
                    time.sleep(1)
                    continue

                lux = (raw * 125.0) / 1.2
                print(f"Ambient Lux: {lux:.2f}")

            except OSError as e:
                print(f"I2C communication error: {e}")

            time.sleep(1)

    except RuntimeError as e:
        print(f"Sensor initialization failed: {e}")
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        if i2c_bus is not None:
            try:
                i2c_bus.close()
            except Exception:
                pass
        print("Program terminated.")


if __name__ == "__main__":
    main()

