import argparse
import signal
import sys
import time
from typing import List, Optional

try:
    from gpiozero import Button
    from gpiozero.pins.native import NativeFactory
except ImportError:
    print("Error: gpiozero is not installed. Install with: pip install gpiozero", file=sys.stderr)
    sys.exit(1)

DEFAULT_DEBOUNCE_MS = 200

_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


def get_raspi_model() -> str:
    """Return the Raspberry Pi model name from the board revision code."""
    try:
        with open('/proc/cpuinfo', 'r') as f:
            for line in f:
                if line.startswith('Revision'):
                    rev_hex = line.split(':')[1].strip()
                    rev_dec = int(rev_hex, 16)
                    rev_map = {
                        0x10: '3B-P',
                        0x14: 'B+ 40-pin',
                        0x20: '256KB',
                        0x22: '4GB',
                        0x30: '4GB',
                        0x32: '8GB',
                        0x34: '16GB',
                    }
                    return rev_map.get(rev_dec, 'Unknown')
    except Exception:
        return 'Unknown'


def get_gpio_num() -> int:
    """Return the number of GPIO pins on the board header."""
    try:
        with open('/proc/cpuinfo', 'r') as f:
            for line in f:
                if line.startswith('Revision'):
                    rev_hex = line.split(':')[1].strip()
                    rev_dec = int(rev_hex, 16)
                    rev_map = {
                        0x10: 17,
                        0x14: 26,
                        0x20: 26,
                        0x22: 26,
                        0x30: 26,
                        0x32: 26,
                        0x34: 26,
                    }
                    return rev_map.get(rev_dec, 26)
    except Exception:
        return 26


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(description='Raspberry Pi GPIO debouncing demo.')
    parser.add_argument('-d', '--debounce', type=int, default=DEFAULT_DEBOUNCE_MS,
                        help='Debounce time in milliseconds (default: %d)' % DEFAULT_DEBOUNCE_MS)
    return parser.parse_args()


def main() -> int:
    global _running
    args = parse_args()
    debounce_ms = args.debounce

    signal.signal(signal.SIGINT, _signal_handler)
