#!/usr/bin/env python3
"""Rainbow HAT 3-bit binary counter with touchpads.

Touchpad A (GPIO5) -> bit 4
Touchpad B (GPIO6) -> bit 2
Touchpad C (GPIO12) -> bit 1
"""

import signal
import sys
import time

try:
    import board
    import busio
    from adafruit_apa102 import APA102
    from digitalio import DigitalInOut
    from adafruit_rainbowhat import RainbowHAT
except ImportError as exc:
    print(f"Missing dependency: {exc}", file=sys.stderr)
    print("Install with: pip install adafruit-circuitpython-rainbowhat", file=sys.stderr)
    sys.exit(1)

# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------
TOUCH_PINS = {"A": 5, "B": 6, "C": 12}
NUM_BITS = len(TOUCH_PINS)

# ---------------------------------------------------------------------------
# Globals for cleanup
# ---------------------------------------------------------------------------
_hat = None
_running = True


def _cleanup(signum=None, frame=None):
    """Release every HAT resource on exit."""
    global _running, _hat
    _running = False
    if _hat is not None:
        try:
            _hat.clear_display()
        except Exception:
            pass
        try:
            _hat.clear_leds()
        except Exception:
            pass
        try:
            _hat.clear_strip()
        except Exception:
            pass
        try:
            _hat.set_buzzer_pwm(0)
        except Exception:
            pass
        try:
            _hat.set_rainbow_on()
        except Exception:
            pass
    if signum is not None:
        sys.exit(0)


def _init_hat():
    """Initialise the Rainbow HAT; return True on success, False on failure."""
    global _hat
    try:
        _hat = RainbowHAT()
        _hat.set_buzzer_pwm(0)
        _hat.set_rainbow_on()
        return True
    except Exception as exc:
        print(f"Rainbow HAT init failed: {exc}", file=sys.stderr)
        _hat = None
        return False


def _init_i2c():
    """Initialise the I2C bus; return True on success, False on failure."""
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
        return i2c
    except Exception as exc:
        print(f"I2C bus init failed: {exc}", file=sys.stderr)
        return None


def _init_leds():
    """Initialise the APA102 strip and discrete LEDs; return True on success."""
    try:
        strip = APA102(14, i2c_addr=0x00, global_brightness=0.5)
        strip.fill((0, 0, 0))
        return True
    except Exception as exc:
        print(f"APA102 init failed: {exc}", file=sys.stderr)
        return False


def _init_buzzer():
    """Initialise the buzzer; return True on success."""
    try:
        buzzer = DigitalInOut(13)
        buzzer.direction = DigitalInOut.OUT
        buzzer.value = False
        return True
    except Exception as exc:
        print(f"Buzzer init failed: {exc}", file=sys.stderr)
        return False


def _init_rainbow_leds():
    """Initialise the discrete LEDs; return True on success."""
    try:
        led_pins = {"A": DigitalInOut(7), "B": DigitalInOut(8), "C": DigitalInOut(8)}
        for name, pin in led_pins.items():
            pin.direction = DigitalInOut.OUT
            pin.value = False
        return True
    except Exception as exc:
        print(f"Discrete LEDs init failed: {exc}", file=sys.stderr)
        return False


def _init_display():
    """Initialise the 14-segment display; return True on success."""
    try:
        display = _hat.display
        display.clear()
        return True
    except Exception as exc:
        print(f"Display init failed: {exc}", file=sys.stderr)
        return False


def _update_display(value):
    """Render the decimal value 0-7 on the 14-segment display."""
    if not _init_display():
        return
    try:
        display = _hat.display
        if value < 0 or value > 7:
            display.clear()
            display.show()
            return
        display.clear()
        display.print_hex(value)
        display.show()
    except Exception as exc:
        print(f"Display update failed: {exc}", file=sys.stderr)


def _update_leds(value):
    """Drive the discrete LEDs and APA102 strip based on the bit states."""
    if not _init_leds():
        return
    if not _init_i2c():
        return
    if not _init_buzzer():
        return
    if not _init_rainbow_leds():
        return
    if not _init_leds():
        return

    try:
        # Discrete LEDs
        for bit in range(NUM_BITS):
            state = (value >> bit) & 1
            if state:
                _hat.set_led(TOUCH_PINS[f"A+{bit}"])
                _hat.set_led(TOUCH_PINS[f"B+{bit}"])
                _hat.set_led(TOUCH_PINS[f"C+{bit}"])
            else:
                _hat.clear_led(TOUCH_PINS[f"A+{bit}"])
                _hat.clear_led(TOUCH_PINS[f"B+{bit}"])
                _hat.clear_led(TOUCH_PINS[f"C+{bit}"])

        # APA102 strip
        strip = _hat.strip
        if value == 0:
            strip.fill((0, 0, 0))
        elif value == 7:
            for i in range(14):
                strip.set_pixel(i, (255, 255, 255))
        else:
            strip.set_pixel(value, (255, 0, 0))
            strip.set_pixel(value + 1, (0, 255, 0))
            strip.set_pixel(value + 2, (0, 0, 255))
        strip.show()

        # Buzzer
        _hat.set_buzzer_pwm(0.5)
        _hat.set_rainbow_on()
    except Exception as exc:
        print(f"LED/strip update failed: {exc}", file=sys.stderr)


def _handle_touch(channel):
    """Callback for each touchpad press."""
    global _hat
    if _hat is None:
        return
    try:
        bit = channel.value
        if bit < 0 or bit > 7:
            return
        _hat.bit_states[bit] = not _hat.bit_states[bit]
        _update_leds(_hat.bit_states[0] << 4 | (_hat.bit_states[1] << 2) | _hat.bit_states[2])
    except Exception as exc:
        print(f"Touch callback error: {exc}", file=sys.stderr)


def main():
    global _running

    signal.signal(signal.SIGINT, _cleanup)
    signal.signal(signal.SIGTERM, _cleanup)

    if not _init_hat():
        print("Rainbow HAT unavailable — exiting.", file=sys.stderr)
        sys.exit(1)

    if not _init_leds():
        print("Discrete LEDs unavailable — exiting.", file=sys.stderr)
        _cleanup()
        sys.exit(1)

    if not _init_buzzer():
        print("Buzzer unavailable — exiting.", file=sys.stderr)
        _cleanup()
        sys.exit(1)

    if not _init_display():
        print("Display unavailable — exiting.", file=sys.stderr)
        _cleanup()
        sys.exit(1)

    for bit in range(NUM_BITS):
        try:
            channel = _hat.touch[TOUCH_PINS[f"A+{bit}"]]
            channel.when_activated = lambda ch=channel: _handle_touch(ch)
        except Exception as exc:
            print(f"Touchpad init failed for bit {bit}: {exc}", file=sys.stderr)

    print("Rainbow HAT ready. Press Ctrl+C to exit.")

    try:
        signal.pause()
    except KeyboardInterrupt:
        pass
    finally:
        _cleanup()


if __name__ == "__main__":
    main()

