LED_PIN = 18

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def validate_grid(grid_size):
    if not isinstance(grid_size, int) or grid_size <= 0:
        raise ValueError(f"Invalid grid size: {grid_size}")
    return True

def build_grid(grid_size):
    if not validate_grid(grid_size):
        raise ValueError("Invalid grid size")
    return [[0] * grid_size for _ in range(grid_size)]

def bfs(grid, start, end):
    if not (0 <= start[0] < grid_size and 0 <= start[1] < grid_size):
        raise ValueError(f"Start cell {start} is out of bounds")
    if not (0 <= end[0] < grid_size and 0 <= end[1] < grid_size):
        raise ValueError(f"End cell {end} is out of bounds")
    if grid[end[0]][end[1]] == 1:
        raise ValueError(f"End cell {end} is an obstacle")
    if start == end:
        return []
    frontier = [(start, [start])]
    while _running and frontier:
        current, path = frontier.pop(0)
        if current == end:
            return path
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
