    signal.signal(signal.SIGTERM, _signal_handler)
    try:
        grid = build_grid(GRID_SIZE)
        path = bfs(grid, START_CELL, DEFECT_CELL)
        if path:
            logging.info(f"Path found: {path}")
            drive_status_led(True)
