import json
import random
import sys

try:
    import gpiozero
except ImportError:
    gpiozero = None

# Keyword -> farm action mapping
KEYWORD_TO_ACTION = {
    "water": "open_valve",
    "stop": "close_valve",
    "status": "report",
}

# Number of simulated audio frames
NUM_FRAMES = 6


def generate_audio_frame():
    """Return a simulated audio frame with a random energy level."""
    energy = random.randint(0, 9)
    return {"energy": energy}


def transcribe_frame(frame):
    """Return the transcribed keyword for a given audio frame."""
    energy = frame.get("energy")
    if energy is None:
        raise ValueError("Frame must contain an 'energy' key")
    keyword = random.choice(list(KEYWORD_TO_ACTION.keys()))
    return keyword


def perform_action(keyword):
    """Return the farm action corresponding to a keyword."""
    return KEYWORD_TO_ACTION.get(keyword)


def main():
    """Run the voice recognition simulation and persist the chosen actions."""
    actions = []
    try:
        for i in range(NUM_FRAMES):
            frame = generate_audio_frame()
            try:
                keyword = transcribe_frame(frame)
            except ValueError as exc:
                print(f"Frame {i}: transcription error: {exc}", file=sys.stderr)
                continue
            action = perform_action(keyword)
            actions.append(action)
            print(f"Frame {i}: Keyword={keyword}, Action={action}")

        # Persist the chosen actions to a JSON file
        with open("voice_actions.json", "w") as f:
            json.dump(actions, f, indent=2)

    except KeyboardInterrupt:
        print("\nSimulation interrupted by user.", file=sys.stderr)
    except Exception as exc:
        print(f"Unexpected error during simulation: {exc}", file=sys.stderr)
    finally:
        # Ensure the actions list is written to disk
        with open("voice_actions.json", "w") as f:
            json.dump(actions, f, indent=2)
        print(f"Voice actions persisted to voice_actions.json ({len(actions)} actions).")


if __name__ == "__main__":
    main()

