import random
import time
import signal
import sys

try:
    from gpiozero import LED
    from gpiozero.exc import GPIOZeroError, GPIODeviceError
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero")
    sys.exit(1)

# Configuration
ALERT_PIN = 18
ALERT_THRESHOLD = 50
NUM_READINGS = 5
DELAY_SECONDS = 2
ERROR_PROBABILITY = 0.1
RETRY_ATTEMPTS = 1

# Global flag for graceful shutdown
_running = True


def _signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for clean shutdown."""
    global _running
    _running = False


def simulate_water_quality_reading():
    """Simulates a water quality reading between 0 and 100."""
    return random.randint(0, 100)


def validate_reading(reading):
    """Validates the water quality reading."""
    if not 0 <= reading <= 100:
        raise ValueError(f"Reading must be between 0 and 100, got {reading}")


def control_alert_system(led, reading, threshold):
    """Controls the alert system based on the water quality reading."""
    if reading < threshold:
        led.on()
        return "ON"
    else:
        led.off()
        return "OFF"


def handle_sensor_failure(reading):
    """Handles simulated sensor failure with retry."""
    if random.random() < ERROR_PROBABILITY:
        print(f"Simulated sensor failure: reading {reading}")
        print("Retrying...")
        return simulate_water_quality_reading()
    return reading


def main():
    """Main function to simulate water quality monitoring."""
    global _running

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    led = None
    try:
        # Initialize the LED on GPIO18 with a 330-ohm resistor
        try:
            led = LED(ALERT_PIN, initial_value=False, pin_factory=None)
        except (GPIOZeroError, GPIODeviceError) as e:
            print(f"Error: Failed to initialize GPIO {ALERT_PIN}: {e}")
            return
        except Exception as e:
            print(f"Unexpected error initializing GPIO {ALERT_PIN}: {e}")
            return

        print(f"Water quality monitoring started. Alert on GPIO{ALERT_PIN} (BCM).")
        print(f"Threshold: {ALERT_THRESHOLD}%")
        print(f"Simulating {NUM_READINGS} readings with a {DELAY_SECONDS}s delay...")

        for i in range(NUM_READINGS):
            if not _running:
                print("\nShutdown requested. Exiting...")
                break

            try:
                # Simulate sensor failure with retry
                reading = handle_sensor_failure(simulate_water_quality_reading())

                # Validate the reading
                validate_reading(reading)

                # Control the alert system
                status = control_alert_system(led, reading, ALERT_THRESHOLD)
                print(f"Reading {i + 1}/{NUM_READINGS}: {reading}% - {status}")

            except ValueError as e:
                print(f"Error: {e}")
            except GPIODeviceError as e:
                print(f"GPIO error: {e}")
            except Exception as e:
                print(f"Unexpected error: {e}")

            if i < NUM_READINGS - 1 and _running:
                time.sleep(DELAY_SECONDS)

    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        # Clean up GPIO resources
        if led is not None:
            try:
                led.close()
            except Exception:
                pass
        print("GPIO cleanup complete. Exiting.")


if __name__ == "__main__":
    main()

