import RPi.GPIO as GPIO
import time
import sys

DATA_PIN = 5
CLOCK_PIN = 6
LATCH_PIN = 12

_initialized = False


def _cleanup():
    """Release GPIO resources safely."""
    global _initialized
    if _initialized:
        _initialized = False
        try:
            GPIO.cleanup()
        except Exception:
            pass


def _setup():
    """Configure BCM mode and the three shift-register control pins."""
    global _initialized
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setwarnings(False)
        for pin in (DATA_PIN, CLOCK_PIN, LATCH_PIN):
            GPIO.setup(pin, GPIO.OUT, initial=GPIO.LOW)
