    sys.exit(1)

PUMP_PIN = 17
MOISTURE_THRESHOLD = 30
NUM_READINGS = 5
DELAY_SECONDS = 2

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def read_moisture_level():
    """Simulate a soil moisture sensor reading between 0 and 100 inclusive."""
    return random.randint(0, 100)

def control_pump(moisture_level):
    """Drive the pump HIGH when moisture is below threshold, LOW otherwise."""
    if moisture_level < MOISTURE_THRESHOLD:
        GPIO.output(PUMP_PIN, GPIO.HIGH)
        return "Pump ON: moisture too low"
    else:
        GPIO.output(PUMP_PIN, GPIO.LOW)
        return "Pump OFF: moisture sufficient"

def cleanup():
    """Turn the pump off and release GPIO resources."""
    try:
        GPIO.output(PUMP_PIN, GPIO.LOW)
    except Exception:
        pass
    GPIO.cleanup()

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(PUMP_PIN, GPIO.OUT, initial=GPIO.LOW)
    except RuntimeError as e:
        print(f"Error: Failed to initialize GPIO: {e}", file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        print(f"Unexpected error during GPIO setup: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        for i in range(NUM_READINGS):
            if not _running:
                break

            moisture = read_moisture_level()
            pump_state = control_pump(moisture)
            print(f"Reading {i + 1}/{NUM_READINGS} - Moisture: {moisture}%, Pump: {pump_state}")

            if i < NUM_READINGS - 1 and _running:
                time.sleep(DELAY_SECONDS)

        if _running:
            print("Soil moisture monitoring complete.")
        else:
            print("\nMonitoring interrupted. Shutting down safely...")

    except Exception as e:
        print(f"Runtime error: {e}", file=sys.stderr)
    finally:
        cleanup()

if __name__ == "__main__":
    main()

