# Configuration
PIR_PIN = 4
DEBOUNCE_SECONDS = 60
POLL_INTERVAL = 1  # seconds

# Global state
last_feeding_time = None
running = True


def is_feeding_time(now: datetime.datetime) -> bool:
    """Return True if the current time is between 07:00-08:00 or 18:00-19:00."""
    return (now.hour == 7 or now.hour == 8) or (now.hour == 18 or now.hour == 19)


def trigger_feeder() -> None:
    """Trigger the feeder mechanism (simulated here)."""
    print("Feeding initiated at", datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S"))


def cleanup_gpio() -> None:
    """Clean up GPIO resources."""
    GPIO.cleanup()


def handle_motion() -> None:
    """Handle a motion detection event."""
    global last_feeding_time

    now = datetime.datetime.now()
    if is_feeding_time(now):
        if last_feeding_time is None or (now - last_feeding_time).total_seconds() >= DEBOUNCE_SECONDS:
            trigger_feeder()
            last_feeding_time = now
        else:
            print("Not feeding time or recently fed.")
    else:
        print("Not feeding time or recently fed.")


def main() -> None:
    """Main program loop."""
    global running

    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(PIR_PIN, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
    except Exception as e:
        print(f"GPIO setup failed: {e}")
        sys.exit(1)

    print("PIR sensor initialized on BCM pin 4. Press Ctrl+C to exit.")

    try:
        while running:
            try:
                motion_detected = GPIO.input(PIR_PIN)
            except Exception as e:
                print(f"Error reading GPIO pin: {e}")
                time.sleep(POLL_INTERVAL)
                continue

            if motion_detected:
                handle_motion()

            time.sleep(POLL_INTERVAL)

    except KeyboardInterrupt:
        print("Exiting program…")
    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        cleanup_gpio()


if __name__ == "__main__":
    main()

