import signal
import sys
import time
import logging
from typing import Optional

try:
    import serial
    from pymodbus.client import ModbusSerialClient as ModbusClient
    from pymodbus.constants import Endian
    from pymodbus.payload import BinaryPayloadDecoder
    from pymodbus.exceptions import ModbusIOException, ModbusException
    from pymodbus.constants import UnitId
except ImportError as e:
    print(f"Missing required library: {e}. Install with: pip install pymodbus pyserial")
    sys.exit(1)

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

class ModbusRTUServoController:
    """
    Controls a servo motor via Modbus RTU over a UART connection.
    """

    def __init__(self, port: str, baudrate: int, slave_id: int, timeout: float = 2.0):
        self.port = port
        self.baudrate = baudrate
        self.slave_id = slave_id
        self.timeout = timeout
        self.client: Optional[ModbusClient] = None
        self._running = True

        try:
            self.client = ModbusSerialClient(
                port=port,
                baudrate=baudrate,
                bytesize=8,
                parity='N',
                stopbits=1,
                timeout=timeout
            )
            if not self.client.connect():
                raise IOError(f"Failed to open serial port {port}")
            logger.info(f"Connected to Modbus RTU slave {slave_id} on {port}")
        except Exception as e:
            logger.error(f"Initialization error: {e}")
            self.client = None
            raise

    def connect(self) -> bool:
        """Connects to the Modbus RTU device."""
        if self.client is None:
            logger.error("Cannot connect: client not initialized.")
            return False
        try:
            if not self.client.connect():
                logger.error("Failed to connect to Modbus RTU device.")
                return False
            logger.info("Connected to Modbus RTU device.")
            return True
        except Exception as e:
            logger.error(f"Connection error: {e}")
            return False

    def disconnect(self) -> None:
        """Disconnects from the Modbus RTU device."""
        if self.client is not None:
            try:
                self.client.close()
                logger.info("Disconnected from Modbus RTU device.")
            except Exception as e:
                logger.error(f"Error during disconnect: {e}")
            finally:
                self.client = None

    def _validate_slave_id(self, slave_id: int) -> None:
        if not isinstance(slave_id, int) or not (0 <= slave_id <= 247):
            raise ValueError("Slave ID must be an integer between 0 and 247.")

    def _validate_timeout(self, timeout: float) -> None:
        if not isinstance(timeout, (int, float)) or timeout < 0:
            raise ValueError("Timeout must be a non-negative number.")

    def _validate_baudrate(self, baudrate: int) -> None:
        if not isinstance(baudrate, int) or baudrate <= 0:
            raise ValueError("Baudrate must be a positive integer.")

    def _validate_port(self, port: str) -> None:
        if not isinstance(port, str) or not port.strip():
            raise ValueError("Port must be a non-empty string.")

    def _validate_unit_id(self, unit_id: int) -> None:
        if not isinstance(unit_id, int) or not (0 <= unit_id <= 247):
            raise ValueError("Unit ID must be an integer between 0 and 247.")

    def _validate_response(self, response: bytes) -> None:
        if response is None or len(response) == 0:
            raise ModbusException("Empty response received.")

    def _read_register(self, address: int, count: int, slave_id: int, unit_id: int) -> int:
        """Reads a block of registers from the slave."""
        if self.client is None:
            raise ModbusException("Client not initialized.")
        if not self.client.is_socket_open():
            raise ModbusException("Client not connected.")

        try:
            self.client.write_u_int8(address, 1)
            time.sleep(0.01)
            response = self.client.read_holding_registers(address=address, count=count, slave=slave_id)
            self._validate_response(response)
            decoder = BinaryPayloadDecoder.fromRegisters(response, byteorder=Endian.BIG, wordorder=Endian.BIG)
            return decoder.decode_32bit_int()
        except (ModbusIOException, ModbusException, OSError) as e:
            logger.error(f"Error reading register {address}: {e}")
            raise ModbusException(f"Failed to read register {address}: {e}")

    def _write_register(self, address: int, value: int, slave_id: int, unit_id: int) -> None:
        """Writes a single register."""
        if self.client is None:
            raise ModbusException("Client not initialized.")
        if not self.client.is_socket_open():
            raise ModbusException("Client not connected.")

        try:
            self.client.write_u_int8(address, 1)
            time.sleep(0.01)
            self.client.write_holding_registers(address=address, count=1, value=value)
            self._validate_response(self.client.read_holding_registers(address=address, count=1, slave=slave_id))
        except (ModbusIOException, ModbusException, OSError) as e:
            logger.error(f"Error writing register {address}: {e}")
            raise ModbusException(f"Failed to write register {address}: {e}")

    def move_servo(self, position: int, timeout: float = 10.0) -> bool:
        """Moves the servo to a specific position."""
        if self.client is None:
            raise ModbusException("Client not initialized.")
        if not self.client.is_socket_open():
            raise ModbusException("Client not connected.")

        try:
            self._validate_slave_id(self.slave_id)
            self._validate_timeout(timeout)
            self._validate_response(self.client.read_holding_registers(address=1, count=1, slave=self.slave_id))

            self._write_register(1, position, self.slave_id, 0)
            logger.info(f"Servo moved to position {position}")
            return True
        except (ModbusException, OSError) as e:
            logger.error(f"Error moving servo: {e}")
            return False

    def read_servo_position(self, timeout: float = 10.0) -> Optional[int]:
        """Reads the current servo position."""
        if self.client is None:
            raise ModbusException("Client not initialized.")
        if not self.client.is_socket_open():
            raise ModbusException("Client not connected.")

        try:
            self._validate_slave_id(self.slave_id)
            self._validate_timeout(timeout)
            self._validate_response(self.client.read_holding_registers(address=1, count=1, slave=self.slave_id))

            position = self._read_register(1, 1, self.slave_id, 0)
            logger.info(f"Servo position: {position}")
            return position
        except (ModbusException, OSError) as e:
            logger.error(f"Error reading servo position: {e}")
            return None

    def close(self) -> None:
        """Closes the connection to the Modbus RTU device."""
        if self.client is not None:
            try:
                self.client.close()
                logger.info("Connection to Modbus RTU device closed.")
            except Exception as e:
                logger.error(f"Error closing connection: {e}")
            finally:
                self.client = None


def signal_handler(signum, frame, controller: Optional[ModbusRTUServoController] = None):
    """Handle SIGINT and SIGTERM for clean shutdown."""
    logger.info(f"Signal {signum} received, shutting down...")
    if controller is not None:
        controller.close()
    sys.exit(0)


