try:
    from gpiozero import OutputDevice, PWMOutputDevice
except ImportError:
    print("Error: gpiozero is required. Install with: sudo apt install python3-gpiozero", file=sys.stderr)
    sys.exit(1)

# GPIO pin assignments (BCM numbering)
LASER_PIN = 17
H_SERVO_PIN = 18
V_SERVO_PIN = 19

# Pulse-width mapping: 0.0 -> minimum, 1.0 -> maximum
hp = [0.0, 0.25, 0.5, 0.75, 1.0, 0.75, 0.5, 0.25, 0.0]
vp = [0.0, 0.25, 0.5, 0.75, 1.0, 0.75, 0.5, 0.25, 0.0]

# Global handles for cleanup
laser = None
h_servo = None
v_servo = None


def cleanup():
    """Turn off the laser and close all GPIO resources."""
    global laser, h_servo, v_servo
    if laser is not None:
        try:
            laser.off()
            laser.close()
        except Exception:
            pass
    if h_servo is not None:
        try:
            h_servo.close()
        except Exception:
            pass
    if v_servo is not None:
        try:
            v_servo.close()
        except Exception:
            pass


def signal_handler(signum, frame):
    """Handle SIGTERM/SIGINT for clean shutdown."""
    print(f"\nReceived signal {signum}, shutting down...")
    cleanup()
    sys.exit(0)


class Laser:
    """Controls a laser via a digital output."""

    def __init__(self, pin):
        self.pin = pin
        try:
            self.laser = OutputDevice(pin)
        except Exception as e:
            raise RuntimeError(f"Failed to initialize laser on GPIO{pin}: {e}") from e

    def on(self):
        self.laser.on()

    def off(self):
        self.laser.off()

    def close(self):
        if self.laser is not None:
            try:
                self.laser.close()
            except Exception:
                pass
            self.laser = None


class Aim:
    """Aiming controller with horizontal and vertical servos."""

    def __init__(self, ld, sd):
        self.ld = ld
        self.sd = sd
        self.hp = hp
        self.vp = vp
        self.b = 10
        self.laser = Laser(LASER_PIN)
        self.h_servo = PWMOutputDevice(H_SERVO_PIN, frequency=1000, initial_value=0)
        self.v_servo = PWMOutputDevice(V_SERVO_PIN, frequency=1000, initial_value=0)

    def _move_servo(self, servo, position):
        """Move a servo to a pulse-width position (0.0-1.0)."""
        if servo is None:
            return
        try:
            # gpiozero PWMOutputDevice expects a value in [0.0, 1.0]
            servo.value = position
        except Exception as e:
            print(f"Warning: failed to set servo {servo.pin} to {position}: {e}", file=sys.stderr)

    def aim(self, targets):
        """Aim at each target in order, then return servos to neutral."""
        for i in targets:
            if i < 1 or i > self.b:
                print(f"Warning: target {i} out of range (1-{self.b}); skipping", file=sys.stderr)
                continue
            self._move_servo(self.h_servo, self.hp[i - 1])
            self._move_servo(self.v_servo, self.vp[i - 1])
            self.laser.on()
            time.sleep(self.ld)
            self.laser.off()
            self._move_servo(self.h_servo, 10)
            self._move_servo(self.v_servo, 10)
            time.sleep(self.sd / 2)
        self.laser.off()

    def close(self):
        """Release all hardware resources."""
        cleanup()


def main():
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        a = Aim(1.0, 0.5)
    except RuntimeError as e:
        print(f"Initialization error: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        targets = [2, 5, 8]
        a.aim(targets)
    except KeyboardInterrupt:
        print("\nAiming interrupted by user.")
    except Exception as e:
        print(f"Runtime error: {e}", file=sys.stderr)
    finally:
        cleanup()


if __name__ == "__main__":
    main()

