import signal
import sys
import time
import logging
from datetime import datetime

try:
    from gpiozero import OutputDevice
    from gpiozero.exc import GPIOZeroError, DeviceClosed
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero", file=sys.stderr)
    sys.exit(1)

# Configure logging
logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)
logger = logging.getLogger(__name__)

# Constants
VIBRATION_PIN = 17
VIBRATION_DURATION = 30  # seconds
ALARM_TIME = "21:14"

# Global flag for graceful shutdown
_running = True


def _signal_handler(signum, frame):
    """Handle SIGINT and SIGTERM for graceful shutdown."""
    global _running
    logger.info("Received signal %s, shutting down...", signum)
    _running = False


def activate_vibration(motor, duration):
    """Activates the vibration motor for a specified duration."""
    try:
        logger.info("Activating vibration motor for %d seconds...", duration)
        motor.on()
        time.sleep(duration)
    except DeviceClosed:
        logger.error("Motor device was closed unexpectedly during activation.")
    except GPIOZeroError as e:
        logger.error("GPIO error during activation: %s", e)
    except Exception as e:
        logger.error("Unexpected error during activation: %s", e)
    finally:
        try:
            motor.off()
            logger.info("Deactivating vibration motor.")
        except DeviceClosed:
            logger.warning("Motor device was closed during deactivation.")
        except Exception as e:
            logger.error("Error deactivating motor: %s", e)


def main():
    """Main function to control the vibration motor."""
    global _running

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    motor = None
    try:
        motor = OutputDevice(VIBRATION_PIN)
        logger.info("Vibration motor initialized on GPIO%d.", VIBRATION_PIN)

        while _running:
            now = datetime.now().strftime("%H:%M")
            if now == ALARM_TIME:
                activate_vibration(motor, VIBRATION_DURATION)
            else:
                logger.debug("Alarm not triggered (time: %s).", now)

            # Sleep in small increments to allow signal handler to interrupt promptly
            for _ in range(300):
                if not _running:
                    break
                time.sleep(1)

    except GPIOZeroError as e:
        logger.error("GPIO initialization error: %s", e)
    except Exception as e:
        logger.error("Unexpected error during initialization: %s", e)
    finally:
        if motor is not None:
            try:
                motor.off()
                motor.close()
                logger.info("Motor deactivated and GPIO resources released.")
            except DeviceClosed:
                logger.warning("Motor device was closed during cleanup.")
            except Exception as e:
                logger.error("Error during cleanup: %s", e)
        logger.info("Program terminated.")


if __name__ == "__main__":
    main()

