import time
import signal
import sys

try:
    from adafruit_servokit import ServoKit
except ImportError:
    print("Error: adafruit-circuitpython-servokit not installed. "
          "Install with: pip install adafruit-circuitpython-servokit")
    sys.exit(1)

# ---------------------------------------------------------------------------
# Constants
# ---------------------------------------------------------------------------
I2C_BUS = 1
PCA9685_ADDR = 0x40
SERVO_CHANNEL = 0
GRAB_ANGLE = 90
RELEASE_ANGLE = 150
STEP_DEG = 5
STEP_DELAY = 0.04

# ---------------------------------------------------------------------------
# Global state for signal handling
# ---------------------------------------------------------------------------
_kit = None
_running = True


def _cleanup():
    """Release servos and close the I2C bus on every exit path."""
    global _kit
    if _kit is not None:
        try:
            for ch in range(16):
                _kit.servo[ch].angle = None  # release the servo position
        except Exception:
            pass
        try:
            _kit.deinit()
        except Exception:
            pass
        _kit = None


def _signal_handler(signum, frame):
    """Handle SIGINT / SIGTERM for a clean shutdown."""
    global _running
    _running = False


def _validate_channel(channel):
    """Raise ValueError if channel is out of range."""
    if not isinstance(channel, int) or not (0 <= channel <= 15):
        raise ValueError(f"Invalid channel {channel}; must be 0-15.")


def _validate_angle(angle):
    """Raise ValueError if angle is out of range."""
    if not isinstance(angle, (int, float)) or not (0 <= angle <= 180):
        raise ValueError(f"Invalid angle {angle}; must be 0-180.")


def _move_servo_to(kit, channel, angle):
    """Move a servo to *angle* in 5-degree steps with a 0.04 s delay."""
    if not _running:
        raise RuntimeError("Shutdown requested; aborting move.")
    _validate_channel(channel)
    _validate_angle(angle)
    current = kit.servo[channel].angle
    if current is None:
        current = 0.0
    step = STEP_DEG if angle > current else -STEP_DEG
    angle = int(angle)
    while current != angle:
        current += step
        if current > angle:
            current = angle
        kit.servo[channel].angle = current
        time.sleep(STEP_DELAY)


def grab_object(kit, call=0):
    """Move channel 0 to GRAB_ANGLE (90°)."""
    _move_servo_to(kit, SERVO_CHANNEL, GRAB_ANGLE)


def release_object(kit, call=0):
    """Move channel 0 to RELEASE_ANGLE (150°)."""
    _move_servo_to(kit, SERVO_CHANNEL, RELEASE_ANGLE)


def move_servo(kit, call, target_angle):
    """Step channel 0 toward *target_angle* in 5-degree increments."""
    _move_servo_to(kit, SERVO_CHANNEL, target_angle)


def main():
    global _kit

    # Register signal handlers for clean shutdown
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    # Initialize the ServoKit on I2C bus 1 at the PCA9685 default address
    try:
        _kit = ServoKit(channels=16, i2c=None, address=PCA9685_ADDR)
    except OSError as exc:
        print(f"Error: cannot open I2C bus {I2C_BUS} (address 0x{PCA9685_ADDR:02X}): {exc}")
        print("        Ensure I2C is enabled (raspi-config) and the "
              "libgpiod-based backend is available.")
        sys.exit(1)
    except Exception as exc:
        print(f"Error: ServoKit initialization failed: {exc}")
        sys.exit(1)

    try:
        grab_object(_kit, call=0)
        if _running:
            move_servo(_kit, call, RELEASE_ANGLE)
        if _running:
            release_object(_kit, call=0)
    except (OSError, ValueError) as exc:
        print(f"Error: {exc}")
    except Exception as exc:
        print(f"Unexpected error: {exc}")
    finally:
        _cleanup()


if __name__ == "__main__":
    main()

