import logging
import signal
import sys

from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)

PUMP_PIN = 20
LIGHT_PIN = 21

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False
    logging.info("Signal %s received, shutting down.", signum)


def parse_intent(phrase):
    """Return the best intent string for a given phrase, case-insensitive."""
    intents = {"pump_on", "pump_off", "light_toggle"}
    lowered = phrase.lower()
    for intent in intents:
        if intent in lowered:
            return intent
    return None


def apply_intent(intent, pump, light):
    """Drive the pump and light according to the parsed intent."""
    if intent == "pump_on":
        pump.on()
        logging.info("Pump turned ON.")
    elif intent == "pump_off":
        pump.off()
        logging.info("Pump turned OFF.")
    elif intent == "light_toggle":
        light.toggle()
        logging.info("Light toggled.")
    else:
        logging.warning("Unknown intent: %s", intent)


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    pump = None
    light = None
    try:
        pump = OutputDevice(PUMP_PIN)
        light = OutputDevice(LIGHT_PIN)
        logging.info("Pump on BCM pin %d, light on BCM pin %d initialized.", PUMP_PIN, LIGHT_PIN)

        phrases = [
            "turn the pump on",
            "switch the light",
            "turn pump off",
            "unknown command",
        ]

        for phrase in phrases:
            if not _running:
                break
            intent = parse_intent(phrase)
            if intent:
                apply_intent(intent, pump, light)
            else:
                logging.warning("Could not parse phrase: %s", phrase)

    except GPIOZeroError as exc:
        logging.error("GPIO error: %s", exc)
    except Exception as exc:
        logging.error("Unexpected error: %s", exc)
    finally:
        if pump is not None:
            try:
                pump.off()
                pump.close()
            except Exception as exc:
                logging.error("Error closing pump: %s", exc)
        if light is not None:
            try:
                light.off()
                light.close()
            except Exception as exc:
                logging.error("Error closing light: %s", exc)
        logging.info("GPIO resources released. Exiting.")


if __name__ == "__main__":
    main()

