                GPIO.output(self.laser_pin, GPIO.HIGH)
                self.laser_open = True
            except Exception as e:
                print(f"Error turning laser on: {e}", file=sys.stderr)
        else:
            GPIO.output(self.laser_pin, GPIO.HIGH)

    def set_laser_off(self):
        if self.laser_open:
            try:
                GPIO.output(self.laser_pin, GPIO.LOW)
                self.laser_open = False
            except Exception as e:
                print(f"Error turning laser off: {e}", file=sys.stderr)
        else:
            GPIO.output(self.laser_pin, GPIO.LOW)

    def set_servo_position(self, position, servo_file):
        try:
            servo_file.write(f"0={position}\n")
            servo_file.flush()
        except IOError as e:
            print(f"Error writing to {servo_file}: {e}", file=sys.stderr)
            self.set_laser_off()

    def cleanup(self):
        try:
            if self.laser_open:
                GPIO.output(self.laser_pin, GPIO.LOW)
        except Exception:
            pass
        try:
            if hasattr(self, 'servo_h') and self.servo_h.fileno() > 0:
                self.servo_h.close()
            if hasattr(self, 'servo_v') and self.servo_v.fileno() > 0:
                self.servo_v.close()
        except Exception:
            pass
        try:
            GPIO.cleanup()
        except Exception:
            pass

    def __del__(self):
        self.cleanup()

