import signal
import sys
import threading

try:
    import spidev
except ImportError:
    print("Error: spidev library not found. Install with: pip install spidev", file=sys.stderr)
    sys.exit(1)

try:
    from eeprom import eeprom
except ImportError:
    print("Error: eeprom library not found. Install with: pip install eeprom", file=sys.stderr)
    sys.exit(1)


class EepromDemo:
    """
    Threaded SPI EEPROM read/write demo for Raspberry Pi using a 25LC040 (or
    compatible 4 Kb SPI EEPROM) on the board's SPI bus (SCK, MOSI, MISO) with
    chip‑select on D5.
    """

    def __init__(self, spi_bus=0, cs_pin=5, data_length=16, data_value=b'1234567890ABCDEF'):
        self.spi_bus = spi_bus
        self.cs_pin = cs_pin
        self.data_length = data_length
        self.data_value = data_value
        self.spi = None
        self.cs_pin_lock = threading.Lock()
        self.spi_lock = threading.Lock()
        self.demo_lock = threading.Lock()
        self.spi_thread = None
        self.read_thread = None
        self.is_running = False

    def initialize_spi(self):
        """Open the SPI bus and verify the chip select pin is accessible."""
        try:
            self.spi = spidev.SpiDev()
            self.spi.open(self.spi_bus, self.cs_pin)
            self.spi.max_speed_hz = 1000000
            self.spi.mode = 0
            self.spi.bits_per_word = 8
        except (IOError, OSError, PermissionError) as e:
            print(f"Error initializing SPI bus {self.spi_bus}, CS pin {self.cs_pin}: {e}", file=sys.stderr)
            self.spi = None
            return False
        return True

    def initialize_eeprom(self):
        """Instantiate the eeprom object with the SPI interface and CS pin."""
        if not self.spi:
            print("SPI not initialized; cannot instantiate eeprom.", file=sys.stderr)
            return None
        try:
            return eeprom(self.spi, self.cs_pin)
        except Exception as e:
            print(f"Error instantiating eeprom: {e}", file=sys.stderr)
            return None

    def write_data(self, data):
        """Write data to the EEPROM in a separate thread with thread-safety."""
        if not self.spi:
            print("SPI not initialized; cannot write.", file=sys.stderr)
            return
        with self.spi_lock:
            if not self.spi:
                print("SPI not initialized; cannot write.", file=sys.stderr)
                return
            try:
                with self.cs_pin_lock:
                    self.spi.writebytes(list(data))
            except (IOError, OSError) as e:
                print(f"Error writing to EEPROM: {e}", file=sys.stderr)

    def read_data(self):
        """Read data from the EEPROM in a separate thread with thread-safety."""
        if not self.spi:
            print("SPI not initialized; cannot read.", file=sys.stderr)
            return None
        with self.spi_lock:
            if not self.spi:
                print("SPI not initialized; cannot read.", file=sys.stderr)
                return None
            try:
                with self.cs_pin_lock:
                    return self.spi.readbytes(self.data_length)
            except (IOError, OSError) as e:
                print(f"Error reading from EEPROM: {e}", file=sys.stderr)
                return None

    def run_demo(self):
        """Run the threaded read/write demo with clean shutdown on signals."""
        if not self.initialize_spi():
            return
        self.eeprom = self.initialize_eeprom()
        if not self.eeprom:
            self.cleanup()
            return

        self.is_running = True
        self.write_thread = threading.Thread(target=self.write_data, args=(self.data_value,), daemon=True)
        self.read_thread = threading.Thread(target=self.read_data, daemon=True)

        self.write_thread.start()
        self.read_thread.start()

        self.wait_for_threads_to_complete()

    def wait_for_threads_to_complete(self):
        """Wait for the write and read threads to finish, checking for signals."""
        while self.is_running:
            if self.read_thread.is_alive():
                self.read_thread.join(timeout=0.5)
            if self.write_thread.is_alive():
                self.write_thread.join(timeout=0.5)
            if self.is_running:
                time.sleep(0.1)

    def cleanup(self):
        """Deinitialize SPI and release the CS pin cleanly."""
        self.is_running = False
        if self.spi_thread is not None and self.spi_thread.is_alive():
            self.spi_thread.join(timeout=2.0)
        if self.read_thread is not None and self.read_thread.is_alive():
