    global running
    running = False

def read_radiation_level(ser):
    try:
        raw = ser.readline()
        if not raw:
            return None
        return raw.decode('ascii', errors='replace').strip()
    except serial.SerialException as e:
        print(f"Serial read error: {e}", file=sys.stderr)
        return None

def parse_radiation(raw):
    try:
        return float(raw)
    except ValueError:
        return None

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        ser = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT)
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        while running:
            radiation = read_radiation_level(ser)
            if radiation is not None:
                level = parse_radiation(radiation)
                if level is not None:
                    print(f"Radiation Level: {level:.2f} µSv/h")
                    if level > RADIATION_THRESHOLD:
                        GPIO.output(GPIO_PIN, GPIO.HIGH)
