import serial
import time
import signal
import sys
import RPi.GPIO as GPIO

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
SERIAL_TIMEOUT = 1
ALARM_PIN = 17
FLOW_THRESHOLD = 10.0
POLL_INTERVAL = 1.0

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def initialize_serial(port, baud, timeout):
    try:
        ser = serial.Serial(port, baud, timeout=timeout)
        ser.reset_input_buffer()
        return ser
    except serial.SerialException as e:
        print(f"Error opening serial port {port}: {e}", file=sys.stderr)
        return None
    except OSError as e:
        print(f"OS error opening serial port {port}: {e}", file=sys.stderr)
        return None

def read_flow_data(ser):
    try:
        raw = ser.readline()
        if not raw:
            return None
        line = raw.decode('ascii', errors='replace').strip()
        if not line:
            return None
        return float(line)
    except ValueError:
        print(f"Invalid data received (not numeric): {line!r}", file=sys.stderr)
        return None
    except serial.SerialException as e:
        print(f"Serial read error: {e}", file=sys.stderr)
        return None
    except OSError as e:
        print(f"OS read error: {e}", file=sys.stderr)
        return None

def control_alarm(pin, flow_rate, threshold):
    if flow_rate > threshold:
        GPIO.output(pin, GPIO.HIGH)
    else:
        GPIO.output(pin, GPIO.LOW)

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    GPIO.setmode(GPIO.BCM)
    GPIO.setup(ALARM_PIN, GPIO.OUT, initial=GPIO.LOW)

    ser = initialize_serial(SERIAL_PORT, BAUD_RATE, SERIAL_TIMEOUT)
    if ser is None:
        print("Failed to initialize serial communication. Exiting.", file=sys.stderr)
        GPIO.cleanup()
        sys.exit(1)

    try:
        while _running:
            flow_rate = read_flow_data(ser)
            if flow_rate is not None:
                print(f"Flow Rate: {flow_rate:.2f} L/min")
                control_alarm(ALARM_PIN, flow_rate, FLOW_THRESHOLD)
            time.sleep(POLL_INTERVAL)
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        if ser and ser.is_open:
            ser.close()
            print("Serial port closed.")
        GPIO.cleanup()
        print("GPIO cleaned up.")

if __name__ == "__main__":
    main()

