import serial
import time
import signal
import sys
from datetime import datetime

# Configuration
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1
LOG_FILE = 'gps_coordinates_log.txt'

# Global flag for graceful shutdown
running = True

def signal_handler(sig, frame):
    """Handle SIGINT/SIGTERM for graceful shutdown."""
    global running
    running = False

def initialize_serial(port, baudrate, timeout):
    """Initializes the serial connection to the GPS module."""
    try:
        ser = serial.Serial(port, baudrate, timeout=timeout)
        return ser
    except serial.SerialException as e:
        print(f"Error initializing serial port: {e}", file=sys.stderr)
        return None

def read_gps_data(serial_port):
    """Reads a line of data from the serial port and returns it as a string."""
    try:
        data = serial_port.readline().decode('ascii', errors='replace').strip()
        return data
    except serial.SerialException as e:
        print(f"Error reading from serial port: {e}", file=sys.stderr)
        return None

def parse_gps_data(data):
    """Parses the GPS data string and returns a dictionary with latitude, longitude, and altitude."""
    if not data:
        return None

    if data.startswith('$GPGGA'):
        parts = data.split(',')
        if len(parts) >= 14:
            # Check for valid fix quality (1 = valid, 0 = invalid)
            if parts[2] == '1':
                lat = parts[3]
                lon = parts[5]
                alt = parts[7]
                return {'latitude': lat, 'longitude': lon, 'altitude': alt}
            else:
                print("Warning: GPS fix is invalid (quality=0). Skipping.")
                return None
    return None

def log_coordinates(coordinates, log_file):
    """Logs the GPS coordinates to a file with an ISO 8601 timestamp."""
    timestamp = datetime.now().isoformat()
    log_entry = f"{timestamp} - Latitude: {coordinates['latitude']}, Longitude: {coordinates['longitude']}, Altitude: {coordinates['altitude']}\n"
    try:
        with open(log_file, 'a') as f:
            f.write(log_entry)
    except IOError as e:
        print(f"Error writing to log file: {e}", file=sys.stderr)

def print_coordinates(coordinates):
    """Prints the GPS coordinates to the console."""
    if coordinates:
        print(f"Latitude: {coordinates['latitude']}, Longitude: {coordinates['longitude']}, Altitude: {coordinates['altitude']}")

def main():
    """Main function to read, parse, and log GPS data."""
    global running

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    serial_connection = initialize_serial(SERIAL_PORT, BAUD_RATE, TIMEOUT)
    if serial_connection is None:
        print("Failed to initialize serial connection. Exiting.", file=sys.stderr)
        sys.exit(1)

    try:
        while running:
            gps_data = read_gps_data(serial_connection)
            if gps_data:
                parsed_data = parse_gps_data(gps_data)
                if parsed_data:
                    print_coordinates(parsed_data)
                    log_coordinates(parsed_data, LOG_FILE)
            time.sleep(0.1)  # Reduce CPU usage

    except Exception as e:
        print(f"An unexpected error occurred: {e}", file=sys.stderr)
    finally:
        if serial_connection and serial_connection.is_open:
            serial_connection.close()
            print("Serial port closed.")

if __name__ == "__main__":
    main()

