import logging
import signal
import sys
import time
from dataclasses import dataclass
from typing import Optional, Tuple

import serial

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)

UART_DEVICE = "/dev/serial0"
BAUDRATE = 9600
TIMEOUT = 1

@dataclass
class GPS_readings:
    latitude: Optional[float] = None
    longitude: Optional[float] = None
    altitude: Optional[float] = None
    satellite_count: Optional[int] = None


class GPSReader:
    """
    Reads and parses NMEA GPGGA sentences from a GPS module connected over UART.
    """

    def __init__(self, device: str = UART_DEVICE, baudrate: int = BAUDRATE, timeout: float = TIMEOUT):
        self.device = device
        self.baudrate = baudrate
        self.timeout = timeout
        self.uart: Optional[serial.Serial] = None
        self._closed = False

    def connect(self) -> None:
        """Open the UART device. Raises on failure."""
        try:
            self.uart = serial.Serial(
                port=self.device,
                baudrate=self.baudrate,
                bytesize=serial.EIGHTBITS,
                parity=serial.PARITY_NONE,
                stopbits=serial.STOPBITS_ONE,
                timeout=self.timeout,
            )
            logging.info("Connected to GPS on %s at %d baud.", self.device, self.baudrate)
        except serial.SerialException as exc:
            logging.error("Failed to open %s: %s", self.device, exc)
            raise

    def disconnect(self) -> None:
        """Close the UART device. Idempotent and safe to call multiple times."""
        if self._closed:
            return
        if self.uart is not None:
            try:
                if self.uart.is_open:
                    self.uart.close()
                    logging.info("Closed UART device %s.", self.device)
            except serial.SerialException as exc:
                logging.error("Error closing UART: %s", exc)
            finally:
                self.uart = None
                self._closed = True

    def read_gps_data(self) -> Optional[GPS_readings]:
        """
        Read one line from the UART and parse a GPGGA sentence.
        Returns a GPS_readings object or None on timeout/error/invalid data.
        """
        if self.uart is None or not self.uart.is_open:
            logging.error("UART not open; cannot read.")
            return None

        try:
            raw = self.uart.readline()
        except serial.SerialException as exc:
            logging.error("UART read error: %s", exc)
            return None

        if not raw:
            return None  # timeout, no data

        try:
            line = raw.decode("ascii", errors="replace").strip()
        except Exception as exc:
            logging.error("Decode error: %s", exc)
            return None

        if not line.startswith("$GPGGA"):
            return None

        return self._parse_gpgga(line)

    def _parse_gpgga(self, line: str) -> GPS_readings:
        """
        Parse a GPGGA sentence and return a GPS_readings object.
        Returns None on any parse or conversion error.
