        except ValueError:
            logging.error("Invalid fix quality field: %r", parts[6])
            return None

        if fix_quality == 0:
            logging.debug("No fix (quality=0); skipping.")
            return None

        try:
            lat = self._to_decimal(parts[2], parts[3])
            lon = self._to_decimal(parts[4], parts[5])
        except (IndexError, ValueError) as exc:
            logging.error("Invalid latitude/longitude fields: %s", exc)
            return None

        altitude = float(parts[9]) if parts[9] else None
        satellite_count = int(parts[10]) if parts[10] else None

