    global _serial_port
    if _serial_port is not None and _serial_port.is_open:
        try:
            _serial_port.close()
            print('Serial port closed.')
        except Exception as e:
            print(f'Error closing serial port: {e}')
    _serial_port = None


def _read_pulse_oximeter_data(ser):
    try:
        raw = ser.readline()
        if not raw:
            return None
        return raw.decode('ascii', errors='replace').strip()
    except serial.SerialException as e:
        print(f'Serial communication error: {e}')
        return None
    except Exception as e:
        print(f'Unexpected error reading data: {e}')
        return None


def _parse_data(data):
    if not data:
        return None, None
    try:
        heart_rate, spo2 = data.split(',')
        return int(heart_rate), int(spo2)
    except ValueError:
        print(f'Invalid data format received: {data}')
        return None, None


