            item = next((it for it in data_store if it["id"] == item_id), None)
            if item is None:
                self._send_json([])
            else:
                self._send_json([item])

    def _handle_delete(self, req: dict) -> None:
        item_id = req.get("id")
        if item_id is None:
            self._send_json([])
        else:
            data_store = [it for it in data_store if it["id"] != item_id]
            self._send_json(data_store)

    def _send_json(self, data: list) -> None:
        body = (
            "{\n"
            "  'data': [\n"
            f"{'  {item["id"]}: {{ 'name': '{item['name']}', 'done': {int(item['done'])}}' if isinstance(item, dict) else f'\"{item}\"' for item in data}\n"
            "  ]\n"
            "}\n"
        )
        self._send_header("Content-Type", "application/json")
        self._send_header("Access-Control-Allow-Origin", "*")
        self._end_headers()
        self.wfile.write(body.encode("utf-8"))

    def _send_header(self, header: str, value: str) -> None:
        self.send_response(200)
        self.send_header(header, value)

    def _send_response(self, status: int, reason: str = "OK") -> None:
        self.send_response(status)
        self.send_header("Content-Type", "text/plain")
        self.end_headers()
        self.wfile.write(reason.encode("utf-8"))

    def log_message(self, fmt: str, *args) -> None:
        pass  # suppress default logging

    def _handle_error(self, status: int, reason: str = "Internal Server Error") -> None:
        self._send_json({"error": reason})
        self.wfile.write(f"HTTP/1.1 {status} {reason}\r\n".encode("utf-8"))
        self.wfile.write(b"\r\n")


class ThreadedHTTPServer(HTTPServer):
    """HTTPServer with a thread pool for concurrent requests."""

    allow_reuse_address = True
    daemon_threads = True

    def __init__(self, addr, handler_class=DataHandler, timeout_interval=1.0):
        super().__init__(addr, handler_class)
        self.timeout_interval = timeout_interval
        self.thread_count = 5
        self.thread_list = []
        self._stop_event = threading.Event()

    def _serve_forever(self):
        while not self._stop_event.is_set():
            self.handle_request()
            self._stop_event.wait(self.timeout_interval)

    def _start_threads(self, n: int):
        for _ in range(n):
            t = threading.Thread(target=self._serve_forever, daemon=True)
            t.start()
            self.thread_list.append(t)

    def _stop_threads(self):
        for t in self.thread_list:
            t.join(timeout=2)
            if t.is_alive():
                t.join(timeout=1)
        self.thread_list.clear()

    def _handle_request(self):
        self._serve_forever()

    def _stop(self):
        self._stop_event.set()
        self._stop_threads()
        super().serve_forever()


# ---------------------------------------------------------------------------
# Signal handling
# ---------------------------------------------------------------------------
_server: ThreadedHTTPServer | None = None


def _signal_handler(signum, frame):
    print(f"\nReceived signal {signum}, shutting down...")
    if _server is not None:
        _server.close()
    sys.exit(0)


# ---------------------------------------------------------------------------
# Main
# ---------------------------------------------------------------------------
def main() -> None:
    global _server
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    uart = open_uart(SERIAL_PORT, BAUD_RATE, SERIAL_TIMEOUT)
    if uart is None:
        print("Failed to open UART. Exiting.", file=sys.stderr)
        sys.exit(1)

    _server = ThreadedHTTPServer(
        WEB_PORT, DataHandler, timeout_interval=SERIAL_TIMEOUT
    )
    _server.timeout_interval = SERIAL_TIMEOUT

    try:
        _server.serve_forever()
    except Exception:
        traceback.print_exc()
    finally:
        if uart is not None and uart.is_open:
            uart.close()
            print("UART closed.")
        if _server is not None:
            _server.close()
            print("Web server closed.")


if __name__ == "__main__":
    main()

