import serial
import time
import signal
import sys

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1
LOG_FILE = 'access_log.txt'

running = True

def signal_handler(signum, frame):
    global running
    running = False

def log_access_event(tag_id):
    timestamp = time.strftime('%Y-%m-%d %H:%M:%S')
    log_entry = f'{timestamp} – RFID Tag: {tag_id}\n'
    try:
        with open(LOG_FILE, 'a') as log_file:
            log_file.write(log_entry)
            log_file.flush()
    except OSError as e:
        print(f'Error writing to log file: {e}', file=sys.stderr)

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        ser = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT)
    except serial.SerialException as e:
        print(f'Error opening serial port {SERIAL_PORT}: {e}', file=sys.stderr)
        sys.exit(1)

    try:
        while running:
            try:
                raw = ser.readline()
                if not raw:
                    continue
                line = raw.decode('ascii', errors='replace').strip()
                if line:
                    tag_id = line.split(' ')[1] if ' ' in line else line
                    log_access_event(tag_id)
                    print(f'Access granted for RFID Tag: {tag_id}')
            except serial.SerialException as e:
                print(f'Serial communication error: {e}', file=sys.stderr)
                break
            except Exception as e:
                print(f'Unexpected error: {e}', file=sys.stderr)
                break
    finally:
        if ser.is_open:
            ser.close()
            print('Serial port closed.')

if __name__ == '__main__':
    main()

