import serial
import time
import sys

PORT = '/dev/ttyUSB0'
BAUD = 9600
TIMEOUT_S = 1
READ_DELAY_S = 1

def open_serial_port(port: str, baud: int) -> serial.Serial:
    """Open and return a serial port, raising serial.SerialException on failure."""
    return serial.Serial(
        port=port,
        baudrate=baud,
        bytesize=serial.EIGHTBITS,
        parity=serial.PARITY_NONE,
        stopbits=serial.STOPBITS_ONE,
        timeout=TIMEOUT_S,
    )

def read_pulse_oximeter_data(ser: serial.Serial) -> list:
    """Read one line from the serial port and return a list of two decoded floats."""
    raw = ser.readline()
    if not raw:
        return []
    line = raw.decode('ascii', errors='replace').strip()
    if not line:
        return []
    parts = line.split(',')
    if len(parts) != 2:
        raise ValueError(f"Expected 2 fields, got {len(parts)}: '{line}'")
    heart_rate, spo2 = parts
    return [float(heart_rate), float(spo2)]

def print_pulse_oximeter_data(heart_rate: float, spo2: float) -> None:
    """Print the heart rate and SpO2 in the required format."""
    print(f"Heart Rate: {heart_rate} bpm, SpO2: {spo2} %")

def main() -> None:
    ser = None
    try:
        ser = open_serial_port(PORT, BAUD)
        print(f"Connected to {PORT} @ {BAUD} baud. Press Ctrl+C to stop.")
        while True:
            try:
                data = read_pulse_oximeter_data(ser)
                if data:
                    print_pulse_oximeter_data(*data)
            except ValueError as e:
                print(f"Error: {e}", file=sys.stderr)
            time.sleep(READ_DELAY_S)
    except serial.SerialException as e:
        print(f"Serial port error: {e}", file=sys.stderr)
        sys.exit(1)
    except KeyboardInterrupt:
        print("\nExiting program.")
    finally:
        if ser is not None and ser.is_open:
            ser.close()
            print("Serial port closed.")

if __name__ == '__main__':
    main()

